// A cute pastel scooter to zip around the island on.
import * as THREE from "three";

const mat = (color, extra = {}) => new THREE.MeshStandardMaterial({ color, flatShading: true, roughness: 0.55, ...extra });

export const SCOOTER_COLORS = ["#ff8fb1", "#8fd3f0", "#b79be8", "#ffd166", "#8fd3b6"];
export const SEAT_H = 0.88; // the top of the seat

export function makeScooter(color = "#ff8fb1") {
  const root = new THREE.Group();
  const lean = new THREE.Group();
  root.add(lean);
  const body = mat(color);
  const cream = mat("#fff7f2");
  const dark = mat("#2b2633", { roughness: 0.8 });
  const chrome = mat("#e8e8f0", { metalness: 0.6, roughness: 0.3 });
  const add = (geo, m, x, y, z, rx = 0, ry = 0, rz = 0) => {
    const mesh = new THREE.Mesh(geo, m);
    mesh.position.set(x, y, z);
    mesh.rotation.set(rx, ry, rz);
    mesh.castShadow = true;
    lean.add(mesh);
    return mesh;
  };
  // rounded body and floorboard
  const shell = add(new THREE.SphereGeometry(0.42, 12, 8), body, 0, 0.5, -0.32);
  shell.scale.set(0.9, 0.75, 1.25);
  add(new THREE.BoxGeometry(0.42, 0.1, 0.8), cream, 0, 0.3, 0.12);
  // seat
  const seat = add(new THREE.CapsuleGeometry(0.15, 0.42, 3, 8), mat("#7a4a3a"), 0, 0.78, -0.3, Math.PI / 2);
  seat.scale.set(1.2, 1, 0.75);
  // front shield and steering column
  const shield = add(new THREE.SphereGeometry(0.3, 10, 8, 0, Math.PI * 2, 0, Math.PI / 2), body, 0, 0.55, 0.55, -Math.PI / 2 + 0.25);
  shield.scale.set(0.95, 1.5, 0.5);
  add(new THREE.CylinderGeometry(0.04, 0.04, 0.6, 6), chrome, 0, 0.76, 0.55, -0.22);
  // handlebars
  const bars = new THREE.Group();
  bars.position.set(0, 1.04, 0.5);
  lean.add(bars);
  const bar = new THREE.Mesh(new THREE.CylinderGeometry(0.025, 0.025, 0.62, 6), chrome);
  bar.rotation.z = Math.PI / 2;
  bars.add(bar);
  for (const s of [-1, 1]) {
    const grip = new THREE.Mesh(new THREE.CylinderGeometry(0.035, 0.035, 0.12, 6), dark);
    grip.rotation.z = Math.PI / 2;
    grip.position.x = s * 0.33;
    bars.add(grip);
    const mirror = new THREE.Mesh(new THREE.SphereGeometry(0.06, 8, 6), chrome);
    mirror.position.set(s * 0.28, 0.2, -0.02);
    mirror.scale.z = 0.4;
    bars.add(mirror);
  }
  // headlight
  const lamp = new THREE.Mesh(new THREE.SphereGeometry(0.09, 10, 8), new THREE.MeshStandardMaterial({ color: "#fff8d8", emissive: "#fff2b0", emissiveIntensity: 1.2 }));
  lamp.position.set(0, 0.92, 0.66);
  lamp.scale.z = 0.6;
  lean.add(lamp);
  // a heart on the front
  const heart = add(new THREE.IcosahedronGeometry(0.07, 0), mat("#e2557f"), 0, 0.72, 0.78);
  heart.scale.set(1.2, 1, 0.5);
  // wheels
  const wheels = [];
  for (const z of [0.62, -0.62]) {
    const w = new THREE.Group();
    w.position.set(0, 0.2, z);
    lean.add(w);
    const tyre = new THREE.Mesh(new THREE.TorusGeometry(0.16, 0.07, 6, 14), dark);
    tyre.rotation.y = Math.PI / 2;
    tyre.castShadow = true;
    w.add(tyre);
    const hub = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.08, 0.1, 8), cream);
    hub.rotation.z = Math.PI / 2;
    w.add(hub);
    wheels.push(w);
  }
  // little back basket with a flower
  add(new THREE.BoxGeometry(0.34, 0.16, 0.26), mat("#c9a27e"), 0, 0.95, -0.78);
  add(new THREE.IcosahedronGeometry(0.07, 0), mat("#ffd166"), 0.06, 1.08, -0.78);
  add(new THREE.IcosahedronGeometry(0.06, 0), mat("#fff7f2"), -0.07, 1.06, -0.74);
  return { root, lean, wheels, bars };
}

// spin the wheels and lean into turns
export function animateScooter(s, dt, speed, turn) {
  for (const w of s.wheels) w.rotation.x += (speed * dt) / 0.2;
  const want = THREE.MathUtils.clamp(-turn * speed * 0.06, -0.35, 0.35);
  s.lean.rotation.z += (want - s.lean.rotation.z) * Math.min(1, dt * 6);
  s.bars.rotation.y += (THREE.MathUtils.clamp(turn * 0.6, -0.5, 0.5) - s.bars.rotation.y) * Math.min(1, dt * 8);
}

// ---- a unicorn for two: summon it, ride it, and your person can hop on behind ----
export const UNI_SEAT_H = 1.32; // the top of the saddle
export const UNI_FRONT = 0.08; // where the rider sits, along the back
export const UNI_BACK = -0.48; // and the one holding on behind
const RAINBOW = ["#ff8fb1", "#ffb36b", "#ffe07a", "#9fe0a6", "#8fd3f0", "#b79be8"];

export function makeUnicorn() {
  const root = new THREE.Group();
  const lean = new THREE.Group();
  root.add(lean);
  const bob = new THREE.Group();
  lean.add(bob);
  const coat = mat("#fffafc", { roughness: 0.7 });
  const blush = mat("#ffc2da");
  const hoof = mat("#d9b8ff", { roughness: 0.5 });
  const gold = mat("#ffd36b", { metalness: 0.5, roughness: 0.3, emissive: "#ffb000", emissiveIntensity: 0.25 });
  const dark = mat("#2b2633");
  const part = (parent, geo, m, x, y, z, rx = 0, ry = 0, rz = 0) => {
    const mesh = new THREE.Mesh(geo, m);
    mesh.position.set(x, y, z);
    mesh.rotation.set(rx, ry, rz);
    mesh.castShadow = true;
    parent.add(mesh);
    return mesh;
  };
  // body
  const body = part(bob, new THREE.CapsuleGeometry(0.36, 0.78, 4, 12), coat, 0, 0.95, -0.05, Math.PI / 2);
  body.scale.set(1, 1, 0.92);
  // a long saddle with room for two
  const saddle = part(bob, new THREE.CapsuleGeometry(0.2, 0.62, 3, 10), mat("#ff8fb1"), 0, 1.25, -0.2, Math.PI / 2);
  saddle.scale.set(1.25, 1, 0.45);
  part(bob, new THREE.TorusGeometry(0.33, 0.035, 5, 16, Math.PI), gold, 0, 0.98, 0.2, 0, Math.PI / 2, 0);
  // neck and head
  const neck = new THREE.Group();
  neck.position.set(0, 1.12, 0.48);
  bob.add(neck);
  part(neck, new THREE.CylinderGeometry(0.17, 0.24, 0.62, 10), coat, 0, 0.24, 0.1, 0.5);
  const head = new THREE.Group();
  head.position.set(0, 0.56, 0.3);
  neck.add(head);
  const skull = part(head, new THREE.SphereGeometry(0.24, 12, 10), coat, 0, 0, 0);
  skull.scale.set(0.9, 1, 1.1);
  part(head, new THREE.SphereGeometry(0.16, 10, 8), blush, 0, -0.08, 0.22).scale.set(1, 0.85, 1);
  for (const s of [-1, 1]) {
    part(head, new THREE.SphereGeometry(0.045, 8, 6), dark, s * 0.15, 0.05, 0.15);
    part(head, new THREE.SphereGeometry(0.035, 6, 4), blush, s * 0.17, -0.06, 0.15);
    part(head, new THREE.ConeGeometry(0.06, 0.18, 5), coat, s * 0.1, 0.24, -0.05, 0, 0, -s * 0.25);
  }
  // the horn, spiralled in gold
  const horn = part(head, new THREE.ConeGeometry(0.06, 0.42, 8), gold, 0, 0.36, 0.08, 0.35);
  const sparkle = new THREE.Mesh(new THREE.IcosahedronGeometry(0.05, 0), new THREE.MeshStandardMaterial({ color: "#ffffff", emissive: "#fff2b0", emissiveIntensity: 1.5 }));
  sparkle.position.set(0, 0.25, 0);
  horn.add(sparkle);
  // rainbow mane down the neck and a rainbow tail
  const mane = [];
  RAINBOW.forEach((c, i) => {
    const t = i / (RAINBOW.length - 1);
    const m = part(neck, new THREE.IcosahedronGeometry(0.11 - t * 0.02, 0), mat(c), 0, 0.62 - t * 0.55, -0.02 - t * 0.12);
    m.scale.set(0.8, 1, 1.3);
    mane.push(m);
  });
  const tail = new THREE.Group();
  tail.position.set(0, 1.05, -0.62);
  bob.add(tail);
  RAINBOW.forEach((c, i) => {
    const m = part(tail, new THREE.IcosahedronGeometry(0.12 - i * 0.008, 0), mat(c), 0, -0.08 - i * 0.1, -0.08 - i * 0.05);
    m.scale.set(0.8, 1.2, 0.8);
  });
  // four legs that gallop
  const legs = [];
  for (const [x, z, ph] of [[-0.18, 0.38, 0], [0.18, 0.38, Math.PI], [-0.18, -0.42, Math.PI * 0.5], [0.18, -0.42, Math.PI * 1.5]]) {
    const leg = new THREE.Group();
    leg.position.set(x, 0.8, z);
    bob.add(leg);
    part(leg, new THREE.CylinderGeometry(0.08, 0.065, 0.66, 8), coat, 0, -0.33, 0);
    part(leg, new THREE.CylinderGeometry(0.085, 0.09, 0.12, 8), hoof, 0, -0.72, 0.01);
    legs.push({ g: leg, ph });
  }
  return { root, lean, bob, legs, head, neck, tail, mane, sparkle, isUnicorn: true, phase: 0 };
}

// gallop, toss the head and swish the tail
export function animateUnicorn(u, dt, speed, turn) {
  const s = Math.abs(speed);
  u.phase += dt * (2 + s * 1.15);
  const k = Math.min(1, s / 3);
  for (const l of u.legs) l.g.rotation.x = Math.sin(u.phase + l.ph) * 0.75 * k;
  u.bob.position.y = Math.abs(Math.sin(u.phase)) * 0.08 * k + Math.sin(u.phase * 0.35) * 0.015 * (1 - k);
  u.neck.rotation.x = Math.sin(u.phase) * 0.08 * k;
  u.tail.rotation.x = 0.3 + Math.sin(u.phase * 0.8) * 0.15 + k * 0.4;
  u.tail.rotation.y = Math.sin(u.phase * 0.6) * 0.3;
  u.sparkle.rotation.y += dt * 3;
  const want = THREE.MathUtils.clamp(-turn * s * 0.05, -0.3, 0.3);
  u.lean.rotation.z += (want - u.lean.rotation.z) * Math.min(1, dt * 6);
  u.head.rotation.y += (THREE.MathUtils.clamp(turn * 0.4, -0.4, 0.4) - u.head.rotation.y) * Math.min(1, dt * 6);
}
