// Keyboard + mouse on desktop; a floating joystick, drag-to-look and pinch
// on phones. Produces a move vector and camera angles for the game loop.
export class Controls {
  constructor({ canvas, zone, joystick, knob, handlers }) {
    this.canvas = canvas;
    this.handlers = handlers;
    this.keys = new Set();
    this.enabled = true;
    this.yaw = Math.PI;
    this.pitch = 0.38;
    this.dist = 8;
    this.joy = { x: 0, y: 0, id: null };
    this.pointers = new Map();
    this.pinch = 0;
    this.jumpQueued = 0;
    this.jumpHeld = false;
    this.sens = 1;
    this.lockMode = false;
    // with the rifle on a desktop, the mouse is captured for aiming
    this.onLockedMove = (e) => {
      if (document.pointerLockElement !== canvas || !this.enabled) return;
      this.yaw -= e.movementX * 0.0026 * this.sens;
      this.pitch = Math.min(1.35, Math.max(-0.9, this.pitch + e.movementY * 0.002 * this.sens));
    };
    document.addEventListener("mousemove", this.onLockedMove);

    this.onKeyDown = (e) => {
      if (this.isTyping(e)) return;
      const k = e.key.toLowerCase();
      if (!this.enabled) {
        if (k === "escape") handlers.escape?.();
        return;
      }
      if (["arrowup", "arrowdown", "arrowleft", "arrowright", " "].includes(k)) e.preventDefault();
      if (!e.repeat) {
        if (k === "e" || k === "enter") handlers.interact?.();
        if (k === " ") this.pressJump();
        if (k === "1") handlers.emote?.("wave");
        if (k === "2") handlers.emote?.("heart");
        if (k === "3") handlers.emote?.("dance");
        if (k === "4") handlers.emote?.("poop");
        if (k === "5") handlers.emote?.("kiss");
        if (k === "6") handlers.emote?.("cuddle");
        if (k === "t" || k === "/") {
          e.preventDefault();
          handlers.chat?.();
        }
        if (k === "v") handlers.voice?.();
        if (k === "k") handlers.camera?.();
        if (k === "r") handlers.ride?.();
        if (k === "u") handlers.unicorn?.();
        if (k === "p") handlers.petStay?.();
        if (k === "n") handlers.time?.();
        if (k === "g") handlers.gun?.();
        if (k === "f") handlers.fire?.();
        if (k === "m") handlers.travel?.();
        if (k === "c") handlers.avatar?.();
        if (k === "h" || k === "?") handlers.help?.();
        if (k === "escape") handlers.escape?.();
      }
      this.keys.add(k);
    };
    this.onKeyUp = (e) => {
      const k = e.key.toLowerCase();
      this.keys.delete(k);
      if (k === " ") this.releaseJump();
    };
    this.onBlur = () => {
      this.keys.clear();
      this.releaseJump();
    };
    window.addEventListener("keydown", this.onKeyDown);
    window.addEventListener("keyup", this.onKeyUp);
    window.addEventListener("blur", this.onBlur);

    // look around / tap on the 3D view
    canvas.addEventListener("pointerdown", (e) => {
      if (!this.enabled) return;
      if (this.lockMode && e.pointerType === "mouse") return; // handled by mousedown
      if (e.button === 2) handlers.scope?.(true);
      try {
        canvas.setPointerCapture(e.pointerId);
      } catch {}
      this.pointers.set(e.pointerId, { x: e.clientX, y: e.clientY, t: performance.now(), moved: 0 });
      if (this.pointers.size === 2) this.pinch = this.pinchDistance();
    });
    canvas.addEventListener("pointermove", (e) => {
      const p = this.pointers.get(e.pointerId);
      if (!p) return;
      const dx = e.clientX - p.x;
      const dy = e.clientY - p.y;
      p.x = e.clientX;
      p.y = e.clientY;
      p.moved += Math.abs(dx) + Math.abs(dy);
      if (this.pointers.size === 2) {
        const d = this.pinchDistance();
        if (this.pinch) this.zoom(this.pinch / d);
        this.pinch = d;
        return;
      }
      if (p.moved > 6) {
        const touch = e.pointerType === "touch";
        // the free photo camera turns slower, like a head, not an orbit
        const k = this.sens * (this.lookScale || 1);
        this.yaw -= dx * (touch ? 0.009 : 0.0055) * k;
        this.pitch = Math.min(1.35, Math.max(-0.9, this.pitch + dy * (touch ? 0.006 : 0.0045) * k));
      }
    });
    const end = (e) => {
      if (e.button === 2) handlers.scope?.(false);
      const p = this.pointers.get(e.pointerId);
      if (!p) return;
      this.pointers.delete(e.pointerId);
      if (this.pointers.size < 2) this.pinch = 0;
      if (e.type === "pointerup" && e.button !== 2 && p.moved < 10 && performance.now() - p.t < 450) handlers.tap?.(e.clientX, e.clientY);
    };
    canvas.addEventListener("pointerup", end);
    canvas.addEventListener("pointercancel", end);
    canvas.addEventListener("contextmenu", (e) => e.preventDefault());
    // pointer events skip a second button pressed while one is held, so the
    // rifle listens to mouse buttons directly: hold right to zoom, left to shoot
    canvas.addEventListener("mousedown", (e) => {
      if (!this.lockMode || !this.enabled) return;
      if (document.pointerLockElement !== canvas) {
        try {
          canvas.requestPointerLock?.()?.catch?.(() => {});
        } catch {}
        // the first right click both grabs the mouse and zooms
        if (e.button === 2) handlers.scope?.(true);
        return;
      }
      if (e.button === 0) handlers.fire?.();
      if (e.button === 2) handlers.scope?.(true);
    });
    canvas.addEventListener("mouseup", (e) => {
      if (this.lockMode && e.button === 2) handlers.scope?.(false);
    });
    canvas.addEventListener(
      "wheel",
      (e) => {
        e.preventDefault();
        if (this.enabled) this.zoom(1 + Math.sign(e.deltaY) * Math.min(0.25, Math.abs(e.deltaY) * 0.0015));
      },
      { passive: false },
    );

    // floating joystick: it appears where the thumb lands in the zone
    const R = 48;
    const setKnob = () => {
      knob.style.transform = `translate(${this.joy.x * R}px, ${-this.joy.y * R}px)`;
    };
    zone.addEventListener("pointerdown", (e) => {
      if (!this.enabled || this.joy.id !== null) return;
      try {
        zone.setPointerCapture(e.pointerId);
      } catch {}
      const rect = zone.getBoundingClientRect();
      this.joy.id = e.pointerId;
      // the stick appears under your thumb, but never high up the screen
      this.joy.cx = Math.max(rect.left + 60, e.clientX);
      this.joy.cy = Math.max(rect.top + rect.height * 0.45, Math.min(rect.bottom - 60, e.clientY));
      joystick.style.left = `${this.joy.cx - rect.left}px`;
      joystick.style.top = `${this.joy.cy - rect.top}px`;
      joystick.classList.add("active");
      move(e);
    });
    const move = (e) => {
      if (e.pointerId !== this.joy.id) return;
      let x = (e.clientX - this.joy.cx) / R;
      let y = -(e.clientY - this.joy.cy) / R;
      const len = Math.hypot(x, y);
      if (len > 1) {
        // the base stays put; the knob just stops at the edge
        x /= len;
        y /= len;
      }
      this.joy.x = x;
      this.joy.y = y;
      setKnob();
    };
    zone.addEventListener("pointermove", move);
    const release = (e) => {
      if (e.pointerId !== this.joy.id) return;
      this.joy = { x: 0, y: 0, id: null };
      joystick.classList.remove("active");
      joystick.style.left = "";
      joystick.style.top = "";
      setKnob();
    };
    zone.addEventListener("pointerup", release);
    zone.addEventListener("pointercancel", release);
  }

  pressJump() {
    this.jumpQueued = performance.now();
    this.jumpHeld = true;
  }
  releaseJump() {
    this.jumpHeld = false;
  }

  isTyping(e) {
    const t = e.target;
    return t && (t.isContentEditable || /^(input|textarea|select)$/i.test(t.tagName));
  }

  pinchDistance() {
    const [a, b] = [...this.pointers.values()];
    return Math.hypot(a.x - b.x, a.y - b.y) || 1;
  }

  zoom(k) {
    this.dist = Math.min(16, Math.max(3.2, this.dist * k));
  }

  getMove() {
    if (!this.enabled) return { x: 0, y: 0, run: false };
    const k = this.keys;
    let x = (k.has("d") || k.has("arrowright") ? 1 : 0) - (k.has("a") || k.has("arrowleft") ? 1 : 0);
    let y = (k.has("w") || k.has("arrowup") ? 1 : 0) - (k.has("s") || k.has("arrowdown") ? 1 : 0);
    let run = k.has("shift");
    if (this.joy.id !== null) {
      x = this.joy.x;
      y = this.joy.y;
      run = Math.hypot(x, y) > 0.85;
    }
    const len = Math.hypot(x, y);
    if (len > 1) {
      x /= len;
      y /= len;
    }
    return { x, y, run };
  }

  // a jump pressed in the last 150ms still counts (jump buffering)
  wantsJump() {
    return this.jumpQueued && performance.now() - this.jumpQueued < 150;
  }
  clearJump() {
    this.jumpQueued = 0;
  }

  destroy() {
    window.removeEventListener("keydown", this.onKeyDown);
    window.removeEventListener("keyup", this.onKeyUp);
    window.removeEventListener("blur", this.onBlur);
    document.removeEventListener("mousemove", this.onLockedMove);
    if (document.pointerLockElement === this.canvas) document.exitPointerLock();
  }
}
