// Mini-games around the island: the sky trail (parkour), a heart hunt,
// goal kick, bonk-a-mole and catch-the-bunnies.
import * as THREE from "three";
import { std, glow, makeScreen, photoFrame, nameSprite, ISLAND_R, GROW, SPREAD } from "./world.js";
import { texture } from "./textures.js";
import { bakeWhenSettled } from "./bake.js";

const deg = THREE.MathUtils.degToRad;
const BALL_R = 0.28; // the football
const at = (angleDeg, r) => new THREE.Vector3(Math.sin(deg(angleDeg)) * r * SPREAD, 0, Math.cos(deg(angleDeg)) * r * SPREAD);

export const TRAIL_ANGLE = deg(200);
const TD = new THREE.Vector3(Math.sin(TRAIL_ANGLE), 0, Math.cos(TRAIL_ANGLE));
const TQ = new THREE.Vector3(Math.cos(TRAIL_ANGLE), 0, -Math.sin(TRAIL_ANGLE));
const trailPos = (r, lat = 0) => TD.clone().multiplyScalar(r).addScaledVector(TQ, lat);

export const SPOTS = {
  ball: at(258, 76),
  moles: at(28, 64), // the open meadow between the art studio and the cinema
  bunnies: at(100, 85),
  trail: trailPos(43.5 + GROW),
};
// kept clear of trees and rocks
export const RESERVED = [
  { x: SPOTS.ball.x, z: SPOTS.ball.z, r: 12.6 },
  { x: SPOTS.moles.x, z: SPOTS.moles.z, r: 5 },
  { x: SPOTS.bunnies.x, z: SPOTS.bunnies.z, r: 4 },
  { x: SPOTS.trail.x, z: SPOTS.trail.z, r: 4 },
  // the straw dummies for the sniper rifle (fx.js)
  { x: at(40, 87).x, z: at(40, 87).z, r: 4 },
];

const BEST_KEY = "tdd3d.best";
function loadBest() {
  try {
    return JSON.parse(localStorage.getItem(BEST_KEY) || "{}") || {};
  } catch {
    return {};
  }
}
function saveBest(b) {
  try {
    localStorage.setItem(BEST_KEY, JSON.stringify(b));
  } catch {}
}

function mesh(parent, geo, material, x = 0, y = 0, z = 0) {
  const m = new THREE.Mesh(geo, material);
  m.position.set(x, y, z);
  m.castShadow = true;
  m.receiveShadow = true;
  parent.add(m);
  return m;
}

function signPost(scene, pos, title, lines, color = "#f29ac0", facing) {
  const g = new THREE.Group();
  g.position.copy(pos);
  g.rotation.y = facing ?? Math.atan2(-pos.x, -pos.z);
  scene.add(g);
  // (the same look as the welcome sign at the gate: pale wood posts, a pink photo frame)
  const wood = std("#ffffff", { map: texture("wood", ["#fff3ea", "#e8d4c8"]) });
  for (const s of [-1, 1]) mesh(g, new THREE.BoxGeometry(0.12, 1.05, 0.12), wood, s * 0.75, 0.52, -0.005); // (centred under the board)
  photoFrame(g, 1.75, 1.05, 0, 1.6, 0);
  const screen = makeScreen(1.75, 1.05, { border: color, placeholder: title });
  screen.mesh.position.set(0, 1.6, 0);
  g.add(screen.mesh);
  const back = new THREE.Mesh(screen.mesh.geometry, screen.mesh.material);
  back.position.set(0, 1.6, -0.048); // (on the board's back, not floating behind it)
  back.rotation.y = Math.PI;
  g.add(back);
  screen.draw(lines);
  return { group: g, screen };
}

export class Games {
  constructor({ scene, world, creatures, audio, ui, lowEnd, send, sendMole }) {
    this.send = send; // shares the ball with your person
    this.sendMole = sendMole; // and bonk-a-mole rounds, so you can play together
    this.scene = scene;
    this.world = world;
    this.creatures = creatures;
    this.audio = audio;
    this.ui = ui;
    this.lowEnd = lowEnd;
    this.best = loadBest();
    this.active = null; // "moles" | "bunnies" | null
    this.t = 0;
    this.items = []; // interactables (start signs etc.)
    this.buildTrail();
    this.buildHearts();
    this.buildBall();
    this.buildMoles();
    this.buildBunnyMeadow();
  }

  item(def) {
    const it = { radius: 2.0, hits: [], ...def };
    for (const m of it.hits) m.traverse((o) => (o.userData.item = it));
    this.items.push(it);
    this.world.interactables.push(it);
    return it;
  }

  // ---- the sky trail ------------------------------------------------------
  buildTrail() {
    const g = new THREE.Group();
    this.scene.add(g);
    const pads = [
      [50.5, 0, 0.5, 1.3],
      [53.6, 1.6, 1.1, 1.2],
      [56.8, -0.6, 1.7, 1.2],
      [60.4, 0, 2.1, 1.2, "move"],
      [64.2, 0, 2.6, 2.0, "check"],
      [67.3, 2.0, 3.3, 0.9],
      [69.8, 0, 4.0, 0.9],
      [72.3, -2.0, 4.7, 0.9],
      [75.3, 0, 4.7, 1.1, "bounce"],
      [80.5, 0, 8.0, 3.6, "finish"],
    ];
    const cloud = new THREE.MeshStandardMaterial({ color: "#ffffff", emissive: "#ffffff", emissiveIntensity: 0.25, flatShading: true, roughness: 1 });
    const pastel = ["#ffd6e7", "#e6dcff", "#d8f3ff", "#fff1c9"];
    this.trailSolids = [];
    pads.forEach(([r, lat, y, rad, kind], i) => {
      const p = trailPos(r + GROW, lat);
      const pad = new THREE.Group();
      pad.position.set(p.x, y, p.z);
      g.add(pad);
      const topMat = kind === "bounce" ? std("#e2557f") : std(pastel[i % pastel.length]);
      if (kind === "bounce") {
        // a big mushroom
        mesh(pad, new THREE.CylinderGeometry(0.25, 0.35, 1.2, 8), std("#fff3e0"), 0, -0.6, 0);
        mesh(pad, new THREE.SphereGeometry(rad, 12, 6, 0, Math.PI * 2, 0, Math.PI / 2), topMat, 0, -0.15, 0).scale.y = 0.55;
        for (let d = 0; d < 6; d++) mesh(pad, new THREE.SphereGeometry(0.13, 6, 4), std("#ffffff"), Math.sin(d) * rad * 0.6, 0.18, Math.cos(d) * rad * 0.6).scale.y = 0.4;
      } else {
        mesh(pad, new THREE.CylinderGeometry(rad, rad * 0.92, 0.3, 14), topMat, 0, -0.15, 0);
        const puffs = kind === "finish" ? 9 : 4;
        for (let k = 0; k < puffs; k++) {
          const a = (k / puffs) * Math.PI * 2;
          mesh(pad, new THREE.IcosahedronGeometry(rad * 0.45, 0), cloud, Math.sin(a) * rad * 0.6, -0.45, Math.cos(a) * rad * 0.6).castShadow = false;
        }
      }
      const solid = { type: "cyl", x: p.x, z: p.z, r: rad, top: y, bottom: y - 0.6, kind, base: p.clone(), i };
      if (kind === "bounce") solid.top = y - 0.05;
      this.world.solids.push(solid);
      this.trailSolids.push({ solid, pad });
      if (kind === "check") {
        const flag = new THREE.Group();
        flag.position.set(0.9, 0, 0);
        pad.add(flag);
        mesh(flag, new THREE.CylinderGeometry(0.04, 0.04, 1.6, 5), std("#fff7f2"), 0, 0.8, 0);
        this.checkFlag = mesh(flag, new THREE.BoxGeometry(0.02, 0.4, 0.6), std("#b79be8"), 0, 1.4, 0.3);
      }
      if (kind === "finish") {
        // trophy star and a portal home
        const star = new THREE.Shape();
        for (let k = 0; k < 10; k++) {
          const rr = k % 2 ? 0.25 : 0.55;
          const a = (k / 10) * Math.PI * 2;
          k ? star.lineTo(Math.sin(a) * rr, Math.cos(a) * rr) : star.moveTo(Math.sin(a) * rr, Math.cos(a) * rr);
        }
        const starMesh = mesh(pad, new THREE.ExtrudeGeometry(star, { depth: 0.18, bevelEnabled: false }), new THREE.MeshStandardMaterial({ color: "#ffd166", emissive: "#ffb000", emissiveIntensity: 0.9, metalness: 0.4, roughness: 0.3, flatShading: true }), 0, 1.4, 0);
        this.star = starMesh;
        const ring = mesh(pad, new THREE.TorusGeometry(0.9, 0.1, 6, 20), glow.magic, -2.0, 1.2, 0);
        this.homeRing = ring;
        this.finishPad = pad;
        this.item({ id: "trail-home", label: "go back to the island", pos: new THREE.Vector3(p.x, y, p.z).addScaledVector(TQ, -2.0), radius: 1.6, action: { type: "game", game: "trail-home" }, hits: [ring] });
      }
    });
    // sign and arch at the start
    const sign = signPost(this.scene, trailPos(44.2 + GROW, 2.6), "₊˚⊹ sky trail ⊹˚₊", this.trailText());
    this.trailSign = sign;
    const label = nameSprite();
    label.userData.draw("₊˚⊹ sky trail ⊹˚₊");
    label.position.copy(trailPos(46 + GROW, 0)).setY(3.2);
    this.scene.add(label);
    this.trail = { running: false, time: 0, checkpoint: 0 };
  }

  trailText() {
    const b = this.best.trail;
    const stars = this.best.stars || 0;
    return { title: "₊˚⊹ sky trail ⊹˚₊", big: b ? b.toFixed(1) + "s" : "⋆", sub: `${b ? "best time" : "no best time yet"}${stars ? ` · ⭐ ${stars}` : ""}`, foot: "jump the clouds and grab the star" };
  }

  respawnPoint() {
    if (this.trail.checkpoint && this.trailSolids) {
      const s = this.trailSolids.find((t) => t.solid.kind === "check").solid;
      return { pos: new THREE.Vector3(s.x, s.top, s.z), facing: TRAIL_ANGLE };
    }
    const p = trailPos(45.5 + GROW, 0);
    return { pos: p, facing: TRAIL_ANGLE };
  }

  // ---- hearts --------------------------------------------------------------
  buildHearts() {
    const shape = new THREE.Shape();
    shape.moveTo(0, -0.35);
    shape.bezierCurveTo(-0.6, 0.05, -0.28, 0.55, 0, 0.25);
    shape.bezierCurveTo(0.28, 0.55, 0.6, 0.05, 0, -0.35);
    const geo = new THREE.ExtrudeGeometry(shape, { depth: 0.12, bevelEnabled: false });
    geo.center();
    const mat = new THREE.MeshStandardMaterial({ color: "#ff8fb1", emissive: "#ff4f8b", emissiveIntensity: 0.7, flatShading: true });
    this.hearts = [];
    const spots = [];
    for (let i = 0; i < 18 && spots.length < 18; i++) {
      for (let t = 0; t < 40; t++) {
        const a = Math.random() * Math.PI * 2;
        const d = 10 + Math.random() * (ISLAND_R - 16);
        const p = new THREE.Vector3(Math.sin(a) * d, 0.9, Math.cos(a) * d);
        if (this.world.isFree(p.x, p.z, 0.6) && spots.every((s) => s.distanceTo(p) > 5)) {
          spots.push(p);
          break;
        }
      }
    }
    // a couple of hearts on the sky trail too
    for (const ts of this.trailSolids.filter((t) => t.solid.i === 2 || t.solid.i === 6)) spots.push(new THREE.Vector3(ts.solid.x, ts.solid.top + 0.9, ts.solid.z));
    spots.forEach((p) => {
      const m = new THREE.Mesh(geo, mat);
      m.position.copy(p);
      this.scene.add(m);
      this.hearts.push({ mesh: m, base: p.clone(), taken: false });
    });
    this.heartCount = 0;
    this.heartTotal = this.hearts.length;
  }

  // ---- goal kick: a little fenced pitch with a goal at each end -------------
  buildBall() {
    const c = SPOTS.ball;
    const out = c.clone().setY(0).normalize();
    const g = new THREE.Group();
    g.position.copy(c);
    g.rotation.y = Math.atan2(out.x, out.z); // local +z points out to sea
    this.scene.add(g);
    g.updateMatrixWorld(true);
    const HW = 6.0; // half width
    const HL = 10.0; // half length
    const toW = (x, z) => new THREE.Vector3(x, 0, z).applyMatrix4(g.matrixWorld);
    const seg = (x0, z0, x1, z1, h, extra = {}) => {
      const a = toW(x0, z0);
      const b = toW(x1, z1);
      this.world.segments.push({ ax: a.x, az: a.z, bx: b.x, bz: b.z, h, room: "", ...extra });
    };
    // its own kept turf, so snow or autumn on the island's ground never covers the pitch
    {
      const turf = new THREE.Mesh(new THREE.PlaneGeometry(HW * 2 + 0.1, HL * 2 + 0.1), new THREE.MeshStandardMaterial({ map: texture("grass", ["#8fd07a", "#79bd66"], 5), roughness: 1 }));
      turf.rotation.x = -Math.PI / 2;
      turf.position.y = 0.012;
      turf.receiveShadow = true;
      g.add(turf);
    }
    // striped grass and white lines
    const stripe = new THREE.MeshStandardMaterial({ color: "#a8dc8e", transparent: true, opacity: 0.6, depthWrite: false });

    const NS = 10;
    for (let k = 0; k < NS; k += 2) {
      const s = new THREE.Mesh(new THREE.PlaneGeometry(HW * 2, (HL * 2) / NS), stripe);
      s.rotation.x = -Math.PI / 2;
      s.position.set(0, 0.018, -HL + (HL * 2 * (k + 0.5)) / NS);
      s.receiveShadow = true;
      g.add(s);
    }
    const line = new THREE.MeshBasicMaterial({ color: "#ffffff", transparent: true, opacity: 0.8 });
    const flat = (geo, x, z) => {
      const m = new THREE.Mesh(geo, line);
      m.rotation.x = -Math.PI / 2;
      m.position.set(x, 0.025, z);
      g.add(m);
      return m;
    };
    flat(new THREE.RingGeometry(1.3, 1.42, 40), 0, 0);
    flat(new THREE.CircleGeometry(0.14, 12), 0, 0);
    flat(new THREE.PlaneGeometry(HW * 2 - 0.4, 0.12), 0, 0);
    const EL = HL - 0.35; // the end lines
    for (const s of [-1, 1]) {
      flat(new THREE.PlaneGeometry(HW * 2 - 0.4, 0.12), 0, s * EL);
      flat(new THREE.PlaneGeometry(0.12, HL * 2 - 0.7), s * (HW - 0.2), 0);
      // the big box, the little box, the spot and the arc
      const box = (w, d) => {
        flat(new THREE.PlaneGeometry(w, 0.1), 0, s * (EL - d));
        for (const x of [-1, 1]) flat(new THREE.PlaneGeometry(0.1, d), (x * w) / 2, s * (EL - d / 2));
      };
      box(6.6, 2.5);
      box(5.0, 1.0);
      flat(new THREE.CircleGeometry(0.09, 10), 0, s * (EL - 1.8));
      const arc = flat(new THREE.RingGeometry(0.85, 0.95, 24, 1, Math.PI * 0.22, Math.PI * 0.56), 0, s * (EL - 1.8));
      arc.rotation.z = s > 0 ? 0 : Math.PI;
      // corner quarter circles
      for (const x of [-1, 1]) {
        const q = flat(new THREE.RingGeometry(0.32, 0.42, 10, 1, 0, Math.PI / 2), x * (HW - 0.2), s * EL);
        q.rotation.z = Math.atan2(s, -x) - Math.PI / 4; // the quarter faces into the pitch
      }
    }
    // corner flags that wave in the breeze
    const flagCols = ["#ff8fb1", "#8fd3f0"];
    for (const zs of [-1, 1]) for (const xs of [-1, 1]) {
      const fx = xs * (HW - 0.2);
      const fz = zs * EL;
      mesh(g, new THREE.CylinderGeometry(0.025, 0.025, 1.1, 5), std("#fff7f2"), fx, 0.55, fz);
      const piv = new THREE.Group();
      piv.position.set(fx, 1.0, fz);
      g.add(piv);
      const fl = new THREE.Mesh(new THREE.PlaneGeometry(0.34, 0.22, 4, 1), new THREE.MeshStandardMaterial({ color: flagCols[zs > 0 ? 0 : 1], side: THREE.DoubleSide, flatShading: true }));
      fl.position.x = 0.17;
      piv.add(fl);
      const pos = fl.geometry.attributes.position;
      const x0 = Float32Array.from({ length: pos.count }, (_, i) => pos.getX(i));
      this.world.animated.push((t) => {
        piv.rotation.y = Math.sin(t * 0.7 + xs + zs) * 0.6;
        for (let i = 0; i < pos.count; i++) pos.setZ(i, Math.sin(t * 6 + x0[i] * 14 + fx) * 0.04 * (x0[i] + 0.17) * 3);
        pos.needsUpdate = true;
      });
    }
    // two goals, pink and blue
    this.goalSides = [];
    for (const side of [1, -1]) {
      const goal = new THREE.Group();
      goal.position.z = side * (HL - 1.25);
      goal.rotation.y = side > 0 ? 0 : Math.PI;
      g.add(goal);
      const col = side > 0 ? "#ff8fb1" : "#8fd3f0";
      const frame = std("#fff7f2", { flatShading: false });
      const tint = std(col, { flatShading: false });
      // (a proper size: about four and a half metres across and two high)
      const GW = 2.2;
      const GH = 2.0;
      const GD = 1.05;
      for (const s of [-1, 1]) {
        mesh(goal, new THREE.CylinderGeometry(0.07, 0.07, GH, 10), frame, s * GW, GH / 2, 0);
        for (let k = 0; k < 3; k++) mesh(goal, new THREE.CylinderGeometry(0.075, 0.075, 0.14, 10), tint, s * GW, 0.35 + k * 0.6, 0);
        // a back leg sloping from the crossbar to the ground, and a bar along the ground
        const leg = mesh(goal, new THREE.CylinderGeometry(0.035, 0.035, Math.hypot(GH, GD), 6), tint, s * GW, GH / 2, GD / 2);
        leg.rotation.x = -Math.atan2(GD, GH);
        mesh(goal, new THREE.CylinderGeometry(0.035, 0.035, GD, 6), tint, s * GW, 0.035, GD / 2).rotation.x = Math.PI / 2;
      }
      mesh(goal, new THREE.CylinderGeometry(0.07, 0.07, GW * 2 + 0.14, 10), frame, 0, GH, 0).rotation.z = Math.PI / 2;
      mesh(goal, new THREE.CylinderGeometry(0.035, 0.035, GW * 2, 6), tint, 0, 0.035, GD).rotation.z = Math.PI / 2;
      // the net: a grid of string over the back, the roof and both sides
      const pts = [];
      const L = (a, b) => pts.push(...a, ...b);
      const step = 0.18;
      const backZ = (y) => GD * (1 - y / GH); // the back slopes from the crossbar down to the ground bar
      for (let x = -GW; x <= GW + 1e-3; x += step) L([x, GH, 0], [x, 0.03, GD]);
      for (let y = 0.03; y <= GH + 1e-3; y += step) L([-GW, y, backZ(y)], [GW, y, backZ(y)]);
      for (const sx of [-1, 1]) {
        for (let y = 0.03; y <= GH + 1e-3; y += step) L([sx * GW, y, 0], [sx * GW, y, backZ(y)]);
        for (let z = step; z <= GD + 1e-3; z += step) L([sx * GW, 0.03, z], [sx * GW, Math.max(0.03, GH * (1 - z / GD)), z]);
      }
      const ng = new THREE.BufferGeometry();
      ng.setAttribute("position", new THREE.Float32BufferAttribute(pts, 3));
      goal.add(new THREE.LineSegments(ng, new THREE.LineBasicMaterial({ color: "#ffffff", transparent: true, opacity: 0.55 })));
      const zf = side * (HL - 1.25);
      const zb = side * (HL - 0.15);
      for (const s of [-1, 1]) {
        const p = toW(s * GW, zf);
        this.world.circles.push({ x: p.x, z: p.z, r: 0.1 });
        seg(s * GW, zf, s * GW, zb, GH);
      }
      this.goalSize = { w: GW, h: GH };
      this.goalSides.push({ side, z0: Math.min(zf, zb), z1: Math.max(zf, zb) });
    }
    // a low picket fence all round (you can hop over it, the ball can't)
    const wood = std("#ffffff", { map: texture("wood", ["#fff3ea", "#e8d4c8"]) });
    const picket = new THREE.BoxGeometry(0.08, 0.7, 0.05);
    const pickets = [];
    const addRun = (x0, z0, x1, z1) => {
      const len = Math.hypot(x1 - x0, z1 - z0);
      const n = Math.max(2, Math.round(len / 0.32));
      for (let i = 0; i <= n; i++) pickets.push([x0 + ((x1 - x0) * i) / n, z0 + ((z1 - z0) * i) / n, Math.atan2(x1 - x0, z1 - z0)]);
      const rail = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.07, len), wood);
      rail.position.set((x0 + x1) / 2, 0.45, (z0 + z1) / 2);
      rail.rotation.y = Math.atan2(x1 - x0, z1 - z0);
      g.add(rail);
    };
    const gap = 0.9; // a gap in the middle of one side to walk in (the ball can't get through)
    addRun(-HW, -HL, HW, -HL);
    addRun(-HW, HL, HW, HL);
    addRun(HW, -HL, HW, HL);
    addRun(-HW, -HL, -HW, -gap);
    addRun(-HW, gap, -HW, HL);
    const inst = new THREE.InstancedMesh(picket, wood, pickets.length);
    const m4 = new THREE.Matrix4();
    const q = new THREE.Quaternion();
    pickets.forEach(([x, z, a], i) => {
      q.setFromAxisAngle(new THREE.Vector3(0, 1, 0), a);
      m4.compose(new THREE.Vector3(x, 0.35, z), q, new THREE.Vector3(1, 1, 1));
      inst.setMatrixAt(i, m4);
    });
    inst.castShadow = true;
    g.add(inst);
    seg(-HW, -HL, HW, -HL, 0.75);
    seg(-HW, HL, HW, HL, 0.75);
    seg(HW, -HL, HW, HL, 0.75);
    seg(-HW, -HL, -HW, -gap, 0.75);
    seg(-HW, gap, -HW, HL, 0.75);
    seg(-HW, -gap, -HW, gap, 0.75, { ballOnly: true });
    for (const [x, z] of [[-HW, -gap], [-HW, gap]]) mesh(g, new THREE.CylinderGeometry(0.07, 0.07, 1.0, 6), std("#e2557f"), x, 0.5, z);
    const buntCols = ["#ff8fb1", "#ffd166", "#8fd3f0", "#b79be8", "#9be0b0"];
    const pennant = new THREE.BufferGeometry();
    pennant.setAttribute("position", new THREE.Float32BufferAttribute([-0.11, 0, 0, 0.11, 0, 0, 0, -0.24, 0], 3));
    pennant.computeVertexNormals();
    for (const sx of [-1, 1]) {
      const x = sx * HW;
      for (const z of [-HL, HL, 0]) {
        if (sx < 0 && z === 0) continue;
        mesh(g, new THREE.CylinderGeometry(0.035, 0.04, 1.5, 6), wood, x, 0.75, z);
      }
      const runs = sx < 0 ? [[-HL, -gap], [gap, HL]] : [[-HL, 0], [0, HL]];
      for (const [z0, z1] of runs) {
        const n = Math.round(Math.abs(z1 - z0) / 0.38);
        const y0 = sx < 0 && Math.abs(z0) < 1 ? 1.0 : 1.48;
        const y1 = sx < 0 && Math.abs(z1) < 1 ? 1.0 : 1.48;
        for (let i = 1; i < n; i++) {
          const k = i / n;
          const y = y0 + (y1 - y0) * k - Math.sin(k * Math.PI) * 0.25;
          const pn = new THREE.Mesh(pennant, std(buntCols[i % buntCols.length], { side: THREE.DoubleSide, key: "bunting" }));
          pn.position.set(x, y, z0 + (z1 - z0) * k);
          pn.rotation.y = Math.PI / 2;
          pn.rotation.x = Math.sin(i * 1.3) * 0.15; // a little hang, each one different
          g.add(pn);
        }
      }
    }
    // a little bleacher outside the far side, for cheering
    const bl = new THREE.Group();
    bl.position.set(HW + 1.25, 0, 0);
    bl.rotation.y = -Math.PI / 2;
    g.add(bl);
    const seatA = std("#ff8fb1", { flatShading: false });
    const seatB = std("#8fd3f0", { flatShading: false });
    for (let row = 0; row < 2; row++) {
      mesh(bl, new THREE.BoxGeometry(3.4, 0.08, 0.42), row ? seatB : seatA, 0, 0.42 + row * 0.42, -row * 0.45);
      mesh(bl, new THREE.BoxGeometry(3.4, 0.42 + row * 0.42, 0.06), wood, 0, (0.42 + row * 0.42) / 2, -row * 0.45 + 0.2);
      for (const sx of [-1.6, 0, 1.6]) mesh(bl, new THREE.BoxGeometry(0.08, 0.42 + row * 0.42, 0.38), wood, sx, (0.42 + row * 0.42) / 2, -row * 0.45);
    }
    for (const sx of [-1, 1]) {
      const a = toW(HW + 1.25, sx * 1.6);
      this.world.circles.push({ x: a.x, z: a.z, r: 0.4 });
    }
    seg(HW + 0.95, -1.8, HW + 0.95, 1.8, 0.9);
    // a foam finger and a water bottle on the bench, for the vibe
    mesh(bl, new THREE.BoxGeometry(0.18, 0.32, 0.06), std("#ffd166"), -0.9, 0.62, -0.05).rotation.z = 0.3;
    mesh(bl, new THREE.CylinderGeometry(0.05, 0.05, 0.22, 8), std("#8fd3f0", { transparent: true, opacity: 0.7 }), 1.1, 0.57, 0.05);

    this.pitch = { group: g, inv: new THREE.Matrix4().copy(g.matrixWorld).invert(), center: c.clone(), out, HW, HL };
    bakeWhenSettled(g);

    // the ball
    const cv = document.createElement("canvas");
    cv.width = 128;
    cv.height = 64;
    const x = cv.getContext("2d");
    ["#ff8fb1", "#fff7f2", "#8fd3f0", "#fff7f2", "#ffd166", "#fff7f2"].forEach((col, i) => {
      x.fillStyle = col;
      x.fillRect((i * 128) / 6, 0, 128 / 6 + 1, 64);
    });
    const tex = new THREE.CanvasTexture(cv);
    tex.colorSpace = THREE.SRGBColorSpace;
    this.ball = {
      mesh: mesh(this.scene, new THREE.SphereGeometry(BALL_R, 16, 10), new THREE.MeshStandardMaterial({ map: tex, roughness: 0.5 })),
      pos: c.clone().addScaledVector(out, -1).setY(BALL_R),
      vel: new THREE.Vector3(),
      r: BALL_R,
    };
    this.goals = 0;
    this.score = { pink: 0, blue: 0 };
    this.goalCooldown = 0;
    // the sign stands by the gate, facing the way you walk in
    const signAt = toW(-HW - 1.6, 2.2);
    const sign = signPost(this.scene, signAt, "⋆ goal kick ⋆", this.goalText(), "#f29ac0", g.rotation.y - Math.PI / 2);
    this.world.circles.push({ x: signAt.x, z: signAt.z, r: 0.25 });
    this.ballSign = sign;
  }

  goalText() {
    const s = this.score || { pink: 0, blue: 0 };
    return { title: "⋆ goal kick ⋆", pairs: [["💗 pink", String(s.pink)], ["💙 blue", String(s.blue)]], foot: "kick it into a goal ⋆" };
  }

  resetBall() {
    this.ball.pos.copy(this.pitch.center).setY(BALL_R);
    this.ball.vel.set(0, 0, 0);
  }

  // ---- one ball for both of you ----------------------------------------------
  // whoever kicked it last runs it and keeps the other copy in step; the score
  // and goals come from them too
  shareBall(extra = {}, to) {
    const b = this.ball;
    this.ballSendT = 0.15;
    const r2 = (n) => +n.toFixed(2);
    this.send?.({ p: [r2(b.pos.x), r2(b.pos.y), r2(b.pos.z)], v: [r2(b.vel.x), r2(b.vel.y), r2(b.vel.z)], k: this.kickN || 0, s: [this.score.pink, this.score.blue], g: this.goals, ...extra }, to);
  }
  // when you meet: the game with more goals in it wins (the same pick on both sides)
  greetBall(to) {
    this.shareBall({ hi: 1 }, to);
  }
  onRemoteBall(p, key, myKey) {
    if (!p || !Array.isArray(p.p) || !Array.isArray(p.v)) return;
    if (p.hi && ((p.g || 0) < this.goals || ((p.g || 0) === this.goals && !(key < myKey)))) return;
    // every kick is numbered: a packet sent before my latest kick is old news and
    // would yank the ball back (the teleport). Two kicks at once: one side wins.
    const k = p.k | 0;
    const mineNow = !this.ballOwner;
    const justKicked = mineNow && this.kickedAt > performance.now() - 1500;
    if (!p.hi && !p.goal && justKicked) {
      if (k < (this.kickN || 0)) return;
      if (k === (this.kickN || 0) && !(key < myKey)) return;
    }
    this.kickN = Math.max(this.kickN || 0, k);
    // their state is a moment old by the time it gets here: carry it forward so the
    // ball isn't pulled back each time, and ease out the difference
    const b = this.ball;
    const lag = 0.1;
    const shown = b.mesh.position.clone();
    b.vel.set(...p.v);
    b.pos.set(p.p[0] + p.v[0] * lag, Math.max(b.r, p.p[1] + p.v[1] * lag - 7 * lag * lag), p.p[2] + p.v[2] * lag);
    if (!this.ballOff) this.ballOff = new THREE.Vector3();
    this.ballOff.copy(shown).sub(b.pos);
    if (this.ballOff.length() > 3 || p.goal) this.ballOff.set(0, 0, 0);
    this.ballOwner = key;
    if (Array.isArray(p.s) && (p.s[0] !== this.score.pink || p.s[1] !== this.score.blue)) {
      this.score = { pink: p.s[0] | 0, blue: p.s[1] | 0 };
      this.goals = Math.max(this.goals, p.g | 0);
      this.ballSign.screen.draw(this.goalText());
    }
    if (p.goal) {
      this.goalCooldown = 2;
      this.ui.toast(`goal for ${p.goal}! ⋆ 💗 ${this.score.pink} : ${this.score.blue} 💙`);
      this.ui.confetti(this.ball.pos);
      this.audio.sfx("win");
    }
  }
  // they left: the ball is yours again
  dropBallOwner(key) {
    if (this.ballOwner === key) this.ballOwner = null;
  }

  // ---- bonk-a-mole -------------------------------------------------------------
  buildMoles() {
    const c = SPOTS.moles;
    const g = new THREE.Group();
    g.position.copy(c);
    this.scene.add(g);
    const dirt = std("#8a5a3c");
    const fur = std("#7a5a4a");
    this.moles = [];
    const holes = [[0, 0]];
    for (let i = 0; i < 6; i++) holes.push([Math.sin((i / 6) * Math.PI * 2) * 1.8, Math.cos((i / 6) * Math.PI * 2) * 1.8]);
    for (const [x, z] of holes) {
      mesh(g, new THREE.CylinderGeometry(0.45, 0.55, 0.12, 10), dirt, x, 0.04, z);
      mesh(g, new THREE.CircleGeometry(0.32, 10), std("#2b1d24"), x, 0.105, z).rotation.x = -Math.PI / 2;
      const mole = new THREE.Group();
      mole.position.set(x, -0.6, z);
      g.add(mole);
      mesh(mole, new THREE.CapsuleGeometry(0.24, 0.25, 2, 8), fur, 0, 0.25, 0);
      mesh(mole, new THREE.SphereGeometry(0.07, 6, 4), std("#ff8fb1"), 0, 0.42, 0.22);
      for (const s of [-1, 1]) mesh(mole, new THREE.SphereGeometry(0.04, 6, 4), std("#1d1424"), s * 0.09, 0.52, 0.19);
      this.moles.push({ group: mole, x: c.x + x, z: c.z + z, up: 0, timer: 0, bonked: 0 });
    }
    const sign = signPost(this.scene, c.clone().addScaledVector(c.clone().normalize(), -3.6), "⋆ bonk-a-mole ⋆", this.moleText());
    this.moleSign = sign;
    this.item({ id: "moles", label: "play bonk-a-mole", pos: sign.group.position.clone(), radius: 2.2, action: { type: "game", game: "moles" }, hits: [sign.screen.mesh] });
  }
  moleText() {
    return { title: "⋆ bonk-a-mole ⋆", big: String(this.best.moles || 0), sub: "best score", foot: "30 seconds · press ✦ to play" };
  }

  // ---- catch the bunnies -------------------------------------------------------
  buildBunnyMeadow() {
    const c = SPOTS.bunnies;
    const sign = signPost(this.scene, c.clone(), "⋆ catch the bunnies ⋆", this.bunnyText());
    this.bunnySign = sign;
    this.item({ id: "bunnies", label: "play catch the bunnies", pos: c.clone(), radius: 2.2, action: { type: "game", game: "bunnies" }, hits: [sign.screen.mesh] });
  }
  bunnyText() {
    return { title: "⋆ catch the bunnies ⋆", big: String(this.best.bunnies || 0), sub: "best score", foot: "40 seconds · press ✦ to play" };
  }

  // ---- start / stop --------------------------------------------------------------
  start(id, player) {
    if (id === "trail-home") {
      this.trail.running = false;
      this.trail.checkpoint = 0;
      return { teleport: { pos: trailPos(42 + GROW, 0), facing: TRAIL_ANGLE + Math.PI } };
    }
    if (this.active) this.stop(false);
    if (id === "moles") {
      this.active = "moles";
      this.round = { time: 30, score: 0, spawn: 0.4, host: true };
      this.audio.sfx("start");
      this.sendMole?.({ s: 1 });
    } else if (id === "bunnies") {
      this.active = "bunnies";
      this.round = { time: 40, score: 0, bunnies: [] };
      for (let i = 0; i < 6; i++) {
        const a = (i / 6) * Math.PI * 2;
        const p = SPOTS.bunnies.clone().add(new THREE.Vector3(Math.sin(a) * 6, 0, Math.cos(a) * 6));
        const b = this.creatures.spawnGolden(p);
        this.round.bunnies.push(b);
      }
      this.audio.sfx("start");
    }
    void player;
    return null;
  }

  stop(finished = true) {
    if (!this.active) return;
    const id = this.active;
    const score = this.round.score;
    if (id === "bunnies") this.round.bunnies.forEach((b) => this.creatures.remove(b));
    this.active = null;
    this.round = null;
    if (finished) {
      const best = this.best[id] || 0;
      if (score > best) {
        this.best[id] = score;
        saveBest(this.best);
        this.ui.toast(`new best: ${score} ♡`);
        this.ui.confetti();
        this.audio.sfx("win");
      } else {
        this.ui.toast(`time! you got ${score}`);
        this.audio.sfx("end");
      }
    }
    this.moleSign.screen.draw(this.moleText());
    this.bunnySign.screen.draw(this.bunnyText());
  }

  // ---- per frame ---------------------------------------------------------------
  update(dt, player, ctx) {
    this.t += dt;
    const t = this.t;
    const chip = [];

    // moving cloud on the trail
    for (const { solid, pad } of this.trailSolids) {
      if (solid.kind === "move") {
        const lat = Math.sin(t * 0.9) * 2.4;
        const p = solid.base.clone().addScaledVector(TQ, lat);
        solid.dx = p.x - solid.x;
        solid.dz = p.z - solid.z;
        solid.x = p.x;
        solid.z = p.z;
        pad.position.set(p.x, solid.top, p.z);
      }
    }
    if (this.star) {
      this.star.rotation.y = t * 1.5;
      // the star at the end of the trail: grab it!
      if (this.star.visible) {
        this.star.getWorldPosition(this.starPos || (this.starPos = new THREE.Vector3()));
        const dx = this.starPos.x - player.pos.x;
        const dz = this.starPos.z - player.pos.z;
        const dy = this.starPos.y - (player.pos.y + 0.9);
        if (dx * dx + dz * dz < 1.1 && Math.abs(dy) < 1.3) {
          this.star.visible = false;
          this.best.stars = (this.best.stars || 0) + 1;
          saveBest(this.best);
          this.ui.toast(`you caught the star ⭐ × ${this.best.stars}`);
          this.ui.confetti(this.starPos);
          this.audio.sfx("win");
          this.ui.onStar?.(this.best.stars);
          this.trailSign.screen.draw(this.trailText());
        }
      } else if (Math.hypot(player.pos.x, player.pos.z) < ISLAND_R - 4 && player.pos.y < 0.5) this.star.visible = true; // back on the island: it's there again
    }
    if (this.homeRing) this.homeRing.rotation.y = t;

    // trail timer and checkpoints
    const on = player.standing;
    if (on && on.kind !== undefined && on.i !== undefined) {
      if (on.i === 0 && !this.trail.running) {
        this.trail.running = true;
        this.trail.time = 0;
        this.trail.checkpoint = 0;
      }
      if (on.kind === "check" && !this.trail.checkpoint) {
        this.trail.checkpoint = 1;
        this.audio.sfx("check");
        this.ui.toast("checkpoint ⋆");
      }
      if (on.kind === "bounce" && ctx.landedOn === on) ctx.bounce = 11.5;
      if (on.kind === "finish" && this.trail.running) {
        this.trail.running = false;
        const time = this.trail.time;
        const best = this.best.trail;
        if (!best || time < best) {
          this.best.trail = time;
          saveBest(this.best);
          this.ui.toast(`new record: ${time.toFixed(1)}s ⋆`);
        } else this.ui.toast(`you made it in ${time.toFixed(1)}s ⋆`);
        this.ui.confetti();
        this.audio.sfx("win");
        this.trailSign.screen.draw(this.trailText());
      }
    }
    if (this.trail.running) {
      this.trail.time += dt;
      chip.push(`⋆ sky trail ${this.trail.time.toFixed(1)}s`);
      // walked back onto the island: stop timing
      if (Math.hypot(player.pos.x, player.pos.z) < ISLAND_R - 4 && player.grounded && player.pos.y < 0.1) this.trail.running = false;
    }

    // hearts
    for (const h of this.hearts) {
      if (h.taken) continue;
      h.mesh.rotation.y = t * 2 + h.base.x;
      h.mesh.position.y = h.base.y + Math.sin(t * 2 + h.base.z) * 0.15;
      if (Math.hypot(h.base.x - player.pos.x, h.base.z - player.pos.z) < 0.9 && Math.abs(h.base.y - (player.pos.y + 0.9)) < 1.2) {
        h.taken = true;
        h.mesh.visible = false;
        this.heartCount++;
        this.audio.sfx("collect");
        this.ui.buzz?.();
        if (this.heartCount >= this.heartTotal) {
          this.ui.toast("you found every heart ♡");
          this.ui.confetti();
          this.audio.sfx("win");
          setTimeout(() => {
            this.hearts.forEach((x) => {
              x.taken = false;
              x.mesh.visible = true;
            });
            this.heartCount = 0;
          }, 30000);
        }
      }
    }

    // the ball
    this.updateBall(dt, player, ctx?.others || []);

    // rounds
    this.updatePops(dt);
    if (this.active === "moles") this.updateMoles(dt, player);
    else if (this.active === "bunnies") this.updateBunnies(dt, player);
    else this.moles.forEach((m) => this.moleAnim(m, dt));
    if (this.active) chip.push(`${this.active === "moles" ? "bonk-a-mole" : "bunnies"} · ${Math.ceil(this.round.time)}s · ${this.round.score}`);
    if (this.goals && player.pos.distanceTo(this.pitch.center) < 12) chip.push(`💗 ${this.score.pink} : ${this.score.blue} 💙`);

    return { chip: chip.join("   "), hearts: `♡ ${this.heartCount}/${this.heartTotal}` };
  }

  // the ball meets someone standing (or walking past) without kicking it: it
  // rolls off them instead of being taken over
  bumpBall(cx, cz) {
    const b = this.ball;
    const dx = b.pos.x - cx;
    const dz = b.pos.z - cz;
    const d = Math.hypot(dx, dz) || 1;
    const min = b.r + 0.45;
    if (d >= min) return false;
    const nx = dx / d;
    const nz = dz / d;
    b.pos.x = cx + nx * min;
    b.pos.z = cz + nz * min;
    const vn = b.vel.x * nx + b.vel.z * nz;
    if (vn < 0) {
      b.vel.x -= 1.6 * vn * nx;
      b.vel.z -= 1.6 * vn * nz;
    }
    return true;
  }

  updateBall(dt, player, others = []) {
    const b = this.ball;
    const dx = b.pos.x - player.pos.x;
    const dz = b.pos.z - player.pos.z;
    const d = Math.hypot(dx, dz);
    this.kickCool = (this.kickCool || 0) - dt;
    // a kick only when you run into it; just standing there, it bounces off you
    if (d < b.r + 0.45 && player.pos.y < b.pos.y + 0.5) {
      const nx = dx / (d || 1);
      const nz = dz / (d || 1);
      const toward = Math.sin(player.facing) * nx + Math.cos(player.facing) * nz;
      if (player.speed > 0.8 && toward > 0.2 && this.kickCool <= 0) {
        const power = Math.min(16, 2 + player.speed * 1.35);
        b.vel.x = nx * power;
        b.vel.z = nz * power;
        b.vel.y = player.speed > 4 ? 3.2 : 1.2;
        b.pos.x = player.pos.x + nx * (b.r + 0.48);
        b.pos.z = player.pos.z + nz * (b.r + 0.48);
        this.audio.sfx("kick");
        // your kick: you run the ball now, and your person sees it fly
        this.ballOwner = null;
        this.kickN = (this.kickN || 0) + 1;
        this.kickedAt = performance.now();
        this.shareBall();
        this.kickCool = 0.2;
      } else this.bumpBall(player.pos.x, player.pos.z);
    }
    // whoever runs the ball also lets it bounce off the other player
    if (!this.ballOwner) for (const o of others) if (Math.abs(o.y - b.pos.y) < 1.5) this.bumpBall(o.x, o.z);
    // small steps when it flies fast, so it can't slip through the fence
    const steps = Math.min(6, Math.max(1, Math.ceil((Math.hypot(b.vel.x, b.vel.z) * dt) / (b.r * 0.6))));
    const h = dt / steps;
    for (let i = 0; i < steps; i++) this.stepBall(b, h);
    const mine = !this.ballOwner;
    // kept inside the fence even if something odd happens (only the side that runs
    // the ball puts it back; the other copy waits for it instead of jumping alone)
    const lp = b.pos.clone().applyMatrix4(this.pitch.inv);
    if (mine && (Math.abs(lp.x) > this.pitch.HW + 0.6 || Math.abs(lp.z) > this.pitch.HL + 0.6 || Math.hypot(b.pos.x, b.pos.z) > ISLAND_R - 1.5)) {
      this.resetBall();
      this.ballOff?.set(0, 0, 0);
      this.shareBall();
    }
    this.rollBall(b, dt);
    this.finishBall(b, dt, mine);
  }
  stepBall(b, dt) {
    b.vel.y -= 14 * dt;
    b.pos.addScaledVector(b.vel, dt);
    if (b.pos.y < b.r) {
      b.pos.y = b.r;
      if (b.vel.y < -1.5) b.vel.y *= -0.45;
      else b.vel.y = 0;
      const f = Math.exp(-dt * 1.2);
      b.vel.x *= f;
      b.vel.z *= f;
    }
    // bounce off walls, trees and posts
    const before = b.pos.clone();
    this.world.collideBall?.(b.pos, b.r);
    const push = b.pos.clone().sub(before).setY(0);
    if (push.lengthSq() > 1e-6) {
      push.normalize();
      const vn = b.vel.x * push.x + b.vel.z * push.z;
      if (vn < 0) {
        b.vel.x -= 1.7 * vn * push.x;
        b.vel.z -= 1.7 * vn * push.z;
      }
    }
  }
  rollBall(b, dt) {
    const sp = Math.hypot(b.vel.x, b.vel.z);
    if (sp > 0.01) {
      const axis = new THREE.Vector3(b.vel.z, 0, -b.vel.x).normalize();
      b.mesh.rotateOnWorldAxis(axis, (sp * dt) / b.r);
    }
  }
  finishBall(b, dt, mine) {
    const sp = Math.hypot(b.vel.x, b.vel.z);
    // corrections from your person's copy are blended in, not jumped to
    const off = this.ballOff;
    if (off) {
      off.multiplyScalar(Math.exp(-dt * 8));
      if (off.lengthSq() < 1e-4) off.set(0, 0, 0);
    }
    b.mesh.position.copy(b.pos);
    if (off) b.mesh.position.add(off).setY(Math.max(b.r, b.mesh.position.y));
    // yours: keep their copy in step while it moves, and once more when it stops
    if (mine) {
      this.ballSendT = (this.ballSendT || 0) - dt;
      const moving = sp > 0.05 || b.pos.y > b.r + 0.01;
      if ((moving && this.ballSendT <= 0) || (!moving && this.ballMoving)) this.shareBall();
      this.ballMoving = moving;
    }
    // goal? (counted by whoever runs the ball, so it's only counted once)
    this.goalCooldown -= dt;
    if (!mine) return;
    const local = b.pos.clone().applyMatrix4(this.pitch.inv);
    const inGoal = this.goalSides.find((s) => local.z > s.z0 && local.z < s.z1 && Math.abs(local.x) < this.goalSize.w - 0.1 && local.y < this.goalSize.h);
    if (this.goalCooldown <= 0 && inGoal) {
      // the far (pink) goal scores for blue, and the other way round
      const team = inGoal.side > 0 ? "blue" : "pink";
      this.score[team]++;
      this.goals++;
      this.goalCooldown = 2;
      this.ui.toast(`goal for ${team}! ⋆ 💗 ${this.score.pink} : ${this.score.blue} 💙`);
      this.ui.confetti(b.pos);
      this.audio.sfx("win");
      this.ballSign.screen.draw(this.goalText());
      this.shareBall({ goal: team });
      setTimeout(() => {
        this.resetBall();
        if (!this.ballOwner) this.shareBall();
      }, 1200);
    }
  }

  moleAnim(m, dt) {
    const target = m.timer > 0 && !m.bonked ? 1 : 0;
    m.up += (target - m.up) * Math.min(1, dt * 12);
    m.group.position.y = -0.6 + m.up * 0.62;
    // squashed flat, then a little wobble back up
    m.group.scale.y = m.bonked > 0 ? 0.4 + Math.max(0, 0.45 - m.bonked) : 1;
    m.group.rotation.y = m.bonked > 0 ? m.bonked * 18 : 0;
    m.bonked = Math.max(0, m.bonked - dt);
    m.timer -= dt;
  }

  updateMoles(dt, player) {
    const r = this.round;
    r.time -= dt;
    r.spawn -= dt;
    // whoever started the round pops the moles; the other one sees the same ones
    if (r.host && r.spawn <= 0) {
      const idle = this.moles.filter((m) => m.timer <= 0);
      if (idle.length) {
        const m = idle[Math.floor(Math.random() * idle.length)];
        m.timer = 1.1 + Math.random() * 0.6;
        m.bonked = 0;
        this.sendMole?.({ i: this.moles.indexOf(m), d: +m.timer.toFixed(2) });
      }
      r.spawn = 0.45 + Math.random() * 0.35;
    }
    for (const m of this.moles) {
      // step on it while it peeks out (a little forgiving: you only need to reach the hole)
      if (m.timer > 0 && !m.bonked && m.up > 0.3 && Math.hypot(m.x - player.pos.x, m.z - player.pos.z) < 0.9) {
        this.bonkMole(m);
        this.ui.buzz?.();
        this.sendMole?.({ b: this.moles.indexOf(m) });
      }
      this.moleAnim(m, dt);
    }
    if (r.time <= 0) this.stop(true);
  }

  bonkMole(m) {
    m.bonked = 0.6;
    m.timer = 0.45;
    if (this.round) this.round.score++;
    this.audio.sfx("bonk");
    this.audio.sfx("pop");
    this.pop(m.x, m.z, this.round ? this.round.score : 0);
  }

  // a bonk you can't miss: "+1" and the new score float up, stars burst out
  // and the mole spins its eyes for a moment
  pop(x, z, score) {
    this.pops = this.pops || [];
    const c = document.createElement("canvas");
    c.width = 256;
    c.height = 128;
    const g = c.getContext("2d");
    g.textAlign = "center";
    g.textBaseline = "middle";
    g.font = 'bold 74px "Fredoka", "Quicksand", sans-serif';
    g.lineWidth = 14;
    g.strokeStyle = "#ffffff";
    g.strokeText("+1", 128, 52);
    g.fillStyle = "#e2557f";
    g.fillText("+1", 128, 52);
    if (score) {
      g.font = 'bold 34px "Fredoka", "Quicksand", sans-serif';
      g.lineWidth = 8;
      g.strokeText(`bonk! ⋆ ${score}`, 128, 104);
      g.fillStyle = "#7b5cd6";
      g.fillText(`bonk! ⋆ ${score}`, 128, 104);
    }
    const tex = new THREE.CanvasTexture(c);
    tex.colorSpace = THREE.SRGBColorSpace;
    const label = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, transparent: true, depthTest: false }));
    label.renderOrder = 10;
    label.scale.set(1.8, 0.9, 1);
    label.position.set(x, 1.0, z);
    this.scene.add(label);
    const stars = [];
    const starMat = new THREE.MeshBasicMaterial({ color: "#ffd166", transparent: true });
    for (let i = 0; i < 8; i++) {
      const st = new THREE.Mesh(new THREE.OctahedronGeometry(0.09, 0), starMat);
      const a = (i / 8) * Math.PI * 2;
      st.position.set(x, 0.35, z);
      st.userData.v = new THREE.Vector3(Math.cos(a) * 2.6, 3 + Math.random(), Math.sin(a) * 2.6);
      this.scene.add(st);
      stars.push(st);
    }
    const ring = new THREE.Mesh(new THREE.RingGeometry(0.2, 0.32, 20), new THREE.MeshBasicMaterial({ color: "#ff8fb1", transparent: true, side: THREE.DoubleSide }));
    ring.rotation.x = -Math.PI / 2;
    ring.position.set(x, 0.06, z);
    this.scene.add(ring);
    this.pops.push({ label, stars, ring, starMat, t: 0 });
  }
  updatePops(dt) {
    if (!this.pops?.length) return;
    this.pops = this.pops.filter((p) => {
      p.t += dt;
      const k = p.t / 0.9;
      p.label.position.y = 1.0 + Math.min(1, k * 1.6) * 1.1;
      const s = 1 + Math.max(0, 0.35 - p.t) * 2.2;
      p.label.scale.set(1.8 * s, 0.9 * s, 1);
      p.label.material.opacity = k < 0.6 ? 1 : Math.max(0, 1 - (k - 0.6) / 0.4);
      for (const st of p.stars) {
        st.userData.v.y -= 9 * dt;
        st.position.addScaledVector(st.userData.v, dt);
        st.rotation.y += dt * 8;
      }
      p.starMat.opacity = Math.max(0, 1 - k);
      p.ring.scale.setScalar(1 + k * 5);
      p.ring.material.opacity = Math.max(0, 0.9 - k);
      if (k < 1) return true;
      for (const o of [p.label, ...p.stars, p.ring]) {
        this.scene.remove(o);
        o.geometry?.dispose();
      }
      p.label.material.map.dispose();
      p.label.material.dispose();
      p.ring.material.dispose();
      p.starMat.dispose();
      return false;
    });
  }
  // your person started a round, popped a mole or bonked one
  onRemoteMole(p, name) {
    if (p.s) {
      if (this.active && this.active !== "moles") this.stop(false);
      this.active = "moles";
      this.round = { time: 30, score: 0, spawn: Infinity, host: false };
      this.ui.toast(`${name} started bonk-a-mole ⋆ step on the moles together!`);
      this.audio.sfx("start");
      return;
    }
    const m = this.moles[p.i ?? p.b];
    if (!m) return;
    if (p.d) {
      m.timer = p.d;
      m.bonked = 0;
      // seeing it even if you came late
      if (!this.active) {
        this.active = "moles";
        this.round = { time: 30, score: 0, spawn: Infinity, host: false };
      }
    } else if (p.b != null && !m.bonked) this.bonkMole(m);
  }

  updateBunnies(dt, player) {
    const r = this.round;
    r.time -= dt;
    for (const b of r.bunnies) {
      if (b.hidden) continue;
      if (Math.hypot(b.pos.x - player.pos.x, b.pos.z - player.pos.z) < 0.8) {
        b.hidden = true;
        this.creatures.remove(b);
        r.score++;
        this.audio.sfx("collect");
        this.ui.confetti(b.pos.clone().setY(0.5));
        this.ui.buzz?.();
      }
    }
    if (r.time <= 0 || r.bunnies.every((b) => b.hidden)) this.stop(true);
  }
}
