// Our pantry: what the farm and the garden give us, ready for dodo's bakery. Milk
// from the cows and goats, eggs from the hens, butter churned at the farm, flour
// from the golden wheat and fruit from the orchard trees. It's shared (shared.js),
// so whatever either of us brings in, both of us can bake with. Sugar, yeast,
// cinnamon, chocolate and salt come from the shop and never run out.
import { getShared, setShared, onShared } from "./shared.js";

export const PANTRY_KEY = "tdd3d.pantry";
// what the bakery needs from us (everything else in the bakery's pantry is bought)
export const GROWN = {
  milk: { emoji: "🥛", where: "milk a cow or a goat at our farm 🐄" },
  egg: { emoji: "🥚", where: "collect the eggs in the hen house 🐔" },
  butter: { emoji: "🧈", where: "churn some milk into butter at the farm 🧈" },
  flour: { emoji: "🌾", where: "grow golden wheat in the garden 🌾" },
  fruit: { emoji: "🍒", where: "pick fruit off the orchard trees in the garden forest 🍎" },
};
// a little to start with, so the bakery works before the first harvest
const START = { milk: 4, egg: 6, butter: 3, flour: 6, fruit: 3 };
const MAX = 99;

function read(raw = getShared(PANTRY_KEY)) {
  let d = null;
  try {
    d = JSON.parse(raw || "null");
  } catch {}
  const out = { have: { ...START }, cows: {}, eggT: 0 };
  if (d && typeof d === "object") {
    if (d.have && typeof d.have === "object") for (const k of Object.keys(GROWN)) out.have[k] = Math.max(0, Math.min(MAX, Math.round(Number(d.have[k]) || 0)));
    if (d.cows && typeof d.cows === "object") for (const [k, v] of Object.entries(d.cows)) if (Number.isFinite(Number(v))) out.cows[String(k).slice(0, 12)] = Number(v);
    out.eggT = Number(d.eggT) || 0;
  }
  return out;
}

export class Pantry {
  constructor({ isGuest, send } = {}) {
    this.isGuest = isGuest;
    this.send = send;
    this.state = read();
    this.listeners = new Set();
    onShared((key, value) => {
      if (key !== PANTRY_KEY) return;
      this.state = read(value);
      this.changed();
    });
  }
  onChange(fn) {
    this.listeners.add(fn);
    return () => this.listeners.delete(fn);
  }
  changed() {
    for (const fn of this.listeners) fn(this.state);
  }
  save() {
    const s = JSON.stringify(this.state);
    if (!this.isGuest) setShared(PANTRY_KEY, s);
    this.send?.({ s });
    this.changed();
  }
  // a copy from your person while you're both here
  remote(json) {
    if (typeof json !== "string" || json.length > 4000) return;
    this.state = read(json);
    this.changed();
  }
  count(id) {
    return this.state.have[id] ?? Infinity; // bought things are always there
  }
  add(id, n = 1) {
    if (!(id in GROWN) || n <= 0) return;
    this.state.have[id] = Math.min(MAX, (this.state.have[id] || 0) + n);
    this.save();
  }
  // take everything in the list, or nothing if something's missing
  take(ids) {
    const grown = ids.filter((id) => id in GROWN);
    if (grown.some((id) => (this.state.have[id] || 0) < 1)) return false;
    for (const id of grown) this.state.have[id]--;
    if (grown.length) this.save();
    return true;
  }
}
