// Far away all round the island: one long green mountain range rising out of the clouds,
// shaped by noise so no two peaks are alike, with ridges, saddles and valleys, pine
// forests on the gentler slopes, and waterfalls tumbling down the valleys towards us
// into the mist. Out past the race track and the clouds, drawn without the scene's fog
// (it would swallow them) and with their own soft haze at the foot instead.
import * as THREE from "three";

const TAU = Math.PI * 2;
const R0 = 150; // the range's inner foot, just past the race track and the clouds
const RV = 0; // the valley floor runs right under the island, closed in the middle, so there is never a hole to see the sky through
const R1 = 360; // its far edge
const FOOT = -72; // the valley floor, well below the island's rocky underside

// ---- noise -------------------------------------------------------------------------------
const hash2 = (x, y) => {
  const s = Math.sin(x * 127.1 + y * 311.7) * 43758.5453;
  return s - Math.floor(s);
};
function vnoise(x, y) {
  const xi = Math.floor(x), yi = Math.floor(y);
  const xf = x - xi, yf = y - yi;
  const u = xf * xf * (3 - 2 * xf), v = yf * yf * (3 - 2 * yf);
  const a = hash2(xi, yi), b = hash2(xi + 1, yi), c = hash2(xi, yi + 1), d = hash2(xi + 1, yi + 1);
  return a + (b - a) * u + (c - a) * v + (a - b - c + d) * u * v;
}
function fbm(x, y, oct = 5) {
  let s = 0, amp = 0.5, f = 1;
  for (let i = 0; i < oct; i++) {
    s += vnoise(x * f, y * f) * amp;
    f *= 2.03;
    amp *= 0.5;
  }
  return s;
}
// sharp crests: folded noise, each octave weighted by the one before
function ridged(x, y, oct = 5) {
  let s = 0, amp = 0.55, f = 1, w = 1;
  for (let i = 0; i < oct; i++) {
    const n = 1 - Math.abs(vnoise(x * f, y * f) * 2 - 1);
    s += n * n * amp * w;
    w = Math.min(1, n * 1.4);
    f *= 2.1;
    amp *= 0.5;
  }
  return s;
}
function rng(a) {
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// where the waterfalls are: each sits in a valley carved into the range
const FALLS = [0.35, 1.2, 2.05, 2.75, 3.6, 4.45, 5.2, 5.95].map((a, i) => ({ a: a + (hash2(i, 7) - 0.5) * 0.2, w: 0.035 + hash2(i, 3) * 0.02 }));

// the height of the range at (angle, radius)
// the green valley floor round the island: gently rolling, under everything
function valley(x, z) {
  return FOOT + fbm(x * 0.02 + 3, z * 0.02 + 9, 3) * 9 - 4.5;
}
function height(a, r) {
  const x = Math.cos(a) * r, z = Math.sin(a) * r;
  if (r < R0) return valley(x, z);
  const t = (r - R0) / (R1 - R0); // 0 at the inner foot, 1 at the far edge
  // rises steeply out of the clouds, peaks a third of the way back, then rolls on
  const hump = Math.sin(Math.min(1, Math.max(0, t) * 1.5) * Math.PI * 0.5) ** 1.6 * (1 - Math.max(0, t - 0.6) * 0.8);
  const big = fbm(x * 0.006 + 11, z * 0.006 - 4, 4); // where the tall massifs are
  const crest = ridged(x * 0.012, z * 0.012, 5);
  const bumps = fbm(x * 0.05, z * 0.05, 3);
  let h = valley(x, z) + hump * (45 + big * 105 + crest * 65) + bumps * 7 * Math.min(1, t * 4);
  // valleys for the waterfalls: a notch cut down into the slope
  for (const f of FALLS) {
    let d = a - f.a;
    d = Math.atan2(Math.sin(d), Math.cos(d));
    const k = Math.exp(-(d * d) / (2 * f.w * f.w));
    h -= k * 26 * Math.min(1, Math.max(0, t) * 2.2);
  }
  return h;
}

const C = {
  peak: new THREE.Color("#c2e3a4"),
  meadow: new THREE.Color("#8acb6e"),
  forest: new THREE.Color("#4f9a59"),
  deep: new THREE.Color("#3d7f4d"),
  rock: new THREE.Color("#9d97a2"),
  rockD: new THREE.Color("#7f7987"),
  haze: new THREE.Color("#cfe0ec"),
};

function buildRange(lowEnd) {
  const NA = lowEnd ? 200 : 320, NR = lowEnd ? 26 : 40;
  const grid = [];
  const NV = lowEnd ? 10 : 15; // rings across the valley floor
  for (let j = 0; j <= NR + NV; j++) {
    const r = j < NV ? RV + ((R0 - RV) * j) / NV : R0 + (R1 - R0) * ((j - NV) / NR) ** 1.25;
    const row = [];
    for (let i = 0; i <= NA; i++) {
      const a = ((i % NA) / NA) * TAU; // the seam meets itself exactly
      const rr = j ? r + (hash2(i % NA, j) - 0.5) * 2.5 : 0; // break the rings up a little (the middle is one point)
      row.push(new THREE.Vector3(Math.cos(a) * rr, height(a, rr), Math.sin(a) * rr));
    }
    grid.push(row);
  }
  const pos = [];
  const col = [];
  const c = new THREE.Color();
  const e1 = new THREE.Vector3(), e2 = new THREE.Vector3(), n = new THREE.Vector3();
  const tri = (p, q, s, k) => {
    pos.push(p.x, p.y, p.z, q.x, q.y, q.z, s.x, s.y, s.z);
    e1.subVectors(q, p);
    e2.subVectors(s, p);
    n.crossVectors(e1, e2).normalize();
    const slope = Math.abs(n.y); // 1 flat, 0 a cliff
    const y = (p.y + q.y + s.y) / 3;
    const rn = hash2(k, Math.round(y));
    if (y > 70 && slope > 0.5) c.copy(C.peak).lerp(C.meadow, rn * 0.4);
    else if (slope < 0.36) c.copy(C.rock).lerp(C.rockD, rn);
    else if (slope < 0.5) c.copy(C.rockD).lerp(C.forest, 0.6 + rn * 0.3);
    else c.copy(y > 20 ? C.meadow : C.forest).lerp(C.deep, rn * 0.5);
    c.lerp(C.haze, Math.min(0.35, Math.max(0, (-30 - y) / 140))); // a little haze down in the valley
    for (let v = 0; v < 3; v++) col.push(c.r, c.g, c.b);
  };
  for (let j = 0; j < NR + NV; j++) for (let i = 0; i < NA; i++) {
    const a = grid[j][i], b = grid[j][i + 1], d = grid[j + 1][i], e = grid[j + 1][i + 1];
    tri(a, b, d, i * 3 + j);
    tri(b, e, d, i * 5 + j * 7);
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute("position", new THREE.Float32BufferAttribute(pos, 3));
  geo.setAttribute("color", new THREE.Float32BufferAttribute(col, 3));
  geo.computeVertexNormals();
  return geo;
}

// streaks of white water, wrapping top to bottom
function fallTexture() {
  const cv = document.createElement("canvas");
  cv.width = 128;
  cv.height = 256;
  const g = cv.getContext("2d");
  const grd = g.createLinearGradient(0, 0, 128, 0);
  grd.addColorStop(0, "rgba(160,215,240,0)");
  grd.addColorStop(0.15, "rgba(170,222,245,0.8)");
  grd.addColorStop(0.85, "rgba(170,222,245,0.8)");
  grd.addColorStop(1, "rgba(160,215,240,0)");
  g.fillStyle = grd;
  g.fillRect(0, 0, 128, 256);
  const R = rng(5);
  for (let i = 0; i < 120; i++) {
    const x = 10 + R() * 108;
    const y = R() * 256;
    const h = 20 + R() * 70;
    const w = 1 + R() * 3;
    g.fillStyle = `rgba(255,255,255,${0.35 + R() * 0.6})`;
    g.fillRect(x, y, w, h);
    g.fillRect(x, y - 256, w, h); // wraps round
  }
  const t = new THREE.CanvasTexture(cv);
  t.wrapS = THREE.ClampToEdgeWrapping;
  t.wrapT = THREE.RepeatWrapping;
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}
let mistTex;
function mistSprite(size) {
  if (!mistTex) {
    const c = document.createElement("canvas");
    c.width = c.height = 128;
    const g = c.getContext("2d");
    const grd = g.createRadialGradient(64, 64, 0, 64, 64, 64);
    grd.addColorStop(0, "rgba(255,255,255,0.85)");
    grd.addColorStop(0.5, "rgba(255,255,255,0.35)");
    grd.addColorStop(1, "rgba(255,255,255,0)");
    g.fillStyle = grd;
    g.fillRect(0, 0, 128, 128);
    mistTex = new THREE.CanvasTexture(c);
  }
  const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: mistTex, transparent: true, depthWrite: false, fog: false, opacity: 0.8 }));
  s.scale.setScalar(size);
  return s;
}

export function buildScenery(world) {
  const group = new THREE.Group();
  world.scene.add(group);
  const lowEnd = world.lowEnd;

  const mat = new THREE.MeshStandardMaterial({ vertexColors: true, flatShading: true, roughness: 0.95, fog: false, side: THREE.DoubleSide });
  group.add(new THREE.Mesh(buildRange(lowEnd), mat));

  // pine forests on the gentler slopes, in clumps
  const R = rng(91);
  const spots = [];
  const want = lowEnd ? 1000 : 2600;
  for (let k = 0; spots.length < want && k < want * 8; k++) {
    const a0 = R() * TAU, r0 = RV + 15 + R() * 230;
    const m = 4 + Math.floor(R() * 10);
    for (let q = 0; q < m && spots.length < want; q++) {
      const a = a0 + (R() - 0.5) * 0.05, r = r0 + (R() - 0.5) * 14;
      const y = height(a, r);
      if (y > 80) continue;
      const dr = height(a, r + 2) - y;
      const da = height(a + 2 / r, r) - y;
      if (Math.hypot(dr, da) > 2.0) continue; // too steep for trees
      spots.push([Math.cos(a) * r, y, Math.sin(a) * r, 1.3 + R() * 1.5]);
    }
  }
  const pine = new THREE.ConeGeometry(1, 3, 6).translate(0, 1.5, 0);
  const pines = new THREE.InstancedMesh(pine, new THREE.MeshStandardMaterial({ flatShading: true, roughness: 0.9, fog: false }), spots.length);
  const mtx = new THREE.Matrix4();
  const q = new THREE.Quaternion();
  const up = new THREE.Vector3(0, 1, 0);
  const tint = new THREE.Color();
  spots.forEach(([x, y, z, s], i) => {
    pines.setMatrixAt(i, mtx.compose(new THREE.Vector3(x, y - 0.6, z), q.setFromAxisAngle(up, i), new THREE.Vector3(s, s * (1.1 + (i % 5) * 0.12), s)));
    pines.setColorAt(i, tint.set(["#3e7d4b", "#467f45", "#356f45", "#4f8a50"][i % 4]).lerp(C.haze, Math.min(0.3, Math.max(0, (-30 - y) / 140))));
  });
  group.add(pines);

  // the waterfalls: down each valley, hugging the slope, into the mist below
  const tex = fallTexture();
  const fallMat = new THREE.MeshStandardMaterial({ map: tex, transparent: true, depthWrite: false, side: THREE.DoubleSide, fog: false, roughness: 0.3, emissive: "#ffffff", emissiveMap: tex, emissiveIntensity: 0.3 });
  const falls = [];
  const poolMat = new THREE.MeshStandardMaterial({ color: "#8fd0ec", roughness: 0.15, fog: false });
  for (const f of FALLS) {
    const rTop = R0 + 50 + hash2(f.a, 2) * 20;
    const steps = 40;
    const pos = [], uv = [], idx = [];
    const width = 9 + hash2(f.a, 9) * 4;
    const tx = -Math.sin(f.a), tz = Math.cos(f.a); // across the fall, along the range
    let dist = 0;
    let prev = null;
    for (let k = 0; k <= steps; k++) {
      const u = k / steps;
      const r = rTop - (rTop - (R0 - 4)) * u;
      // the valley floor, a little above it; the water spreads out as it falls
      let y = Infinity;
      for (const o of [-0.4, 0, 0.4]) y = Math.min(y, height(f.a + (o * width) / r, r));
      y += 1.0 + u * 2.5;
      const p = new THREE.Vector3(Math.cos(f.a) * r, y, Math.sin(f.a) * r);
      if (prev) dist += p.distanceTo(prev);
      prev = p;
      const hw = (width / 2) * (0.6 + u * 0.9);
      pos.push(p.x - tx * hw, p.y, p.z - tz * hw, p.x + tx * hw, p.y, p.z + tz * hw);
      uv.push(0, dist / 30, 1, dist / 30); // v grows downhill
      if (k < steps) {
        const b = k * 2;
        idx.push(b, b + 1, b + 2, b + 1, b + 3, b + 2);
      }
    }
    const g = new THREE.BufferGeometry();
    g.setAttribute("position", new THREE.Float32BufferAttribute(pos, 3));
    g.setAttribute("uv", new THREE.Float32BufferAttribute(uv, 2));
    g.setIndex(idx);
    g.computeVertexNormals();
    falls.push(g);
    // a little pool where it starts, and spray where it plunges into the clouds
    const pool = new THREE.Mesh(new THREE.CircleGeometry(width * 0.8, 14), poolMat);
    pool.rotation.x = -Math.PI / 2;
    const pr = rTop + width * 0.4;
    pool.position.set(Math.cos(f.a) * pr, height(f.a, pr) + 1.1, Math.sin(f.a) * pr);
    group.add(pool);
    for (let m = 0; m < 3; m++) {
      const rr = R0 - 6 + m * 5;
      const s = mistSprite(16 + m * 6);
      s.position.set(Math.cos(f.a) * rr, height(f.a, rr) + 4 + m * 3, Math.sin(f.a) * rr);
      group.add(s);
    }
  }
  {
    const n = lowEnd ? 260 : 420;
    const pos = [], idx = [];
    const rr = (a) => R0 - 14 + Math.sin(a * 3 + 1) * 5 + Math.sin(a * 7) * 2.5;
    for (let i = 0; i <= n; i++) {
      const a = ((i % n) / n) * TAU;
      const r = rr(a);
      const w = 3.2 + Math.sin(a * 5) * 0.8;
      let y = -Infinity;
      for (const o of [-w, 0, w]) y = Math.max(y, height(a, r + o));
      for (const o of [-w, w]) pos.push(Math.cos(a) * (r + o), y + 0.6, Math.sin(a) * (r + o));
      if (i < n) idx.push(i * 2, i * 2 + 2, i * 2 + 1, i * 2 + 1, i * 2 + 2, i * 2 + 3);
    }
    const g = new THREE.BufferGeometry();
    g.setAttribute("position", new THREE.Float32BufferAttribute(pos, 3));
    g.setIndex(idx);
    g.computeVertexNormals();
    group.add(new THREE.Mesh(g, new THREE.MeshStandardMaterial({ color: "#7cc8e6", roughness: 0.2, metalness: 0.1, fog: false, side: THREE.DoubleSide })));
  }
  const fallMesh = new THREE.Mesh(mergeAll(falls), fallMat);
  fallMesh.renderOrder = 1;
  group.add(fallMesh);
  world.animated.push((t, dt = 0.016) => {
    tex.offset.y -= dt * 0.55; // the streaks run downhill (v grows downhill)
  });
  world.scenery = group;
  return group;
}

function mergeAll(geos) {
  let n = 0, m = 0;
  for (const g of geos) {
    n += g.attributes.position.count;
    m += g.index.count;
  }
  const pos = new Float32Array(n * 3), uv = new Float32Array(n * 2), nor = new Float32Array(n * 3);
  const idx = new Uint32Array(m);
  let o = 0, io = 0;
  for (const g of geos) {
    pos.set(g.attributes.position.array, o * 3);
    uv.set(g.attributes.uv.array, o * 2);
    nor.set(g.attributes.normal.array, o * 3);
    for (let i = 0; i < g.index.count; i++) idx[io + i] = g.index.array[i] + o;
    o += g.attributes.position.count;
    io += g.index.count;
  }
  const out = new THREE.BufferGeometry();
  out.setAttribute("position", new THREE.BufferAttribute(pos, 3));
  out.setAttribute("uv", new THREE.BufferAttribute(uv, 2));
  out.setAttribute("normal", new THREE.BufferAttribute(nor, 3));
  out.setIndex(new THREE.BufferAttribute(idx, 1));
  return out;
}
