// The island's trails, laid out as one network for the whole map rather than a path per
// place. Like a little village:
//
//   · the plaza ring round the willow, the heart of it all
//   · the pavilion lane, a ring just in front of every pavilion's door (and the diary's and
//     the bakery's), so the inner places are neighbours, not dead ends
//   · the grand avenue from the willow out to the gate, and three more at the compass points
//     from the willow out to the pavilion lane
//   · short spurs from the nearest trail to the doors that need one, found by walking
//     round whatever's in the way
//   · a little signpost at every crossing, its arrows naming where each way leads
//
// The rings and avenues bend round what's in their way on their own: every place's footprint
// is known, and each one is laid as the smoothest line that keeps clear of them all.
import * as THREE from "three";
import { std } from "./world.js";
import { FONT, texture } from "./textures.js";

const D2R = Math.PI / 180;
// places walked to across the grass, with no path of their own
const NO_PATH = new Set(["lake", "chill", "weather", "pinboard", "wishlist", "stall", "heart", "discord", "cinema", "balloon", "lookout", "swings"]);
const polar = (a, r) => [Math.sin(a * D2R) * r, Math.cos(a * D2R) * r];

// words for a place, without the decoration round the name
const plain = (s) => String(s).replace(/\p{Lm}/gu, " ").replace(/[^\p{L}\p{N}\s'’&]/gu, " ").replace(/\s+/g, " ").trim().toLowerCase();

export function layTrails(world, { ROOMS, SPREAD, GROW, ISLAND_R }) {
  // ---- what the trails keep clear of: every place, and the games' and rides' grounds -------
  const foot = [];
  const BY_KIND = { pavilion: 6.3, tower: 6.4, hall: 8.4, bakery: 9.6, deck: 5.8 };
  const BY_ID = { swings: 6.2, balloon: 6.6, lookout: 7.6, stall: 3.4, wishlist: 3.1, pinboard: 3.1, heart: 3.6, discord: 3.6, chill: 5.2, gate: 6.5 };
  for (const room of world.rooms.values()) {
    const d = room.def;
    if (d.id === "plaza") continue;
    const p = room.group.position;
    // (a building's own clearance when it has one: some have decks and steps round them)
    foot.push({ x: p.x, z: p.z, r: BY_ID[d.id] ?? (BY_KIND[d.kind] ? Math.max(BY_KIND[d.kind], d.clear || 0) : d.clear ?? 4), id: d.id });
  }
  const spot = (a, r) => polar(a, r * SPREAD);
  const SPOT = {
    ball: spot(258, 76),
    moles: spot(28, 64),
    bunnies: spot(100, 85),
    trail: polar(200, 43.5 + GROW),
    coaster: polar(135, 42.5 + GROW),
  };
  for (const q of world.reserved) {
    let id = "reserved";
    for (const [k, [x, z]] of Object.entries(SPOT)) if (Math.hypot(q.x - x, q.z - z) < 1) id = k;
    foot.push({ x: q.x, z: q.z, r: q.r, id });
  }
  const clearance = (x, z, hw, skip) => {
    let c = Infinity;
    for (const f of foot) {
      if (skip?.has(f.id)) continue;
      const d = Math.hypot(x - f.x, z - f.z) - f.r - hw;
      if (d < c) c = d;
    }
    return c;
  };
  const penalty = (c) => (c < 0 ? 400 + 300 * -c : c < 1.8 ? 20 * (1.8 - c) ** 2 : 0);
  const edge = (x, z) => {
    const r = Math.hypot(x, z);
    return r > ISLAND_R - 6 ? 60 * (r - (ISLAND_R - 6)) ** 2 : 0;
  };

  // ---- a line through a corridor: at each step along a base line, how far to one side it
  // goes is picked so the whole line is as smooth as it can be while keeping clear ----------
  function corridor({ n, base, offsets, nominal, lambda, mu, hw, skip, fixStart, fixEnd }) {
    const m = offsets.length;
    const cost = [];
    const from = [];
    for (let i = 0; i < n; i++) {
      const row = new Float64Array(m);
      const back = new Int16Array(m);
      for (let j = 0; j < m; j++) {
        const [x, z] = base(i, offsets[j]);
        let local = penalty(clearance(x, z, hw, skip)) + edge(x, z) + mu * (offsets[j] - nominal) ** 2;
        if (i === 0 && fixStart != null && Math.abs(offsets[j] - fixStart) > 1e-6) local += 1e9;
        if (i === n - 1 && fixEnd != null && Math.abs(offsets[j] - fixEnd) > 1e-6) local += 1e9;
        if (i === 0) {
          row[j] = local;
          continue;
        }
        let best = Infinity;
        let bk = 0;
        const prev = cost[i - 1];
        for (let k = 0; k < m; k++) {
          const v = prev[k] + lambda * (offsets[j] - offsets[k]) ** 2;
          if (v < best) {
            best = v;
            bk = k;
          }
        }
        row[j] = best + local;
        back[j] = bk;
      }
      cost.push(row);
      from.push(back);
    }
    let j = 0;
    for (let k = 1; k < m; k++) if (cost[n - 1][k] < cost[n - 1][j]) j = k;
    const pick = new Array(n);
    for (let i = n - 1; i >= 0; i--) {
      pick[i] = offsets[j];
      j = from[i][j];
    }
    // a soft final smoothing, so it flows rather than steps
    for (let pass = 0; pass < 5; pass++) {
      const prev = pick.slice();
      for (let i = 1; i < n - 1; i++) pick[i] = (prev[i - 1] + 2 * prev[i] + prev[i + 1]) / 4;
    }
    return pick.map((o, i) => base(i, o));
  }
  const range = (a, b, s) => Array.from({ length: Math.round((b - a) / s) + 1 }, (_, i) => a + i * s);
  // evenly spaced points along a smooth curve through pts
  const resample = (pts, closed = false, step = 0.6) => {
    const curve = new THREE.CatmullRomCurve3(pts.map(([x, z]) => new THREE.Vector3(x, 0, z)), closed, "centripetal", 0.5);
    const n = Math.max(2, Math.ceil(curve.getLength() / step));
    const out = curve.getSpacedPoints(n).map((p) => [p.x, p.z]);
    if (closed) out.pop();
    return out;
  };

  const lines = [];
  const network = []; // the main trails, that spurs join
  // 1 · the plaza ring round the willow (its middle a touch north of the island's)
  const ring0 = [];
  for (let i = 0; i < 112; i++) ring0.push(polar((i / 112) * 360, 12.5).map((v, k) => (k ? v - 0.5 : v)));
  lines.push({ pts: ring0, w: 2.1, closed: true, lift: 0.004, kind: "ring0" });
  network.push(lines[lines.length - 1]);

  // 2 · the pavilion lane
  {
    const n = 181;
    const pts = corridor({ n, base: (i, r) => polar(i * 2, r), offsets: range(19.5, 27, 0.5), nominal: 23, lambda: 16, mu: 0.4, hw: 1.05, fixStart: 23, fixEnd: 23 });
    pts.pop();
    lines.push({ pts: resample(pts, true), w: 2.0, closed: true, lift: 0.003, kind: "lane", name: "the pavilion lane" });
    network.push(lines[lines.length - 1]);
  }

  // 3 · the avenues, from the willow outwards, as straight as the way allows (laid out to the
  // island's edge first, so they run true, then cut back below)
  const AVENUES = [
    { id: "gate", a: 0, end: null, w: 2.6, to: "gate" },
    { id: "east", a: 100, end: Math.hypot(...SPOT.bunnies) - 5, w: 2.2, to: "bunnies" },
    { id: "north", a: 200, end: Math.hypot(...SPOT.trail) - 5, w: 2.2, to: "trail" },
    { id: "west", a: 268, end: 53.5, w: 2.2, to: "ball" },
  ];
  // where each place's door is, and which way is in towards the willow
  const doorOf = (def) => {
    const room = world.rooms.get(def.id);
    const len = Math.hypot(def.pos.x, def.pos.z);
    const dx = def.pos.x / len;
    const dz = def.pos.z / len;
    const off = def.pathOff ?? (def.kind === "pavilion" || def.kind === "tower" ? (def.r || 5.2) + 1.6 : def.kind === "deck" ? 5.5 : def.kind === "bakery" ? 5.1 : def.kind === "hall" ? 6.4 : 2.6);
    const reach = room?.doorReach;
    const d1 = reach ? len - reach * (def.scale || 1) + 0.25 : len - off;
    return { x: dx * d1, z: dz * d1, ux: -dx, uz: -dz, r: d1 };
  };
  const gateDef = ROOMS.find((d) => d.id === "gate");
  AVENUES[0].end = doorOf(gateDef).r;
  for (const av of AVENUES) {
    const s0 = 11.5;
    const n = Math.max(2, Math.round(av.end - s0) + 1);
    const ds = (av.end - s0) / (n - 1);
    const t = [Math.cos(av.a * D2R), -Math.sin(av.a * D2R)];
    const base = (i, o) => {
      const [x, z] = polar(av.a, s0 + i * ds);
      return [x + t[0] * o, z + t[1] * o];
    };
    const pts = corridor({ n, base, offsets: range(-6, 6, 0.5), nominal: 0, lambda: 14, mu: 0.6, hw: av.w / 2, skip: new Set([av.to]), fixStart: 0, fixEnd: 0 });
    // (it starts right on the plaza ring's middle line, not inside it: the ring's middle sits a
    // touch north of the island's, so a fixed start left a stub poking in towards the willow)
    const laid = resample(pts);
    const from = laid.findIndex(([x, z]) => Math.hypot(x, z + 0.5) >= 12.5);
    const line = { pts: laid.slice(Math.max(0, from)), w: av.w, pebbleFrom: 1.3, room: av.to, kind: "avenue", avenue: av };
    lines.push(line);
    network.push(line);
    av.line = line;
  }

  // 4 · the east, north and west avenues stop at the pavilion lane: past it there's nothing
  // left out there to walk to (those places are reached across the grass)
  {
    const lane = network.find((l) => l.kind === "lane");
    for (const av of AVENUES.slice(1)) {
      let ka = 0;
      let bd = Infinity;
      av.line.pts.forEach(([x, z], k) => {
        for (const [px, pz] of lane.pts) {
          const d = Math.hypot(px - x, pz - z);
          if (d < bd) {
            bd = d;
            ka = k;
          }
        }
      });
      av.line.pts = av.line.pts.slice(0, ka + 1);
      delete av.line.room;
      av.trimmed = true;
    }
  }

  // ---- spurs: from each door to the nearest trail, round whatever's in the way ---------------
  const G = 1; // grid cell
  const H = Math.ceil(ISLAND_R) + 2;
  const N = H * 2 + 1;
  const cellOf = (x, z) => [Math.round(x / G) + H, Math.round(z / G) + H];
  const idx = (i, j) => j * N + i;
  // cells right on a main trail: where a spur arrives
  const onTrail = new Int16Array(N * N).fill(-1);
  network.forEach((line, li) => {
    for (const [x, z] of line.pts) {
      const [ci, cj] = cellOf(x, z);
      const rad = Math.ceil(line.w / 2);
      for (let di = -rad; di <= rad; di++) for (let dj = -rad; dj <= rad; dj++) {
        const i = ci + di, j = cj + dj;
        if (i < 0 || j < 0 || i >= N || j >= N) continue;
        if (Math.hypot((i - H) * G - x, (j - H) * G - z) <= line.w / 2 + 0.2) onTrail[idx(i, j)] = li;
      }
    }
  });
  function route(from, skip) {
    // the cost of walking each cell (built per spur: what it may brush past differs)
    const cost = (i, j) => {
      const x = (i - H) * G, z = (j - H) * G;
      if (Math.hypot(x, z) > ISLAND_R - 4.5) return Infinity;
      const c = clearance(x, z, 0.85, skip);
      return c < 0 ? Infinity : 1 + Math.max(0, 1.6 - c) * 5;
    };
    const memo = new Float32Array(N * N).fill(-1);
    const costAt = (i, j) => {
      const k = idx(i, j);
      if (memo[k] < 0) memo[k] = cost(i, j);
      return memo[k];
    };
    const [si, sj] = cellOf(from[0], from[1]);
    const dist = new Float32Array(N * N).fill(Infinity);
    const prev = new Int32Array(N * N).fill(-1);
    // a small binary heap
    const heap = [];
    const push = (k, d) => {
      heap.push([k, d]);
      let i = heap.length - 1;
      while (i > 0) {
        const p = (i - 1) >> 1;
        if (heap[p][1] <= heap[i][1]) break;
        [heap[p], heap[i]] = [heap[i], heap[p]];
        i = p;
      }
    };
    const pop = () => {
      const top = heap[0];
      const last = heap.pop();
      if (heap.length) {
        heap[0] = last;
        let i = 0;
        for (;;) {
          const l = i * 2 + 1, r = l + 1;
          let m = i;
          if (l < heap.length && heap[l][1] < heap[m][1]) m = l;
          if (r < heap.length && heap[r][1] < heap[m][1]) m = r;
          if (m === i) break;
          [heap[m], heap[i]] = [heap[i], heap[m]];
          i = m;
        }
      }
      return top;
    };
    const s = idx(si, sj);
    dist[s] = 0;
    push(s, 0);
    let goal = -1;
    while (heap.length) {
      const [k, d] = pop();
      if (d > dist[k]) continue;
      if (onTrail[k] >= 0) {
        goal = k;
        break;
      }
      const i = k % N, j = (k / N) | 0;
      for (let di = -1; di <= 1; di++) for (let dj = -1; dj <= 1; dj++) {
        if (!di && !dj) continue;
        const ni = i + di, nj = j + dj;
        if (ni < 0 || nj < 0 || ni >= N || nj >= N) continue;
        const c = costAt(ni, nj);
        if (c === Infinity) continue;
        const nk = idx(ni, nj);
        const nd = d + c * (di && dj ? Math.SQRT2 : 1);
        if (nd < dist[nk]) {
          dist[nk] = nd;
          prev[nk] = k;
          push(nk, nd);
        }
      }
    }
    if (goal < 0) return null;
    const cells = [];
    for (let k = goal; k >= 0; k = prev[k]) cells.push([((k % N) - H) * G, (((k / N) | 0) - H) * G]);
    cells.reverse(); // from the door's side out to the trail
    // pull it taut where nothing's in the way
    const sees = (a, b) => {
      const L = Math.hypot(b[0] - a[0], b[1] - a[1]);
      for (let t = 0; t <= L; t += 0.4) {
        const x = a[0] + ((b[0] - a[0]) * t) / L, z = a[1] + ((b[1] - a[1]) * t) / L;
        const [ci, cj] = cellOf(x, z);
        if (costAt(ci, cj) > 1.6) return false;
      }
      return true;
    };
    const taut = [from];
    let i = 0;
    const all = [from, ...cells];
    while (i < all.length - 1) {
      let j = all.length - 1;
      while (j > i + 1 && !sees(all[i], all[j])) j--;
      taut.push(all[j]);
      i = j;
    }
    return { pts: taut, line: onTrail[goal] };
  }
  // the nearest point on a trail, and where along it
  const nearestOn = (line, x, z) => {
    let best = 0;
    let bd = Infinity;
    line.pts.forEach(([px, pz], k) => {
      const d = Math.hypot(px - x, pz - z);
      if (d < bd) {
        bd = d;
        best = k;
      }
    });
    return { k: best, p: line.pts[best], d: bd };
  };
  const spurs = [];
  const addSpur = ({ id, name, door, lead, skip, w = 1.6, lift = 0, tail = [] }) => {
    // the last bit straight in to the door
    const L = [door.x + door.ux * lead, door.z + door.uz * lead];
    const r = route(L, skip);
    if (!r) return;
    const host = network[r.line];
    const join = nearestOn(host, ...r.pts[r.pts.length - 1]);
    // from the trail to the door: a smooth line, meeting the trail square on
    const raw = [join.p, ...r.pts.slice(0, -1).reverse(), ...tail, [door.x, door.z]];
    // drop points that bunch up
    const pts = [raw[0]];
    for (const p of raw.slice(1)) if (Math.hypot(p[0] - pts[pts.length - 1][0], p[1] - pts[pts.length - 1][1]) > 0.8) pts.push(p);
    if (pts.length < 2) return;
    const line = { pts: resample(pts.length === 2 ? [pts[0], [(pts[0][0] + pts[1][0]) / 2, (pts[0][1] + pts[1][1]) / 2], pts[1]] : pts), w, pebbleFrom: 1.3, room: id, lift, kind: "spur" };
    lines.push(line);
    spurs.push({ id, name, host, k: join.k, line });
  };
  const label = (def) => `${def.emoji || "✿"} ${plain(def.name)}`;
  const dests = new Map(ROOMS.map((d) => [d.id, label(d)]));
  dests.set("bunnies", "🐰 catch the bunnies");
  dests.set("trail", "☁️ sky trail");
  dests.set("ball", "⚽ goal kick");
  dests.set("coaster", "🎢 sky coaster");
  dests.set("plaza", "🌳 our willow");
  dests.set("gate", "🌷 the gate");
  for (const def of ROOMS) {
    // the plaza is the hub; the garden is reached from the bakery's back door; the gate is the
    // grand avenue's end
    if (def.id === "plaza" || def.id === "garden" || def.id === "gate") continue;
    // places out in the open, walked to across the grass: no path of their own
    if (NO_PATH.has(def.id)) continue;
    if (def.id === "gift") {
      // toto's gift: from the landing where the north avenue crosses the pavilion lane,
      // a gentle curve straight in to its door
      const lane = network.find((l) => l.kind === "lane");
      let best = null;
      for (const [x, z] of AVENUES[2].line.pts) {
        const q = nearestOn(lane, x, z);
        if (!best || q.d < best.d) best = { d: q.d, p: [x, z] };
      }
      const door = doorOf(def);
      const lead = [door.x + door.ux * 2.4, door.z + door.uz * 2.4];
      const V = (x, z) => new THREE.Vector3(x, 0, z);
      const c = new THREE.CubicBezierCurve3(V(...best.p), V((best.p[0] * 2 + lead[0]) / 3, (best.p[1] * 2 + lead[1]) / 3), V(...lead), V(door.x, door.z));
      const pts = c.getSpacedPoints(Math.max(4, Math.ceil(c.getLength() / 0.6))).map((p) => [p.x, p.z]);
      lines.push({ pts, w: 1.6, pebbleFrom: 1.3, room: def.id, kind: "spur" });
      continue;
    }
    const door = doorOf(def);
    addSpur({ id: def.id, name: dests.get(def.id), door, lead: def.kind === "pavilion" || def.kind === "tower" ? 1.2 : 2, skip: new Set([def.id]), w: def.id === "farm" ? 2.2 : 1.6 /* (as wide as the farm's own lane, which it runs straight into) */ });
  }
  {
    // the sky coaster's archway faces in, 3.75 in front of the station
    const [cx, cz] = SPOT.coaster;
    const cr = Math.hypot(cx, cz);
    const vx = -cx / cr, vz = -cz / cr;
    addSpur({ id: "coaster", name: dests.get("coaster"), door: { x: cx + vx * 4.4, z: cz + vz * 4.4, ux: vx, uz: vz }, lead: 2.5, skip: new Set(["coaster"]) });
  }

  // ---- signposts at the crossings ----------------------------------------------------------
  const signposts = [];
  const ringLines = network.filter((l) => l.kind === "lane");
  const along = (line, k, dir) => {
    // the way along a trail from point k: a unit vector, looking a few steps ahead
    const n = line.pts.length;
    const step = (i) => (line.closed ? (i + n) % n : Math.max(0, Math.min(n - 1, i)));
    const a = line.pts[step(k)], b = line.pts[step(k + dir * 4)];
    const l = Math.hypot(b[0] - a[0], b[1] - a[1]) || 1;
    return [(b[0] - a[0]) / l, (b[1] - a[1]) / l];
  };
  const named = (line, k, dir, extra = []) => {
    // the first places whose spurs leave this trail that way (the next one or two along)
    const n = line.pts.length;
    const out = spurs
      .filter((s) => s.host === line)
      .map((s) => ({ s, d: line.closed ? (dir > 0 ? (s.k - k + n) % n : (k - s.k + n) % n) : dir > 0 ? s.k - k : k - s.k }))
      .filter((o) => o.d > 2)
      .sort((a, b) => a.d - b.d)
      .map((o) => o.s.name);
    return [...out, ...extra].slice(0, 2);
  };
  for (const av of AVENUES) {
    for (const ring of ringLines) {
      // where the avenue crosses the ring
      let best = null;
      av.line.pts.forEach(([x, z], ka) => {
        const q = nearestOn(ring, x, z);
        if (!best || q.d < best.d) best = { ka, kr: q.k, d: q.d, p: [x, z] };
      });
      if (!best || best.d > 1.5) continue;
      const boards = [];
      // along the ring, both ways
      for (const dir of [1, -1]) {
        if (!ring.closed && (dir > 0 ? best.kr > ring.pts.length - 6 : best.kr < 5)) continue;
        const names = named(ring, best.kr, dir);
        if (names.length) boards.push({ dir: along(ring, best.kr, dir), names });
      }
      // along the avenue: in to the willow, and out to its end
      boards.push({ dir: along(av.line, best.ka, -1), names: [dests.get("plaza")] });
      const outNames = named(av.line, best.ka, 1, av.trimmed ? [] : [dests.get(av.to)]);
      if (best.ka < av.line.pts.length - 6) boards.push({ dir: along(av.line, best.ka, 1), names: outNames });
      // stand it on the corner with the most room
      const ta = along(av.line, best.ka, 1);
      const tr = along(ring, best.kr, 1);
      let spotAt = null;
      for (const o of [av.w / 2 + 1.0, av.w / 2 + 1.6, av.w / 2 + 2.3]) for (const sa of [1, -1]) for (const sr of [1, -1]) {
        const x = best.p[0] + (ta[0] * sr + tr[0] * sa) * o * 0.9 + (-ta[1] * sa) * 0.3;
        const z = best.p[1] + (ta[1] * sr + tr[1] * sa) * o * 0.9 + (ta[0] * sa) * 0.3;
        let room = Infinity;
        for (const l of lines) for (const [px, pz] of l.pts) room = Math.min(room, Math.hypot(px - x, pz - z) - l.w / 2);
        room = Math.min(room, clearance(x, z, 0.3));
        if (!spotAt || room > spotAt.room) spotAt = { x, z, room };
      }
      // a little round landing where they cross (a disc: a ring as wide as its radius twice over)
      const R = 2.7;
      const disc = [];
      for (let i = 0; i < 40; i++) disc.push(polar((i / 40) * 360, R / 2).map((v, k) => v + best.p[k]));
      lines.push({ pts: disc, w: R, closed: true, lift: 0.006, kind: "landing", pebbles: false });
      if (spotAt && spotAt.room > 0.15) signposts.push({ x: spotAt.x, z: spotAt.z, boards });
    }
  }
  // where the gate avenue meets the plaza ring: one more, to welcome you in
  {
    const g = AVENUES[0].line;
    const k = g.pts.findIndex(([x, z]) => Math.hypot(x, z + 0.5) > 14.6);
    if (k > 0) {
      const [x, z] = g.pts[k];
      const t = along(g, k, 1);
      signposts.push({
        x: x + -t[1] * 2.1,
        z: z + t[0] * 2.1,
        boards: [
          { dir: along(g, k, -1), names: [dests.get("plaza")] },
          { dir: along(g, k, 1), names: [dests.get("gate")] },
        ],
      });
    }
  }
  return { lines, signposts, foot, network };
}

// ---- the signposts: a wooden post with arrow boards, a heart on top ------------------------
const boardTex = new Map();
function boardTexture(names, flip) {
  const key = names.join("|") + (flip ? "<" : ">");
  if (boardTex.has(key)) return boardTex.get(key);
  const c = document.createElement("canvas");
  c.width = 512;
  c.height = names.length > 1 ? 176 : 112;
  const x = c.getContext("2d");
  const W = c.width, Hh = c.height;
  // the board: a cream plank with a point at one end
  x.save();
  if (flip) {
    x.translate(W, 0);
    x.scale(-1, 1);
  }
  x.beginPath();
  const tip = 56;
  x.moveTo(16, 10);
  x.lineTo(W - tip, 10);
  x.lineTo(W - 8, Hh / 2);
  x.lineTo(W - tip, Hh - 10);
  x.lineTo(16, Hh - 10);
  x.quadraticCurveTo(4, Hh / 2, 16, 10);
  x.closePath();
  x.fillStyle = "#fff4ea";
  x.fill();
  x.lineWidth = 8;
  x.strokeStyle = "#e7a1b8";
  x.stroke();
  x.restore();
  x.fillStyle = "#6b4a5e";
  x.textAlign = "center";
  x.textBaseline = "middle";
  const tx = flip ? W / 2 + 22 : W / 2 - 22;
  const fit = (s) => {
    let size = 42;
    x.font = `700 ${size}px ${FONT}`;
    while (x.measureText(s).width > W - 120 && size > 22) x.font = `700 ${--size}px ${FONT}`;
  };
  if (names.length > 1) {
    fit(names[0]);
    x.fillText(names[0], tx, Hh * 0.33);
    fit(names[1]);
    x.fillText(names[1], tx, Hh * 0.7);
  } else {
    fit(names[0]);
    x.fillText(names[0], tx, Hh / 2 + 2);
  }
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  t.anisotropy = 4;
  boardTex.set(key, t);
  return t;
}
export function buildSignposts(root, signposts, { addCircle }) {
  // (pale wood and a pink-cream edge, like the welcome sign at the gate)
  const wood = std("#ffffff", { map: texture("wood", ["#fff3ea", "#e8d4c8"]), key: "signWood" });
  const edge = std("#f4d9e6", { key: "signEdge" });
  const pink = std("#ff8fb1", { key: "signHeart" });
  const postGeo = new THREE.CylinderGeometry(0.07, 0.09, 2.5, 8).translate(0, 1.25, 0);
  const capGeo = new THREE.SphereGeometry(0.13, 10, 8);
  const heart = (() => {
    const s = new THREE.Shape();
    s.moveTo(0, -0.5);
    s.bezierCurveTo(-0.9, 0.1, -0.4, 0.8, 0, 0.35);
    s.bezierCurveTo(0.4, 0.8, 0.9, 0.1, 0, -0.5);
    const g = new THREE.ExtrudeGeometry(s, { depth: 0.12, bevelEnabled: true, bevelSize: 0.04, bevelThickness: 0.04, bevelSegments: 2 });
    g.center();
    return g;
  })();
  const group = new THREE.Group();
  for (const sp of signposts) {
    const g = new THREE.Group();
    g.position.set(sp.x, 0, sp.z);
    const post = new THREE.Mesh(postGeo, wood);
    post.castShadow = true;
    g.add(post);
    const cap = new THREE.Mesh(capGeo, wood);
    cap.position.y = 2.52;
    g.add(cap);
    const h = new THREE.Mesh(heart, pink);
    h.scale.setScalar(0.34);
    h.position.y = 2.82;
    g.add(h);
    // a few flowers at its foot
    const cols = ["#ff9fc0", "#fff7f2", "#ffd166", "#c7b0f5"];
    for (let k = 0; k < 7; k++) {
      const a = k * 0.9;
      const f = new THREE.Mesh(new THREE.IcosahedronGeometry(0.07, 0), std(cols[k % 4], { key: `signF${k % 4}` }));
      f.position.set(Math.sin(a) * 0.28, 0.12 + (k % 2) * 0.05, Math.cos(a) * 0.28);
      g.add(f);
    }
    sp.boards.forEach((b, i) => {
      const two = b.names.length > 1;
      const w = 1.5, hgt = two ? 0.52 : 0.33;
      const y = 2.15 - i * 0.5 - (two ? 0.08 : 0);
      const holder = new THREE.Group();
      holder.position.y = y;
      // the board's length runs along local +x: turn it to point the way it names
      holder.rotation.y = Math.atan2(-b.dir[1], b.dir[0]);
      g.add(holder);
      const plank = new THREE.Mesh(new THREE.BoxGeometry(w, hgt, 0.04), edge);
      plank.position.x = w / 2 - 0.05;
      plank.castShadow = true;
      holder.add(plank);
      for (const side of [1, -1]) {
        const face = new THREE.Mesh(new THREE.PlaneGeometry(w, hgt), new THREE.MeshBasicMaterial({ map: boardTexture(b.names, side < 0), transparent: true, alphaTest: 0.3, toneMapped: false }));
        face.position.set(w / 2 - 0.05, 0, side * 0.023);
        if (side < 0) face.rotation.y = Math.PI;
        holder.add(face);
      }
    });
    group.add(g);
    addCircle(sp.x, sp.z, 0.16);
  }
  root.add(group);
  return group;
}
