// Meet in the world: when you are both online, each of you sees the other
// walking around. Uses the site's own Supabase realtime connection
// (broadcast + presence on one channel), so no database tables are needed.
import * as THREE from "three";
import { Avatar } from "./avatar.js";
import { textCanvas, FONT } from "./textures.js";
import { makeRifle } from "./fx.js";
import { makeScooter, animateScooter, SEAT_H, makeUnicorn, animateUnicorn, UNI_SEAT_H, UNI_FRONT, UNI_BACK } from "./vehicle.js";
import { WORLD_CHANNEL } from "./guest.js";

const CHANNEL = WORLD_CHANNEL;
const SEND_MS = 100;

function nameTag(text) {
  const { ctx, tex } = textCanvas(512, 128);
  ctx.font = `700 46px ${FONT}`;
  const w = Math.min(500, ctx.measureText(text).width + 50);
  ctx.fillStyle = "rgba(226,85,127,0.85)";
  ctx.beginPath();
  ctx.roundRect((512 - w) / 2, 28, w, 72, 36);
  ctx.fill();
  ctx.fillStyle = "#fff";
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.fillText(text, 256, 65);
  tex.needsUpdate = true;
  const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, transparent: true, depthWrite: false }));
  s.scale.set(2.2, 0.55, 1);
  s.renderOrder = 6;
  return s;
}

export class Net {
  constructor({ scene, getState, onJoin, onLeave, onEmote, onAnyEmote, onHit, onPaint, onCinema, onX, pets, guest, validGuest, onDenied }) {
    this.onX = onX;
    this.pets = pets;
    this.guest = guest || null;
    this.validGuest = validGuest;
    this.onDenied = onDenied;
    this.denyAt = new Map();
    this.onCinema = onCinema;
    this.onPaint = onPaint;
    this.onAnyEmote = onAnyEmote;
    this.onHit = onHit;
    this.scene = scene;
    this.getState = getState;
    this.onJoin = onJoin;
    this.onLeave = onLeave;
    this.onEmote = onEmote;
    this.remotes = new Map();
    this.session = Math.random().toString(36).slice(2, 10);
    this.sendTimer = 0;
    this.cfgTimer = 0;
    this.channel = null;
    this.retry = setInterval(() => this.connect(), 3000);
    this.connect();
  }

  get myKey() {
    return `${this.userId}:${this.session}`;
  }

  connect() {
    if (this.channel) return;
    const bridge = window.__tddBridge;
    const user = this.guest ? { id: `guest-${this.guest.token}` } : bridge?.getUser?.();
    if (!bridge?.supabase || !user) return;
    this.userId = user.id;
    const ch = bridge.supabase.channel(CHANNEL, {
      config: { broadcast: { self: false }, presence: { key: `${user.id}:${this.session}` } },
    });
    this.channel = ch;
    this.supabase = bridge.supabase;
    ch.on("broadcast", { event: "state" }, ({ payload }) => this.receive(payload));
    ch.on("broadcast", { event: "emote" }, ({ payload }) => {
      const r = this.remotes.get(payload.key);
      if (r) r.avatar.playEmote(payload.emote);
      this.onAnyEmote?.(payload, r);
      if (payload.to === `${this.userId}:${this.session}`) this.onEmote?.(payload, r);
    });
    ch.on("broadcast", { event: "paint" }, ({ payload }) => {
      if (this.guest || this.isGuestKey(payload?.key)) return;
      this.onPaint?.(payload);
    });
    // everything else: chat, voice, photos, the tree, visitors
    ch.on("broadcast", { event: "x" }, ({ payload }) => {
      if (!payload || payload.key === this.myKey) return;
      if (payload.to && payload.to !== this.myKey) return;
      if (payload.t === "deny") {
        if (this.guest) this.onDenied?.(payload.why);
        return;
      }
      const r = this.remotes.get(payload.key);
      // visitors only reach us once we've let them in
      if (this.isGuestKey(payload.key) && !r) return;
      this.onX?.(payload, r);
    });
    ch.on("broadcast", { event: "cinema" }, ({ payload }) => {
      if (payload?.key === `${this.userId}:${this.session}`) return;
      if (this.isGuestKey(payload?.key)) return; // visitors only watch
      this.onCinema?.(payload, this.remotes.get(payload.key)?.name);
    });
    ch.on("broadcast", { event: "hit" }, ({ payload }) => {
      if (this.isGuestKey(payload.key)) return;
      if (payload.to === `${this.userId}:${this.session}`) this.onHit?.(payload, this.remotes.get(payload.key));
    });
    ch.on("presence", { event: "sync" }, () => {
      const present = new Set(Object.keys(ch.presenceState()));
      for (const key of [...this.remotes.keys()]) if (!present.has(key)) this.drop(key);
    });
    ch.subscribe((status) => {
      if (status === "SUBSCRIBED") {
        this.connected = true;
        ch.track({ at: Date.now() }).catch(() => {});
        clearInterval(this.retry);
      } else if (status === "CHANNEL_ERROR" || status === "TIMED_OUT" || status === "CLOSED") {
        this.connected = false;
      }
    });
  }

  isGuestKey(key) {
    return typeof key === "string" && key.startsWith("guest-");
  }

  receive(p) {
    if (!p || p.key === `${this.userId}:${this.session}`) return;
    // you on another phone or tab: not a second person (it stole the "find
    // your person" pin and the meet-up from your partner)
    if (typeof p.key === "string" && p.key.startsWith(`${this.userId}:`)) return;
    // visitors: only with a link that's still good (visitors don't see other visitors)
    if (this.isGuestKey(p.key)) {
      const token = p.key.slice(6).split(":")[0];
      if (this.guest || !this.validGuest?.(token)) {
        if (!this.guest) {
          const last = this.denyAt.get(p.key) || 0;
          if (Date.now() - last > 5000) {
            this.denyAt.set(p.key, Date.now());
            this.send("deny", { why: "expired" }, p.key);
          }
        }
        if (this.remotes.has(p.key)) this.drop(p.key);
        return;
      }
    }
    let r = this.remotes.get(p.key);
    if (!r) {
      if (!p.cfg) return; // wait for a full update with the avatar
      const avatar = new Avatar(p.cfg);
      const tag = nameTag(p.name || "♡");
      this.scene.add(avatar.root, tag);
      r = {
        key: p.key,
        user: p.user,
        avatar,
        tag,
        name: p.name,
        cfgKey: JSON.stringify(p.cfg),
        pos: new THREE.Vector3(p.x, p.y, p.z),
        target: new THREE.Vector3(p.x, p.y, p.z),
        facing: p.f,
        targetFacing: p.f,
        speed: 0,
        air: false,
        vy: 0,
        seen: performance.now(),
      };
      avatar.root.position.copy(r.pos);
      avatar.root.userData.remote = r;
      r.guest = this.isGuestKey(p.key);
      this.remotes.set(p.key, r);
      this.onJoin?.(r);
    }
    if (p.tp && !r.guest) this.onTripod?.(p.tp, r);
    if (p.cfg) {
      const key = JSON.stringify(p.cfg);
      if (key !== r.cfgKey) {
        r.cfgKey = key;
        r.avatar.setConfig(p.cfg);
        if (r.rifle) r.avatar.arms?.[1]?.elbow.add(r.rifle);
      }
    }
    // their pets
    if (p.pet && this.pets) {
      const key = JSON.stringify(p.pet);
      if (key !== r.petKey) {
        r.petKey = key;
        this.pets.drop(r.petList);
        r.petList = this.pets.make(p.pet);
        for (const c of r.petList) c.owner = r;
      }
    }
    if (p.pp && r.petList) {
      p.pp.forEach((s, i) => {
        const c = r.petList[i];
        if (!c) return;
        c.target = c.target || new THREE.Vector3();
        c.target.set(s[0], 0, s[1]);
        if (!c.placed) {
          c.pos.copy(c.target);
          c.placed = true;
        }
        c.speed = s[3];
        c.mode = s[4] ? "idle" : "walk";
        this.pets.apply(c, s);
      });
    }
    // their rifle
    if (p.g && !r.rifle) {
      r.rifle = makeRifle().group;
      r.avatar.arms?.[1]?.elbow.add(r.rifle);
    }
    if (r.rifle) r.rifle.visible = Boolean(p.g);
    // their scooter
    // (or their unicorn)
    if (r.scooter && r.scooterColor !== p.v) {
      this.scene.remove(r.scooter.root);
      r.scooter = null;
    }
    if (p.v && !r.scooter) {
      r.scooter = p.v === "unicorn" ? makeUnicorn() : makeScooter(p.v);
      r.scooterColor = p.v;
      this.scene.add(r.scooter.root);
    }
    // holding on behind someone on a unicorn (their key, or mine)
    r.pl = p.pl || 0;
    r.cs = p.cs || 0; // their seat on the sky coaster (1-based)
    r.bn = p.bn || 0; // their seat in the balloon (1-based)
    r.bt = Number(p.bt) || 0; // when their balloon trip started (balloon.js)
    r.pc = Boolean(p.pc); // floating down under a parachute
    r.vo = Boolean(p.vo);
    r.avatar.pose = p.po || null;
    // on a swing: which one, and since when (by our clock; only reset when it drifts, so it
    // never stutters)
    if (Array.isArray(p.sw) && p.sw[0] > 0) {
      const t0 = performance.now() / 1000 - (Number(p.sw[1]) || 0);
      if (!r.sw || r.sw.i !== p.sw[0] - 1 || Math.abs(r.sw.t0 - t0) > 0.35) r.sw = { i: p.sw[0] - 1, t0 };
    } else r.sw = null;
    if (p.name && p.name !== r.name) {
      r.name = p.name;
      this.scene.remove(r.tag);
      r.tag = nameTag(p.name);
      this.scene.add(r.tag);
    }
    r.target.set(p.x, p.y, p.z);
    r.targetFacing = p.f;
    r.speed = p.s;
    r.air = p.a;
    r.vy = p.vy;
    r.k = p.k;
    r.avatar.sitting = Boolean(p.st) || Boolean(p.v) || Boolean(p.pl);
    r.avatar.riding = Boolean(p.v) || Boolean(p.pl);
    r.avatar.lounge = p.lo === 1 && Boolean(p.st);
    r.avatar.floorSit = p.lo === 2 && Boolean(p.st);
    r.avatar.seatH = p.v === "unicorn" || p.pl ? UNI_SEAT_H : p.v ? SEAT_H : p.st || 0.45;
    r.avatar.aiming = p.g;
    r.avatar.lying = Boolean(p.ly) && r.avatar.sitting;
    r.seen = performance.now();
  }

  drop(key) {
    const r = this.remotes.get(key);
    if (!r) return;
    this.scene.remove(r.avatar.root, r.tag);
    if (r.scooter) this.scene.remove(r.scooter.root);
    this.pets?.drop(r.petList);
    this.remotes.delete(key);
    this.onLeave?.(r);
  }

  cinema(payload) {
    this.channel?.send({ type: "broadcast", event: "cinema", payload: { ...payload, key: `${this.userId}:${this.session}` } }).catch?.(() => {});
  }

  paint(payload) {
    this.channel?.send({ type: "broadcast", event: "paint", payload }).catch?.(() => {});
  }

  hit(to, point) {
    this.channel?.send({ type: "broadcast", event: "hit", payload: { key: `${this.userId}:${this.session}`, to, x: point.x, y: point.y, z: point.z } }).catch?.(() => {});
  }

  // a small message of any kind (chat, voice, photos, the tree…)
  send(t, data = {}, to) {
    this.channel?.send({ type: "broadcast", event: "x", payload: { ...data, t, to, key: this.myKey } }).catch?.(() => {});
  }

  emote(emote, to) {
    this.channel?.send({ type: "broadcast", event: "emote", payload: { key: `${this.userId}:${this.session}`, emote, to } }).catch?.(() => {});
  }

  update(dt) {
    // send my state
    this.sendTimer -= dt * 1000;
    this.cfgTimer -= dt;
    if (this.connected && this.sendTimer <= 0) {
      this.sendTimer = SEND_MS;
      const s = this.getState();
      const payload = {
        key: `${this.userId}:${this.session}`,
        user: this.userId,
        x: +s.pos.x.toFixed(2),
        y: +s.pos.y.toFixed(2),
        z: +s.pos.z.toFixed(2),
        f: +s.facing.toFixed(2),
        s: +s.speed.toFixed(2),
        a: !s.grounded,
        vy: +s.vy.toFixed(1),
        k: Boolean(s.knock),
        st: s.seat || 0,
        cs: s.coaster || 0,
        ly: s.lie ? 1 : 0,
        lo: s.lounge || 0,
        g: Boolean(s.gun),
        v: s.ride || 0,
        pl: s.pillion || 0,
        vo: s.voice ? 1 : 0,
        po: s.pose || 0,
        sw: s.swing || 0,
        bn: s.balloon || 0,
        bt: s.balloonT ? +s.balloonT.toFixed(2) : 0,
        pc: s.chute || 0,
        pp: s.pets,
      };
      if (this.cfgTimer <= 0) {
        this.cfgTimer = 2;
        payload.cfg = s.cfg;
        payload.name = s.name;
        payload.pet = s.petCfg;
        // where the shared tripod stands (see Album.tripodSync)
        const tp = this.getTripod?.();
        if (tp) payload.tp = tp;
      }
      this.channel.send({ type: "broadcast", event: "state", payload }).catch?.(() => {});
    }
    // move the others smoothly
    const now = performance.now();
    for (const r of this.remotes.values()) {
      if (now - r.seen > 15000) {
        this.drop(r.key);
        continue;
      }
      const k = 1 - Math.exp(-dt * 10);
      if (r.pos.distanceTo(r.target) > 8) r.pos.copy(r.target);
      else r.pos.lerp(r.target, k);
      const d = Math.atan2(Math.sin(r.targetFacing - r.facing), Math.cos(r.targetFacing - r.facing));
      r.facing += d * k;
      r.avatar.root.position.copy(r.pos);
      r.avatar.root.rotation.y = r.facing;
      r.fall = (r.fall || 0) + ((r.k ? 1 : 0) - (r.fall || 0)) * k;
      r.avatar.root.rotation.z = r.fall * 1.45 + (r.scooter?.lean?.rotation.z || 0);
      if (r.scooter) {
        // they ride: the scooter under them, the avatar on the seat
        r.scooter.root.position.copy(r.pos);
        r.scooter.root.rotation.y = r.facing;
        if (r.scooter.isUnicorn) animateUnicorn(r.scooter, dt, r.speed, d * 4);
        else animateScooter(r.scooter, dt, r.speed, d * 4);
        const off = r.scooter.isUnicorn ? UNI_FRONT : -0.28;
        r.avatar.root.position.set(r.pos.x + Math.sin(r.facing) * off, r.pos.y, r.pos.z + Math.cos(r.facing) * off);
      }
      // on the back of a unicorn: theirs, or mine (where I am right now)
      if (r.pl) {
        const seat = r.pl === this.myKey ? this.mySeat?.() : null;
        const drv = seat ? null : this.remotes.get(r.pl);
        const at = seat ? seat.pos : drv?.scooter?.isUnicorn ? drv.pos : null;
        const f = seat ? seat.facing : drv?.facing;
        if (at) {
          r.pos.copy(at);
          r.facing = f;
          r.avatar.root.position.set(at.x + Math.sin(f) * UNI_BACK, at.y, at.z + Math.cos(f) * UNI_BACK);
          r.avatar.root.rotation.y = f;
          r.avatar.root.rotation.z = r.fall * 1.45 + (seat ? seat.lean || 0 : drv?.scooter?.lean?.rotation.z || 0);
        }
      }
      // on the sky coaster: in their seat on the train (it runs on the clock, so it is
      // in the same place for both of us), turning with it through the loop
      const cp = r.cs ? this.coasterSeat?.(r.cs - 1) : null;
      if (cp) {
        r.avatar.root.position.copy(cp.pos);
        r.avatar.root.quaternion.copy(cp.quat);
        r.wasCoaster = true;
      } else if (r.wasCoaster) {
        r.wasCoaster = false;
        r.avatar.root.rotation.set(0, r.facing, 0);
      }
      // in the balloon: in their seat in the basket, wherever it is in the sky
      const bp = r.bn ? this.balloonSeat?.(r.bn - 1) : null;
      if (bp) {
        r.avatar.root.position.copy(bp.pos);
        r.avatar.root.rotation.y = bp.facing;
      }
      // both in the basket: holding hands
      const mine = bp ? this.balloonMine?.() ?? -1 : -1;
      r.avatar.holdArm = mine >= 0 && mine !== r.bn - 1 ? r.bn - 1 : -1;
      // on a swing: on its seat, wherever the swing is right now
      const sp = r.sw ? this.swingSeat?.(r) : null;
      if (sp) {
        r.avatar.root.position.copy(sp.pos);
        r.avatar.root.rotation.y = sp.facing;
        r.avatar.seatH = sp.h;
      }
      // their parachute (parachute.js)
      if (r.pc && !r.chute && this.makeChute) {
        r.chute = this.makeChute(r.avatar.dims?.height || 1.6);
        r.avatar.root.add(r.chute.root);
      }
      r.chute?.update(dt, r.pc);
      const mounted = r.scooter || r.pl;
      r.avatar.update(dt, mounted ? 0 : r.speed, r.air && !mounted, r.vy);
      const up = r.scooter?.isUnicorn || r.pl ? 0.65 : r.scooter ? 0.2 : 0;
      r.tag.position.set(r.avatar.root.position.x, (cp ? cp.pos.y : r.pos.y) + r.avatar.dims.height + 0.35 + up, r.avatar.root.position.z);
      // their pets
      for (const c of r.petList || []) {
        if (!c.target) continue;
        if (c.pos.distanceTo(c.target) > 10) c.pos.copy(c.target);
        else c.pos.lerp(c.target, k);
        const pd = Math.atan2(Math.sin((c.targetFacing || 0) - c.facing), Math.cos((c.targetFacing || 0) - c.facing));
        c.facing += pd * k;
        this.pets.animate(c, dt);
      }
    }
  }

  nearest(p, max = 2.2) {
    let best = null;
    let bd = max;
    for (const r of this.remotes.values()) {
      const d = Math.hypot(r.pos.x - p.x, r.pos.z - p.z);
      if (d < bd) {
        bd = d;
        best = r;
      }
    }
    return best;
  }

  // the nearest of their pets (to pet it)
  nearestPet(p, max = 1.6) {
    let best = null;
    let bd = max;
    for (const r of this.remotes.values()) {
      for (const c of r.petList || []) {
        if (!c.placed) continue;
        const d = Math.hypot(c.pos.x - p.x, c.pos.z - p.z);
        if (d < bd) {
          bd = d;
          best = c;
        }
      }
    }
    return best;
  }

  destroy() {
    clearInterval(this.retry);
    for (const key of [...this.remotes.keys()]) this.drop(key);
    if (this.channel) this.supabase?.removeChannel(this.channel);
    this.channel = null;
  }
}
