// The sky coaster: a pastel rollercoaster on the island's edge. A chain lift
// climbs high over the fence, a huge first drop dives off the island (below the
// grass!), a vertical loop out over the sky, a climbing helix and a swoop back
// into the station.
//
// The train waits in the station until someone hops in; then it counts down and
// goes. The start is shared with your person, so you both see the same train and
// ride it together. It keeps going round while anyone stays seated.
import * as THREE from "three";
import { RoundedBoxGeometry } from "three/examples/jsm/geometries/RoundedBoxGeometry.js";
import { std, glow, nameSprite, ISLAND_R, GROW } from "./world.js";
import { bakeWhenSettled } from "./bake.js";

const deg = THREE.MathUtils.degToRad;
const ANGLE = 135; // where on the island ring the station stands
const RING_R = 42.5 + GROW;
export const COASTER_SPOT = new THREE.Vector3(Math.sin(deg(ANGLE)) * RING_R, 0, Math.cos(deg(ANGLE)) * RING_R);
// keep trees and rocks away from the station
export const COASTER_RESERVED = [{ x: COASTER_SPOT.x, z: COASTER_SPOT.z, r: 13 }];

const DWELL = 10; // the countdown before it leaves, once someone's aboard
const CAR_GAP = 2.4; // between car centres (along the track)
const CARS = 2;
const G = 9.8;
const SEAT_H = 0.42; // seat cushion above the car's floor
const RAIL_Y = 0.32; // the rails sit this far above the track's line

// ---- the track's line, in station space: +x along the platform, +z out to sea ----------
function centerline() {
  const P = [];
  const p = (x, y, z) => P.push(new THREE.Vector3(x, y, z));
  // the station (the ride starts and ends at its middle)
  p(0, 0.3, 0);
  p(4.5, 0.3, 0);
  p(9, 0.3, 0);
  // the chain lift, curling out over the fence
  p(13.5, 1.6, 0.5);
  p(17.5, 6.5, 2.4);
  p(20.3, 12.5, 5.2);
  p(21.3, 18.6, 8.6);
  p(19.8, 23.6, 11.8);
  p(16.4, 26, 13.7); // the crest
  // the first drop: off the edge of the island, right down below the grass
  p(12.6, 24, 14.6);
  p(9.6, 16.5, 14.9);
  p(6.8, 7.5, 15.1);
  p(3.8, 0.2, 15.1);
  p(0.4, -3.0, 15);
  p(-3.2, -2.6, 14.7);
  p(-6.4, 0.2, 14.4);
  p(-9.4, 2.4, 14.2);
  p(-12.5, 3, 14.1);
  // the vertical loop (lateral drift so the track misses itself)
  const C = new THREE.Vector3(-17, 10, 0);
  const RL = 7;
  const n = 16;
  for (let i = 0; i <= n; i++) {
    const f = (i / n) * Math.PI * 2;
    p(C.x - RL * Math.sin(f), C.y - RL * Math.cos(f), 14 - 3.2 * (i / n));
  }
  // round the corner and up into a climbing helix
  p(-22.5, 3.4, 10.7);
  p(-26.5, 4.6, 9.8);
  const H = { x: -30.5, z: 3, r: 6 };
  const turns = 1.5;
  const hn = 18;
  for (let i = 0; i <= hn; i++) {
    const k = i / hn;
    const a = k * turns * Math.PI * 2;
    p(H.x - H.r * Math.sin(a), 6 + k * 12.5, H.z + H.r * Math.cos(a));
  }
  // the swoop home, with the brakes at the end
  p(-24.5, 16.5, -2.8);
  p(-19.5, 9, -2.4);
  p(-15, 3, -1.3);
  p(-11.8, 0.7, -0.35);
  p(-8.5, 0.3, 0);
  p(-4.2, 0.3, 0);
  return { P, loop: [C, RL] };
}

export class Coaster {
  constructor({ scene, world, audio, ui, lowEnd, send, othersRiding }) {
    Object.assign(this, { scene, world, audio, ui, send, othersRiding });
    this.departAt = null; // when the train leaves (ms), or null while it sits idle
    this.view = 0; // 0 your seat, 1 behind the train, 2 alongside it
    this.riding = false;
    this.seatIndex = 0;
    this.waiting = false;
    this.fovBoost = 0;
    this.camUp = new THREE.Vector3(0, 1, 0);
    this.lastPhase = "dock";
    this.build(lowEnd);
  }

  // ---- building --------------------------------------------------------------------------
  build(lowEnd) {
    const out = COASTER_SPOT.clone().normalize();
    const g = (this.group = new THREE.Group());
    g.position.copy(COASTER_SPOT);
    g.rotation.y = Math.atan2(out.x, out.z); // local +z points out to sea
    this.scene.add(g);
    g.updateMatrixWorld(true);
    this.m = g.matrixWorld.clone();
    this.q = new THREE.Quaternion().setFromRotationMatrix(this.m);

    const { P, loop } = centerline();
    const rough = new THREE.CatmullRomCurve3(P, true, "centripetal");
    rough.arcLengthDivisions = 4000;
    // ease the whole line (neighbours averaged a few times) so no bend is a sharp corner;
    // the loop keeps its round shape, then it's measured out again evenly
    const raw = rough.getSpacedPoints(Math.round(rough.getLength() / 0.25));
    raw.pop();
    const [LC0, LR0] = loop;
    const keep = raw.map((q) => Math.hypot(q.x - LC0.x, q.y - LC0.y) < LR0 + 1.5 && q.z > 10 && q.z < 14.6 && q.y > LC0.y - LR0 - 0.5);
    // how far each point is from the loop (in points): smoothing fades in over ~5m so the
    // loop and the rest of the track meet without a kink
    const M = raw.length;
    const gap = raw.map((_, i) => {
      for (let k = 0; k <= 20; k++) if (keep[(i + k) % M] || keep[(i - k + M) % M]) return k;
      return 99;
    });
    let sm = raw;
    for (let pass = 0; pass < 8; pass++) {
      sm = sm.map((q, i) => {
        const fade = Math.min(1, gap[i] / 20);
        if (fade <= 0) return q;
        const acc = new THREE.Vector3();
        let w = 0;
        for (let k = -6; k <= 6; k++) {
          const wt = 7 - Math.abs(k);
          acc.addScaledVector(sm[(i + k + M) % M], wt);
          w += wt;
        }
        return q.clone().lerp(acc.divideScalar(w), fade);
      });
    }
    const curve = new THREE.CatmullRomCurve3(sm, true, "centripetal");
    curve.arcLengthDivisions = 6000;
    this.L = curve.getLength();
    const N = (this.N = Math.round(this.L / 0.2));
    const pts = curve.getSpacedPoints(N); // pts[N] === pts[0]
    pts.pop();
    this.pts = pts;
    this.ds = this.L / N;

    // tangents
    const T = pts.map((_, i) => pts[(i + 1) % N].clone().sub(pts[(i - 1 + N) % N]).normalize());
    // which samples are in the loop (there the "up" turns all the way round)
    const [LC, LR] = loop;
    const inLoop = pts.map((q) => Math.hypot(q.x - LC.x, q.y - LC.y) < LR + 1.2 && q.z > 10 && q.z < 14.6 && q.y > LC.y - LR + 0.8);
    // a little margin either side so the hand-over is smooth
    const loopIdx = inLoop.map((v, i) => v || inLoop[(i + 5) % N] || inLoop[(i - 5 + N) % N]);
    // up vectors: world-up (banked into the turns) everywhere except the loop,
    // where the frame is carried round the loop by parallel transport
    const U = new Array(N);
    const worldUp = new THREE.Vector3(0, 1, 0);
    const projUp = (t) => worldUp.clone().addScaledVector(t, -worldUp.dot(t)).normalize();
    for (let i = 0; i < N; i++) {
      if (loopIdx[i] && i > 0 && U[i - 1]) {
        const prev = U[i - 1];
        U[i] = prev.clone().addScaledVector(T[i], -prev.dot(T[i])).normalize();
      } else U[i] = projUp(T[i]);
    }
    // ease from the loop's carried frame back to world-up after the loop
    let lastLoop = -1;
    for (let i = 0; i < N; i++) if (loopIdx[i]) lastLoop = i;
    for (let k = 1; k <= 30 && lastLoop >= 0; k++) {
      const i = (lastLoop + k) % N;
      const a = U[lastLoop].clone();
      const b = projUp(T[i]);
      U[i] = a.lerp(b, k / 30).addScaledVector(T[i], -a.dot(T[i])).normalize();
    }

    // the ride's speed along the track: a gentle roll out of the station, a steady
    // chain lift, then gravity (minus a little friction) and the brakes at the end
    let crest = 0;
    for (let i = 0; i < N; i++) if (pts[i].y > pts[crest].y) crest = i;
    const yTop = pts[crest].y;
    const v = new Float32Array(N + 1);
    const LIFT = 4.6;
    for (let i = 0; i <= N; i++) {
      const s = i * this.ds;
      const y = pts[i % N].y;
      let sp;
      if (i <= crest) sp = Math.min(LIFT, Math.sqrt(0.6 + 2 * 0.9 * s));
      else sp = Math.sqrt(Math.max(9, LIFT * LIFT + 2 * G * (yTop - y) - 0.55 * (s - crest * this.ds)));
      // the brakes: slow to a stop at the station's middle
      sp = Math.min(sp, Math.sqrt(0.5 + 2 * 5.5 * (this.L - s)));
      v[i] = sp;
    }
    this.v = v;
    // time at each sample
    const t = new Float32Array(N + 1);
    for (let i = 1; i <= N; i++) t[i] = t[i - 1] + this.ds / ((v[i] + v[i - 1]) / 2);
    this.t = t;
    this.runT = t[N];
    this.crestS = crest * this.ds;
    this.loopS = [loopIdx.indexOf(true), lastLoop].map((i) => i * this.ds);

    // banking: lean into the turns by how hard you're turning at that speed
    const bank = new Float32Array(N);
    for (let i = 0; i < N; i++) {
      if (loopIdx[i]) continue;
      const a = T[(i - 6 + N) % N];
      const b = T[(i + 6) % N];
      const ha = Math.atan2(a.x, a.z);
      const hb = Math.atan2(b.x, b.z);
      const dh = Math.atan2(Math.sin(hb - ha), Math.cos(hb - ha)) / (12 * this.ds);
      const flat = 1 - Math.min(1, Math.abs(T[i].y) * 1.3);
      bank[i] = THREE.MathUtils.clamp(Math.atan((v[i] * v[i] * dh) / G), -1.05, 1.05) * flat;
    }
    // smooth the banking so it rolls in and out gently
    const bs = new Float32Array(N);
    for (let i = 0; i < N; i++) {
      let sum = 0;
      for (let k = -25; k <= 25; k++) sum += bank[(i + k + N) % N];
      bs[i] = sum / 51;
    }
    for (let i = 0; i < N; i++) if (!loopIdx[i] && Math.abs(bs[i]) > 0.001) U[i].applyAxisAngle(T[i], -bs[i]);
    // iron out any sudden twist (where the loop hands over, or the banking kicks in), which
    // would put kinks in the rails: average each up vector with its neighbours a few times
    for (let pass = 0; pass < 4; pass++) {
      const src = U.map((u) => u.clone());
      for (let i = 0; i < N; i++) {
        const acc = new THREE.Vector3();
        for (let k = -12; k <= 12; k++) acc.addScaledVector(src[(i + k + N) % N], 1 - Math.abs(k) / 13);
        U[i].copy(acc.addScaledVector(T[i], -acc.dot(T[i])).normalize());
      }
    }
    this.T = T;
    this.U = U;
    this.B = T.map((tt, i) => new THREE.Vector3().crossVectors(tt, U[i]).normalize()); // to the right

    this.buildTrack(g, lowEnd);
    this.blockTrack();
    this.buildStation(g);
    this.buildTrain(g);
    bakeWhenSettled(g);
  }

  // you can't walk onto the rails or through the train: low parts of the track over the
  // island (the station, the run in and the foot of the lift) get a wall down each side
  blockTrack() {
    const step = 5; // ~1m
    for (const side of [-1, 1]) {
      let prev = null;
      for (let i = 0; i <= this.N; i += step) {
        const k = i % this.N;
        const p = this.pts[k];
        const w = p.clone().addScaledVector(this.B[k], side * 0.75).applyMatrix4(this.m);
        const ok = p.y < 2.2 && Math.hypot(w.x, w.z) < ISLAND_R - 1.5;
        if (ok && prev) this.world.addWallSegment(prev.x, prev.z, w.x, w.z, 1.6);
        prev = ok ? w : null;
      }
    }
  }

  // sweeps a round tube along the track, offset by (right, up)
  sweep(offB, offU, r, seg, from = 0, to = this.N) {
    const pos = [];
    const nor = [];
    const idx = [];
    const ring = [];
    for (let k = 0; k < seg; k++) ring.push([Math.cos((k / seg) * Math.PI * 2), Math.sin((k / seg) * Math.PI * 2)]);
    const count = to - from + 1;
    for (let j = 0; j < count; j++) {
      const i = (from + j) % this.N;
      const c = this.pts[i].clone().addScaledVector(this.B[i], offB).addScaledVector(this.U[i], offU);
      for (const [a, b] of ring) {
        const n = this.B[i].clone().multiplyScalar(a).addScaledVector(this.U[i], b);
        pos.push(c.x + n.x * r, c.y + n.y * r, c.z + n.z * r);
        nor.push(n.x, n.y, n.z);
      }
    }
    for (let j = 0; j < count - 1; j++) {
      for (let k = 0; k < seg; k++) {
        const a = j * seg + k;
        const b = j * seg + ((k + 1) % seg);
        const c2 = (j + 1) * seg + k;
        const d = (j + 1) * seg + ((k + 1) % seg);
        idx.push(a, c2, b, b, c2, d);
      }
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute("position", new THREE.Float32BufferAttribute(pos, 3));
    geo.setAttribute("normal", new THREE.Float32BufferAttribute(nor, 3));
    geo.setIndex(idx);
    return geo;
  }

  buildTrack(g, lowEnd) {
    const N = this.N;
    const railMat = std("#ff8fb1", { flatShading: false, roughness: 0.4, metalness: 0.2 });
    const spineMat = std("#b79be8", { flatShading: false, roughness: 0.5, metalness: 0.15 });
    const seg = lowEnd ? 6 : 12;
    for (const s of [-1, 1]) {
      const m = new THREE.Mesh(this.sweep(s * 0.42, RAIL_Y, 0.065, seg), railMat);
      m.castShadow = true;
      g.add(m);
    }
    const spine = new THREE.Mesh(this.sweep(0, RAIL_Y - 0.36, 0.13, seg), spineMat);
    spine.castShadow = true;
    g.add(spine);
    // ties every ~0.7m
    const every = 4;
    const tieGeo = new THREE.BoxGeometry(1.0, 0.07, 0.12);
    const ties = new THREE.InstancedMesh(tieGeo, std("#fff7f2", { flatShading: false }), Math.ceil(N / every));
    const legGeo = new THREE.BoxGeometry(0.07, 0.36, 0.07);
    const legs = new THREE.InstancedMesh(legGeo, spineMat, Math.ceil(N / every));
    const m4 = new THREE.Matrix4();
    const basis = new THREE.Matrix4();
    let k = 0;
    for (let i = 0; i < N; i += every) {
      basis.makeBasis(this.B[i].clone().negate(), this.U[i], this.T[i]); // a proper (right-handed) rotation
      const c = this.pts[i].clone().addScaledVector(this.U[i], RAIL_Y - 0.04);
      m4.copy(basis).setPosition(c);
      ties.setMatrixAt(k, m4);
      const c2 = this.pts[i].clone().addScaledVector(this.U[i], RAIL_Y - 0.22);
      m4.copy(basis).setPosition(c2);
      legs.setMatrixAt(k, m4);
      k++;
    }
    ties.count = legs.count = k;
    ties.castShadow = true;
    g.add(ties, legs);

    // supports: candy-striped posts wherever the track is over the island near the
    // station; out over the sky it floats on little puffs of cloud
    const postMat = std("#ffffff", { map: stripeTex(), flatShading: false });
    const footMat = std("#e8d4e8");
    const cloud = std("#ffffff", { flatShading: false, roughness: 1, emissive: "#ffe6f0", emissiveIntensity: 0.15 });
    let lastPost = -99;
    let lastPuff = -99;
    for (let i = 0; i < N; i++) {
      const p = this.pts[i];
      const w = p.clone().applyMatrix4(this.m);
      const r = Math.hypot(w.x, w.z);
      const s = i * this.ds;
      const nearStation = Math.abs(p.z) < 9 && p.x > -22 && p.x < 22 && r < ISLAND_R - 3.5;
      const low = p.y - 0.1;
      if (nearStation && low > 1.2 && s - lastPost > 3.2 && Math.abs(this.U[i].y) > 0.6) {
        lastPost = s;
        const h = low;
        const post = new THREE.Mesh(new THREE.CylinderGeometry(0.11, 0.15, h, 8), postMat);
        post.position.set(p.x, h / 2, p.z);
        post.castShadow = true;
        g.add(post);
        const foot = new THREE.Mesh(new THREE.CylinderGeometry(0.3, 0.36, 0.14, 10), footMat);
        foot.position.set(p.x, 0.07, p.z);
        g.add(foot);
        this.world.addCircle(w.x, w.z, 0.25);
      } else if (!nearStation && r > 47 && p.y > -1 && s - lastPuff > 7 && !(s > this.loopS[0] - 3 && s < this.loopS[1] + 3)) {
        lastPuff = s;
        const puff = new THREE.Group();
        puff.position.copy(p).addScaledVector(this.U[i], -0.75);
        g.add(puff);
        for (let j = 0; j < 4; j++) {
          const b = new THREE.Mesh(new THREE.SphereGeometry(0.42 - j * 0.06, 10, 8), cloud);
          b.position.set((j - 1.5) * 0.4, Math.sin(j * 2) * 0.12, Math.cos(j * 3) * 0.2);
          b.scale.y = 0.7;
          puff.add(b);
        }
      }
    }
    // the lift's chain glints as it runs
    const chainFrom = Math.round(9 / this.ds);
    const chainTo = Math.round(this.crestS / this.ds);
    const chainMat = new THREE.MeshStandardMaterial({ color: "#8a8a96", metalness: 0.6, roughness: 0.4, emissive: "#ffd166", emissiveIntensity: 0.15 });
    const chain = new THREE.Mesh(this.sweep(0, RAIL_Y - 0.02, 0.04, 4, chainFrom, chainTo), chainMat);
    g.add(chain);
    this.world.animated.push((tt) => (chainMat.emissiveIntensity = 0.12 + 0.12 * (0.5 + 0.5 * Math.sin(tt * 9))));
    // rainbow hoops to fly through on the first drop and after the loop
    const RAIN = ["#ff8fb1", "#ffb36b", "#ffe07a", "#9fe0a6", "#8fd3f0", "#b79be8"];
    for (const at of [this.crestS + 16, this.loopS[1] + 12]) {
      const i = Math.round(at / this.ds) % N;
      const hoop = new THREE.Group();
      const basisH = new THREE.Matrix4().makeBasis(this.B[i].clone().negate(), this.U[i], this.T[i]);
      hoop.quaternion.setFromRotationMatrix(basisH);
      hoop.position.copy(this.pts[i]).addScaledVector(this.U[i], 0.9);
      g.add(hoop);
      RAIN.forEach((c, j) => hoop.add(new THREE.Mesh(new THREE.TorusGeometry(2.0 - j * 0.12, 0.07, 6, 30, Math.PI), new THREE.MeshBasicMaterial({ color: c, toneMapped: false }))));
      hoop.children.forEach((h) => (h.position.y = -0.6));
    }
  }

  buildStation(g) {
    const wood = std("#fff3f8");
    const pink = std("#ff8fb1", { flatShading: false });
    const lav = std("#b79be8", { flatShading: false });
    const add = (geo, mat, x, y, z, parent = g) => {
      const m = new THREE.Mesh(geo, mat);
      m.position.set(x, y, z);
      m.castShadow = m.receiveShadow = true;
      parent.add(m);
      return m;
    };
    // a pastel platform on the inner side, a stripe of paint where the train stops
    const floor = add(new THREE.BoxGeometry(17, 0.06, 2.6), std("#ffffff", { map: checkerTex() }), 0, 0.03, -2.1);
    floor.receiveShadow = true;
    add(new THREE.BoxGeometry(17, 0.065, 0.18), std("#ffd166"), 0, 0.035, -0.8);
    // canopy: posts, a curved striped roof and a row of bulbs
    for (const x of [-7.6, -2.5, 2.5, 7.6]) {
      for (const z of [-3.2, 1.3]) {
        add(new THREE.CylinderGeometry(0.1, 0.12, 3.4, 8), z < 0 ? pink : lav, x, 1.7, z);
        const w = new THREE.Vector3(x, 0, z).applyMatrix4(this.m);
        this.world.addCircle(w.x, w.z, 0.2);
      }
    }
    // a curved striped roof: a slice of a tube lying along the platform, arched upwards
    const span = Math.asin(2.35 / 2.6);
    const roof = add(new THREE.CylinderGeometry(2.6, 2.6, 16.4, 20, 1, true, Math.PI / 2 - span, span * 2), (() => {
      const tx = awningTex();
      // lit from inside too, so the underside isn't a dark cave
      return std("#ffffff", { map: tx, emissiveMap: tx, emissive: "#ffffff", emissiveIntensity: 0.35, side: THREE.DoubleSide, flatShading: false, key: "coasterRoof" });
    })(), 0, 2.43, -0.95);
    roof.rotation.z = Math.PI / 2;
    const bulbGeo = new THREE.SphereGeometry(0.07, 6, 4);
    for (let i = 0; i <= 20; i++) add(bulbGeo, i % 2 ? glow.warm : glow.pink, -8 + i * 0.8, 3.45, 1.35);
    // the sign over the entrance
    const c = document.createElement("canvas");
    c.width = 512;
    c.height = 128;
    const x = c.getContext("2d");
    const grd = x.createLinearGradient(0, 0, 512, 0);
    grd.addColorStop(0, "#ff8fb1");
    grd.addColorStop(1, "#b79be8");
    x.fillStyle = grd;
    x.beginPath();
    x.roundRect(4, 4, 504, 120, 40);
    x.fill();
    x.fillStyle = "#fffaf6";
    x.textAlign = "center";
    x.textBaseline = "middle";
    x.font = '700 60px "Fredoka", "Quicksand", sans-serif';
    x.fillText("🎢 sky coaster ♡", 256, 68);
    const tex = new THREE.CanvasTexture(c);
    tex.colorSpace = THREE.SRGBColorSpace;
    // two faces back to back, so it reads the right way round from both sides
    for (const back of [false, true]) {
      const sign = new THREE.Mesh(new THREE.PlaneGeometry(4.2, 1.05), new THREE.MeshBasicMaterial({ map: tex, toneMapped: false, transparent: true, alphaTest: 0.5 }));
      sign.position.set(0, 4.75, back ? -3.23 : -3.27);
      sign.rotation.y = back ? 0 : Math.PI;
      g.add(sign);
    }
    for (const sx of [-1.6, 1.6]) add(new THREE.CylinderGeometry(0.04, 0.04, 0.9, 6), lav, sx, 4.0, -3.25);
    // the way in: an open archway of hearts and fairy lights, flowers and balloons
    const arch = new THREE.Group();
    arch.position.set(0, 0, -3.75);
    g.add(arch);
    for (const sx of [-1.15, 1.15]) {
      add(new THREE.CylinderGeometry(0.11, 0.14, 2.6, 10), sx < 0 ? pink : lav, sx, 1.3, 0, arch);
      add(new THREE.SphereGeometry(0.17, 12, 10), std("#ffd166", { flatShading: false }), sx, 2.68, 0, arch);
      // a flower box at each foot
      add(new RoundedBoxGeometry(0.7, 0.4, 0.5, 2, 0.08), wood, sx * 1.55, 0.2, 0, arch);
      const petals = ["#ff8fb1", "#ffd166", "#b79be8", "#fff7f2", "#8fd3f0"];
      for (let i = 0; i < 7; i++) {
        add(new THREE.SphereGeometry(0.08, 8, 6), std(petals[i % petals.length], { flatShading: false }), sx * 1.55 + (i - 3) * 0.09, 0.47 + (i % 2) * 0.06, (i % 3 - 1) * 0.12, arch);
      }
      // balloons tied to the posts
      ["#ff8fb1", "#b79be8", "#8fd3f0"].forEach((c, i) => {
        const bx = sx * (1.35 + i * 0.12);
        const by = 3.0 + i * 0.25;
        add(new THREE.CylinderGeometry(0.005, 0.005, by - 1.6, 3), std("#ffffff"), bx, (by + 1.6) / 2, 0.05, arch);
        const b = add(new THREE.SphereGeometry(0.2, 12, 10), std(c, { flatShading: false, roughness: 0.25 }), bx, by, 0.05, arch);
        b.scale.y = 1.2;
        this.world.animated.push((t) => (b.position.y = by + Math.sin(t * 1.4 + i + sx) * 0.06));
      });
    }
    add(new THREE.TorusGeometry(1.15, 0.09, 8, 28, Math.PI), pink, 0, 2.6, 0, arch);
    const archBulbs = new THREE.SphereGeometry(0.05, 6, 4);
    for (let i = 0; i <= 12; i++) {
      const t = (i / 12) * Math.PI;
      add(archBulbs, i % 2 ? glow.warm : glow.pink, Math.cos(t) * 1.15, 2.6 + Math.sin(t) * 1.15, 0.1, arch);
    }
    add(new THREE.SphereGeometry(0.16, 10, 8), std("#ff6fa5", { flatShading: false }), 0, 3.85, 0, arch);
    // "welcome aboard" hanging in the arch
    {
      const c2 = document.createElement("canvas");
      c2.width = 512;
      c2.height = 128;
      const x2 = c2.getContext("2d");
      x2.fillStyle = "#fff7f2";
      x2.beginPath();
      x2.roundRect(6, 6, 500, 116, 50);
      x2.fill();
      x2.strokeStyle = "#ff8fb1";
      x2.lineWidth = 8;
      x2.stroke();
      x2.fillStyle = "#e2557f";
      x2.textAlign = "center";
      x2.textBaseline = "middle";
      x2.font = '700 54px "Fredoka", "Quicksand", sans-serif';
      x2.fillText("welcome aboard ♡", 256, 68);
      const t2 = new THREE.CanvasTexture(c2);
      t2.colorSpace = THREE.SRGBColorSpace;
      for (const back of [false, true]) {
        const m = new THREE.Mesh(new THREE.PlaneGeometry(1.7, 0.42), new THREE.MeshBasicMaterial({ map: t2, toneMapped: false, transparent: true, alphaTest: 0.5 }));
        m.position.set(0, 2.55, back ? 0.01 : -0.01);
        m.rotation.y = back ? 0 : Math.PI;
        arch.add(m);
      }
      for (const sx of [-0.6, 0.6]) add(new THREE.CylinderGeometry(0.008, 0.008, 0.5, 3), std("#ffffff"), sx, 3.0, 0, arch);
    }
    // a pink carpet leading in
    add(new THREE.BoxGeometry(1.8, 0.02, 2.4), std("#ff8fb1", { flatShading: false }), 0, 0.012, -4.85);
    for (const sx of [-1.15, 1.15]) {
      const w = new THREE.Vector3(sx, 0, -3.75).applyMatrix4(this.m);
      this.world.addCircle(w.x, w.z, 0.18);
    }
    const stand = new THREE.Group();
    stand.position.set(-9.6, 0, -2.6);
    g.add(stand);
    add(new RoundedBoxGeometry(1.2, 1.1, 0.9, 2, 0.08), pink, 0, 0.55, 0, stand);
    add(new THREE.BoxGeometry(1.35, 0.08, 1.05), wood, 0, 1.14, 0, stand);
    add(new THREE.ConeGeometry(0.8, 0.5, 4), lav, 0, 2.3, 0, stand).rotation.y = Math.PI / 4;
    for (const sx of [-0.5, 0.5]) add(new THREE.CylinderGeometry(0.04, 0.04, 1.0, 5), wood, sx, 1.65, 0.38, stand);
    const ws = new THREE.Vector3(-9.6, 0, -2.6).applyMatrix4(this.m);
    this.world.addCircle(ws.x, ws.z, 0.7);
    // a floating name over the station
    const label = nameSprite();
    label.userData.draw("🎢 sky coaster");
    label.position.set(0, 6.3, -1);
    label.scale.set(5.6, 0.7, 1);
    g.add(label);
    this.world.animated.push((tt) => (label.position.y = 6.3 + Math.sin(tt * 1.5) * 0.12));

    // hop in from the platform
    const spot = new THREE.Vector3(0, 0, -1.7).applyMatrix4(this.m);
    this.world.interactables.push({ id: "coaster", label: "ride the sky coaster 🎢", icon: "🎢", pos: spot, radius: 4.2, action: { type: "coaster" } });
    this.exitSpot = new THREE.Vector3(1.2, 0, -2.1).applyMatrix4(this.m);
    this.stationSpot = spot;
  }

  buildTrain(g) {
    this.cars = [];
    const bodies = [std("#ff8fb1", { flatShading: false, roughness: 0.35, metalness: 0.1 }), std("#b79be8", { flatShading: false, roughness: 0.35, metalness: 0.1 })];
    const seatMat = std("#fff3f8", { flatShading: false });
    const black = std("#2b2633", { flatShading: false });
    const gold = std("#ffd166", { flatShading: false, metalness: 0.5, roughness: 0.3 });
    for (let c = 0; c < CARS; c++) {
      const car = new THREE.Group();
      car.userData.live = true; // it sits still while idle, but it's the train
      g.add(car);
      const add = (geo, mat, x, y, z) => {
        const m = new THREE.Mesh(geo, mat);
        m.position.set(x, y, z);
        m.castShadow = true;
        car.add(m);
        return m;
      };
      const body = bodies[c % 2];
      // tub, rounded nose, seats with high backs, lap bars, wheels
      add(new RoundedBoxGeometry(1.3, 0.5, 2.0, 3, 0.18), body, 0, 0.3, 0);
      for (const sx of [-1, 1]) add(new RoundedBoxGeometry(0.16, 0.35, 1.9, 2, 0.06), body, sx * 0.6, 0.65, 0);
      add(new RoundedBoxGeometry(1.3, 0.55, 0.18, 2, 0.08), body, 0, 0.58, 0.92); // low, so you can see over it
      for (const sx of [-0.3, 0.3]) {
        add(new RoundedBoxGeometry(0.5, 0.12, 0.6, 2, 0.05), seatMat, sx, SEAT_H + 0.13, -0.15);
        add(new RoundedBoxGeometry(0.5, 0.75, 0.14, 2, 0.06), seatMat, sx, SEAT_H + 0.48, -0.5);
        // a padded lap bar across your lap, on a stem from the front of the car
        add(new THREE.CylinderGeometry(0.05, 0.05, 0.42, 10), gold, sx, SEAT_H + 0.4, 0.2).rotation.z = Math.PI / 2;
        add(new THREE.CylinderGeometry(0.025, 0.025, 0.7, 6), gold, sx, SEAT_H + 0.4, 0.55).rotation.x = Math.PI / 2;
      }
      for (const sx of [-0.45, 0.45]) for (const sz of [-0.7, 0.7]) add(new THREE.CylinderGeometry(0.12, 0.12, 0.1, 10), black, sx, 0.02, sz).rotation.z = Math.PI / 2;
      if (c === 0) {
        // the front car has cat ears, little eyes and heart headlights
        for (const sx of [-0.38, 0.38]) {
          const ear = add(new THREE.ConeGeometry(0.13, 0.22, 4), body, sx * 1.15, 0.96, 0.92);
          ear.rotation.y = Math.PI / 4;
          add(new THREE.SphereGeometry(0.06, 8, 6), black, sx * 0.7, 0.66, 1.02);
          add(new THREE.SphereGeometry(0.08, 8, 6), glow.warm, sx * 1.25, 0.35, 1.0);
        }
        add(new THREE.SphereGeometry(0.05, 6, 4), std("#ff6fa5"), 0, 0.56, 1.03);
      }
      this.cars.push(car);
    }
  }

  // ---- where the train is ----------------------------------------------------------------
  // seconds into a ride: below DWELL it's in the station (counting down, or idle at 0),
  // DWELL and up it's out on the track
  phase(nowMs = Date.now()) {
    if (this.departAt === null) return 0;
    const el = (nowMs - this.departAt) / 1000;
    if (el < 0) return Math.max(0, DWELL + el);
    if (el < this.runT) return DWELL + el;
    return 0;
  }
  running(nowMs = Date.now()) {
    return this.departAt !== null && nowMs >= this.departAt && nowMs < this.departAt + this.runT * 1000;
  }
  // start the countdown (and tell your person)
  schedule(inMs = DWELL * 1000) {
    this.departAt = Date.now() + inMs;
    this.send?.({ in: inMs });
  }
  // your person started (or restarted) the countdown
  onRemote(p) {
    if (this.running()) return;
    if (p?.cancel) {
      if (!this.riding) this.departAt = null;
      return;
    }
    if (typeof p?.in !== "number") return;
    this.departAt = Date.now() + Math.max(0, Math.min(DWELL * 1000, p.in));
  }
  // distance along the track of the front car
  trainS(ph) {
    if (ph < DWELL) return 0;
    const tt = ph - DWELL;
    // binary search the time table
    let lo = 0;
    let hi = this.N;
    while (hi - lo > 1) {
      const mid = (lo + hi) >> 1;
      if (this.t[mid] <= tt) lo = mid;
      else hi = mid;
    }
    const f = (tt - this.t[lo]) / Math.max(1e-6, this.t[hi] - this.t[lo]);
    return Math.min(this.L, (lo + f) * this.ds);
  }
  docked() {
    return this.phase() < DWELL - 0.4;
  }
  // a frame on the track at distance s (station space)
  frameAt(s, out) {
    const N = this.N;
    const u = ((s / this.ds) % N + N) % N;
    const i = Math.floor(u);
    const j = (i + 1) % N;
    const f = u - i;
    out.p.lerpVectors(this.pts[i], this.pts[j], f);
    out.t.lerpVectors(this.T[i], this.T[j], f).normalize();
    out.u.lerpVectors(this.U[i], this.U[j], f);
    out.u.addScaledVector(out.t, -out.u.dot(out.t)).normalize();
    out.b.crossVectors(out.u, out.t).normalize(); // to the left, as +x is for the avatar
    out.v = this.v[i] + (this.v[i + 1] - this.v[i]) * f;
    return out;
  }

  // a seat's world pose: 0/1 front car (left/right), 2/3 back car
  seatPose(index, into = {}) {
    const car = this.cars[Math.min(this.cars.length - 1, index >> 1)];
    const sx = index % 2 ? 0.3 : -0.3;
    into.pos = (into.pos || new THREE.Vector3()).set(sx, 0.08, -0.1).applyMatrix4(car.matrixWorld);
    into.quat = (into.quat || new THREE.Quaternion()).setFromRotationMatrix(car.matrixWorld);
    return into;
  }

  // ---- riding ----------------------------------------------------------------------------
  // the seat your person is in (so you take the other one)
  board(otherSeat) {
    this.seatIndex = otherSeat === 0 ? 1 : 0;
    this.riding = true;
    this.waiting = false;
    this.didCrest = false;
    this.didLoop = false;
    // an idle train: start the countdown
    if (this.departAt === null || Date.now() >= this.departAt + this.runT * 1000) this.schedule();
    this.audio?.sfx?.("pop");
  }
  leave() {
    this.riding = false;
    this.fovBoost = 0;
    // nobody left aboard before it set off: call the ride off and let it sit idle
    if (!this.running() && !this.othersRiding?.()) {
      this.departAt = null;
      this.send?.({ cancel: true });
    }
  }

  update(dt) {
    this.dt = dt;
    // back from a ride: go again if anyone stayed seated, otherwise sit idle
    if (this.departAt !== null && Date.now() >= this.departAt + this.runT * 1000) {
      if (this.riding) this.schedule();
      else if (!this.othersRiding?.()) this.departAt = null;
    }
    const ph = this.phase();
    const s = this.trainS(ph);
    this.s = s;
    const f = (this._f ||= { p: new THREE.Vector3(), t: new THREE.Vector3(), u: new THREE.Vector3(), b: new THREE.Vector3(), v: 0 });
    const basis = new THREE.Matrix4();
    for (let c = 0; c < this.cars.length; c++) {
      this.frameAt(s - c * CAR_GAP, f);
      basis.makeBasis(f.b, f.u, f.t);
      const car = this.cars[c];
      car.quaternion.setFromRotationMatrix(basis);
      car.position.copy(f.p).addScaledVector(f.u, RAIL_Y + 0.12);
      car.updateMatrixWorld(true);
    }
    this.frameAt(s, f);
    this.speed = ph < DWELL ? 0 : f.v;
    const docked = ph < DWELL;
    const state = docked ? "dock" : "out";
    if (this.riding) {
      this.fovBoost += (Math.min(18, Math.max(0, this.speed - 6) * 1.1) - this.fovBoost) * Math.min(1, dt * 3);
      // little moments
      if (!docked) {
        if (!this.didCrest && s > this.crestS - 1.5) {
          this.didCrest = true;
          this.ui?.toast?.("wheeeeeee!! 🎢💨");
          this.audio?.sfx?.("whee");
        }
        if (!this.didLoop && s > this.loopS[0]) {
          this.didLoop = true;
          this.audio?.sfx?.("whoosh");
        }
        // the chain lift clacks on the way up
        if (s > 8 && s < this.crestS) {
          this.clack = (this.clack || 0) - dt;
          if (this.clack <= 0) {
            this.clack = 0.22;
            this.audio?.sfx?.("clack");
          }
        }
      }
      if (this.lastPhase === "dock" && state === "out") this.ui?.toast?.("hold on tight!! ♡");
      if (this.lastPhase === "out" && state === "dock") {
        this.didCrest = false;
        this.didLoop = false;
        this.ui?.toast?.("again?! ✦ stay seated to go round again, or hop off ♡");
        this.audio?.sfx?.("ding");
      }
    } else this.fovBoost *= Math.exp(-dt * 4);
    this.lastPhase = state;
  }

  // first person from your seat, turning with the car (upside down in the loop!).
  // lookYaw / lookPitch let you glance around; the view is eased so it never shakes
  placeCamera(camera, lookYaw = 0, lookPitch = 0) {
    if (!this.riding) {
      this.camQ = null;
      return false;
    }
    if (this.view !== 0) return this.placeOutsideCamera(camera, lookYaw, lookPitch);
    const car = this.cars[this.seatIndex >> 1];
    const sx = this.seatIndex % 2 ? 0.3 : -0.3;
    // climbing steeply you would only see sky: glance down the track instead, like a rider does
    const climb = Math.asin(THREE.MathUtils.clamp(new THREE.Vector3(0, 0, 1).transformDirection(car.matrixWorld).y, -1, 1));
    if (climb > 0.3) lookPitch -= (climb - 0.3) * 0.65;
    const eye = new THREE.Vector3(sx, 1.55, -0.1).applyMatrix4(car.matrixWorld);
    const dir = new THREE.Vector3(0, -0.2, 1).applyAxisAngle(new THREE.Vector3(1, 0, 0), -lookPitch).applyAxisAngle(new THREE.Vector3(0, 1, 0), lookYaw);
    const look = new THREE.Vector3(sx, 1.55, -0.1).add(dir.multiplyScalar(6)).applyMatrix4(car.matrixWorld);
    const carQ = car.getWorldQuaternion(new THREE.Quaternion());
    this.camUp.set(0, 1, 0).applyQuaternion(carQ);
    camera.position.copy(eye);
    camera.up.copy(this.camUp);
    camera.lookAt(look);
    camera.up.set(0, 1, 0);
    const want = camera.quaternion.clone();
    if (!this.camQ) this.camQ = want.clone();
    else this.camQ.slerp(want, 1 - Math.exp(-(this.dt || 0.016) * 14));
    camera.quaternion.copy(this.camQ);
    return true;
  }

  // switch between your seat, behind the train and alongside it
  static VIEWS = ["your seat 👀", "behind the train 🎢", "watching from the side 🎥"];
  cycleView() {
    this.view = (this.view + 1) % Coaster.VIEWS.length;
    this.camQ = null;
    this.sidePos = null;
    this.sideAim = null;
    return Coaster.VIEWS[this.view];
  }
  // the camera stays put by the train; dragging turns the view on the spot, like turning
  // your head (lookYaw left/right, lookPitch up/down)
  placeOutsideCamera(camera, lookYaw = 0, lookPitch = 0) {
    const dt = this.dt || 0.016;
    const X = new THREE.Vector3(1, 0, 0);
    const Y = new THREE.Vector3(0, 1, 0);
    if (this.view === 1) {
      // behind and above the train, rolling with it
      const back = this.cars[this.cars.length - 1];
      const q = back.getWorldQuaternion(new THREE.Quaternion());
      const eye = new THREE.Vector3(0, 2.4, -4.2).applyMatrix4(back.matrixWorld);
      const dir = new THREE.Vector3(0, -0.28, 1).normalize().applyAxisAngle(X, -lookPitch).applyAxisAngle(Y, lookYaw).applyQuaternion(q);
      this.camUp.set(0, 1, 0).applyQuaternion(q);
      camera.position.copy(eye);
      camera.up.copy(this.camUp);
      camera.lookAt(eye.clone().add(dir));
      camera.up.set(0, 1, 0);
      const want = camera.quaternion.clone();
      if (!this.camQ) this.camQ = want.clone();
      else this.camQ.slerp(want, 1 - Math.exp(-dt * 10));
      camera.quaternion.copy(this.camQ);
      return true;
    }
    // alongside: off to the side of the train, upright, gliding to keep up
    const car = this.cars[0];
    const at = new THREE.Vector3().setFromMatrixPosition(car.matrixWorld);
    const fwd = new THREE.Vector3(0, 0, 1).transformDirection(car.matrixWorld);
    fwd.y = 0;
    if (fwd.lengthSq() < 1e-4) fwd.set(0, 0, 1);
    fwd.normalize();
    const side = new THREE.Vector3(fwd.z, 0, -fwd.x);
    const want = at.clone().addScaledVector(side, 7.5).addScaledVector(fwd, -2.5).add(new THREE.Vector3(0, 3, 0));
    if (!this.sidePos) this.sidePos = want.clone();
    else this.sidePos.lerp(want, 1 - Math.exp(-dt * 16));
    // smooth where it's aimed too, then turn that by the drag
    const aim = at.clone().sub(this.sidePos).normalize();
    if (!this.sideAim) this.sideAim = aim.clone();
    else this.sideAim.lerp(aim, 1 - Math.exp(-dt * 14)).normalize();
    const right = new THREE.Vector3().crossVectors(this.sideAim, Y).normalize();
    const dir = this.sideAim.clone().applyAxisAngle(right, lookPitch).applyAxisAngle(Y, lookYaw);
    camera.position.copy(this.sidePos);
    camera.up.set(0, 1, 0);
    camera.lookAt(this.sidePos.clone().add(dir));
    // ease the turn like the other views, so dragging glides instead of stepping
    const wantQ = camera.quaternion.clone();
    if (!this.camQ) this.camQ = wantQ.clone();
    else this.camQ.slerp(wantQ, 1 - Math.exp(-dt * 10));
    camera.quaternion.copy(this.camQ);
    return true;
  }

  // seconds till the train leaves (null while it's idle, waiting for someone)
  departsIn() {
    if (this.departAt === null || this.running()) return null;
    const ms = this.departAt - Date.now();
    return ms > 0 ? Math.ceil(ms / 1000) : null;
  }

  // how long till it's back in the station
  untilBack() {
    return this.running() ? Math.ceil(this.runT - (Date.now() - this.departAt) / 1000) : 0;
  }
}

// ---- textures --------------------------------------------------------------------------------
function stripeTex() {
  const c = document.createElement("canvas");
  c.width = 32;
  c.height = 64;
  const x = c.getContext("2d");
  x.fillStyle = "#fff7f2";
  x.fillRect(0, 0, 32, 64);
  x.fillStyle = "#ff8fb1";
  for (let i = -2; i < 6; i++) {
    x.beginPath();
    x.moveTo(0, i * 16);
    x.lineTo(32, i * 16 + 12);
    x.lineTo(32, i * 16 + 20);
    x.lineTo(0, i * 16 + 8);
    x.fill();
  }
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.repeat.set(1, 6);
  return t;
}
function checkerTex() {
  const c = document.createElement("canvas");
  c.width = c.height = 64;
  const x = c.getContext("2d");
  for (let i = 0; i < 4; i++) for (let j = 0; j < 4; j++) {
    x.fillStyle = (i + j) % 2 ? "#ffe3ee" : "#f1e6ff";
    x.fillRect(i * 16, j * 16, 16, 16);
  }
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.repeat.set(10, 1.5);
  return t;
}
function awningTex() {
  const c = document.createElement("canvas");
  c.width = 128;
  c.height = 16;
  const x = c.getContext("2d");
  for (let i = 0; i < 8; i++) {
    x.fillStyle = i % 2 ? "#fff7f2" : "#ff8fb1";
    x.fillRect(i * 16, 0, 16, 16);
  }
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.repeat.set(1, 6);
  return t;
}
