// The sky race: a big floating road all the way round the island, out through
// the TOTO&DODO gate and over a long bridge. Big hills, two ramps that jump a
// gap in the road, rolling candy bumpers to dodge, rainbow arches and boost
// pads. Ride your scooters round it and race each other for three laps.
import * as THREE from "three";
import { std, glow, makeScreen, ISLAND_R, GROW, EDGE_K } from "./world.js";

const TAU = Math.PI * 2;
const N = 360; // road pieces all the way round
const W = 4.5; // half the road's width
const BW = 2.2; // half the bridge's width
const LAPS = 3;
const START = 0.1; // the start line, just past the bridge
const BEST_KEY = "tdd3d.race";
const GATE_GAP = 0.027 * EDGE_K; // the opening in the island fence at the gate

// the road's middle (distance from the island's middle) and height, by angle
const Rc = (a) => 70 + GROW + 5 * Math.sin(2 * a + 0.5) + 2.5 * Math.sin(3 * a + 1.2);
const wrap = (a) => Math.atan2(Math.sin(a), Math.cos(a));
// rolling hills: flat by the bridge, a big climb to the far side and back
const Hbase = (a) => 5.5 * (1 - Math.cos(a)) + 1.3 * Math.sin(4 * a) * (1 - Math.cos(a));
// two ramps that throw you over a gap in the road
const JUMPS = [1.95, 4.3].map((g0) => ({ r0: g0 - 0.1, g0, g1: g0 + 6.2 / Rc(g0) }));
const ramp = (a) => {
  const u = ((a % TAU) + TAU) % TAU;
  for (const j of JUMPS) if (u > j.r0 && u < j.g0) return 1.5 * ((u - j.r0) / (j.g0 - j.r0)) ** 1.4;
  return 0;
};
const inGap = (a) => {
  const u = ((a % TAU) + TAU) % TAU;
  return JUMPS.some((j) => u >= j.g0 && u <= j.g1);
};
const Hc = (a) => Hbase(a) + ramp(a);
const BRIDGE_END = Rc(0) - W + 0.4;
// [angle, across]: a run-up pad before each ramp, and more round the loop
const BOOSTS = [[0.7, 0], [1.15, -2], [1.78, 0], [2.45, 2], [3.2, -2], [3.75, 2], [4.13, 0], [5.05, 2], [5.7, -2]];
const BUMPERS = [[2.75, 0.9], [3.45, 1.3], [5.35, 1.1]]; // [angle, speed]
const ARCHES = [0.85, 2.25, 3.6, 5.5];
const RAINBOW = ["#ff8fb1", "#ffb36b", "#ffe07a", "#9fe0a6", "#8fd3f0", "#b79be8"];

const at = (a, off = 0, y = Hc(a)) => {
  const r = Rc(a) + off;
  return new THREE.Vector3(Math.sin(a) * r, y, Math.cos(a) * r);
};
// the way the road runs at angle a
const heading = (a) => {
  const d = 0.002;
  const p = at(a + d, 0, 0).sub(at(a - d, 0, 0));
  return Math.atan2(p.x, p.z);
};
const fmt = (s) => `${Math.floor(s / 60)}:${(s % 60).toFixed(1).padStart(4, "0")}`;

function loadBest() {
  try {
    return +localStorage.getItem(BEST_KEY) || 0;
  } catch {
    return 0;
  }
}

// a strip along the road from off0 to off1 (across), lifted by y, with v running along it
function strip(off0, off1, y, vScale, skip) {
  const pos = [];
  const uv = [];
  const idx = [];
  let len = 0;
  let prev = null;
  for (let i = 0; i <= N; i++) {
    const a = (i / N) * TAU;
    const mid = at(a, (off0 + off1) / 2);
    if (prev) len += mid.distanceTo(prev);
    prev = mid;
    const p0 = at(a, off0, Hc(a) + y);
    const p1 = at(a, off1, Hc(a) + y);
    pos.push(p0.x, p0.y, p0.z, p1.x, p1.y, p1.z);
    uv.push(0, len / vScale, 1, len / vScale);
    if (i < N && !skip?.(a)) {
      const k = i * 2;
      idx.push(k, k + 1, k + 2, k + 1, k + 3, k + 2);
    }
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute("position", new THREE.Float32BufferAttribute(pos, 3));
  g.setAttribute("uv", new THREE.Float32BufferAttribute(uv, 2));
  g.setIndex(idx);
  g.computeVertexNormals();
  return g;
}
// an upright band along one edge of the road, from y0 to y1
// openings end exactly where they should, the same on both sides
const BRIDGE_OPEN = (BW + 0.2) / (Rc(0) - W);
const CUTS = [BRIDGE_OPEN, TAU - BRIDGE_OPEN, ...JUMPS.flatMap((j) => [j.g0, j.g1])];
function wall(off, y0, y1, skip) {
  const pos = [];
  const idx = [];
  const angles = [...Array.from({ length: N + 1 }, (_, i) => (i / N) * TAU), ...CUTS].sort((x, y) => x - y);
  angles.forEach((a, i) => {
    const p0 = at(a, off, Hc(a) + y0);
    const p1 = at(a, off, Hc(a) + y1);
    pos.push(p0.x, p0.y, p0.z, p1.x, p1.y, p1.z);
    const next = angles[i + 1];
    if (next !== undefined && next - a > 1e-6 && !skip?.((a + next) / 2)) {
      const k = i * 2;
      idx.push(k, k + 1, k + 2, k + 1, k + 3, k + 2);
    }
  });
  const g = new THREE.BufferGeometry();
  g.setAttribute("position", new THREE.Float32BufferAttribute(pos, 3));
  g.setIndex(idx);
  g.computeVertexNormals();
  return g;
}
function canvasTex(w, h, paint, repeat = true) {
  const c = document.createElement("canvas");
  c.width = w;
  c.height = h;
  paint(c.getContext("2d"), w, h);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  if (repeat) t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.anisotropy = 4;
  return t;
}

export class Race {
  // hooks: grid(pos, facing) puts you on your scooter at the start, canJoin(),
  // riding(), myKey(), name(key)
  constructor({ scene, world, audio, ui, send, hooks, lowEnd }) {
    this.scene = scene;
    this.world = world;
    this.audio = audio;
    this.ui = ui;
    this.send = send;
    this.hooks = hooks;
    this.state = "idle"; // idle | count | run | done
    this.best = loadBest();
    this.boost = 0;
    this.rival = null;
    this.build(lowEnd);
  }

  // ---- the road ------------------------------------------------------------
  build(lowEnd) {
    const g = new THREE.Group();
    this.group = g;
    this.scene.add(g);
    const road = canvasTex(128, 128, (x, w, h) => {
      x.fillStyle = "#6f6688";
      x.fillRect(0, 0, w, h);
      // a little speckle, a dashed middle line and soft lane lines
      for (let i = 0; i < 260; i++) {
        x.fillStyle = Math.random() < 0.5 ? "rgba(255,255,255,0.05)" : "rgba(0,0,0,0.06)";
        x.fillRect(Math.random() * w, Math.random() * h, 2, 2);
      }
      x.fillStyle = "#fff7f2";
      x.fillRect(w / 2 - 3, 0, 6, h * 0.55);
      x.fillStyle = "rgba(255,247,242,0.35)";
      x.fillRect(w * 0.25 - 1, 0, 2, h);
      x.fillRect(w * 0.75 - 1, 0, 2, h);
    });
    const roadMat = new THREE.MeshStandardMaterial({ map: road, roughness: 0.85, flatShading: false });
    const top = new THREE.Mesh(strip(-W, W, 0, 9, inGap), roadMat);
    top.receiveShadow = true;
    g.add(top);
    // candy curbs along both edges
    const curb = canvasTex(8, 64, (x, w, h) => {
      x.fillStyle = "#ff8fb1";
      x.fillRect(0, 0, w, h / 2);
      x.fillStyle = "#fff7f2";
      x.fillRect(0, h / 2, w, h / 2);
    });
    const curbMat = new THREE.MeshStandardMaterial({ map: curb, roughness: 0.7 });
    g.add(new THREE.Mesh(strip(-W, -W + 0.55, 0.03, 2.4, inGap), curbMat), new THREE.Mesh(strip(W - 0.55, W, 0.03, 2.4, inGap), curbMat));
    // the road's sides and underneath, so it looks solid from the island
    const side = std("#c9b6e8", { side: THREE.DoubleSide, unique: true });
    const innerGap = (a) => Math.abs(wrap(a)) < BRIDGE_OPEN || inGap(a);
    g.add(new THREE.Mesh(wall(-W, -0.8, 0, inGap), side), new THREE.Mesh(wall(W, -0.8, 0, inGap), side));
    const under = new THREE.Mesh(strip(W, -W, -0.8, 9, inGap), std("#b49fd8"));
    g.add(under);
    // low candy walls along both edges, standing on the road (open where the bridge comes in)
    const railMat = std("#ffb3cf", { side: THREE.DoubleSide, unique: true });
    g.add(new THREE.Mesh(wall(-W, 0, 0.6, innerGap), railMat), new THREE.Mesh(wall(W, 0, 0.6, inGap), railMat));
    // posts with little lights on top
    const every = lowEnd ? 8 : 5;
    const count = Math.ceil(N / every) * 2;
    const postGeo = new THREE.CylinderGeometry(0.08, 0.08, 0.7, 6);
    postGeo.translate(0, 0.35, 0);
    const posts = new THREE.InstancedMesh(postGeo, std("#fff7f2"), count);
    const bulbs = new THREE.InstancedMesh(new THREE.IcosahedronGeometry(0.13, 0), glow.pink, count);
    const m = new THREE.Matrix4();
    let n = 0;
    for (let i = 0; i < N; i += every) {
      const a = (i / N) * TAU;
      for (const s of [-1, 1]) {
        if ((s < 0 && innerGap(a)) || inGap(a)) continue;
        const p = at(a, s * W);
        m.makeTranslation(p.x, p.y, p.z);
        posts.setMatrixAt(n, m);
        m.makeTranslation(p.x, p.y + 0.78, p.z);
        bulbs.setMatrixAt(n++, m);
      }
    }
    posts.count = bulbs.count = n;
    g.add(posts, bulbs);
    // clouds holding it up
    const cloudMat = new THREE.MeshStandardMaterial({ color: "#ffffff", emissive: "#ffffff", emissiveIntensity: 0.25, flatShading: true, roughness: 1 });
    const puffs = lowEnd ? 3 : 5;
    const cloudN = Math.ceil(N / 12) * puffs;
    const clouds = new THREE.InstancedMesh(new THREE.IcosahedronGeometry(1, 1), cloudMat, cloudN);
    const q = new THREE.Quaternion();
    const sc = new THREE.Vector3();
    let cn = 0;
    for (let i = 0; i < N; i += 12) {
      const a = (i / N) * TAU + 0.02;
      for (let k = 0; k < puffs && cn < cloudN; k++) {
        const p = at(a + (k - puffs / 2) * 0.012, (k % 2 ? 1 : -1) * (1 + k * 0.7), Hc(a) - 2.5 - (k % 3) * 0.5);
        const s = 1.4 + ((i * 7 + k * 13) % 10) * 0.12;
        m.compose(p, q, sc.set(s * 1.3, s * 0.6, s));
        clouds.setMatrixAt(cn++, m);
      }
    }
    clouds.count = cn;
    g.add(clouds);

    // the bridge out of the gate
    const wood = std("#f0dcc8");
    const E0 = ISLAND_R - 0.4; // where the bridge leaves the island
    const len = BRIDGE_END - E0;
    const deck = new THREE.Mesh(new THREE.BoxGeometry(BW * 2, 0.35, len), std("#e8d4c8"));
    deck.position.set(0, -0.155, E0 + len / 2);
    deck.receiveShadow = true;
    g.add(deck);
    const plank = new THREE.BoxGeometry(BW * 2 - 0.1, 0.04, 0.9);
    for (let z = E0 + 0.2; z < BRIDGE_END - 0.4; z += 1.1) {
      const pl = new THREE.Mesh(plank, wood);
      pl.position.set(0, 0.02, z + 0.45);
      g.add(pl);
    }
    for (const s of [-1, 1]) {
      const rail = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.12, len), railMat);
      rail.position.set(s * BW, 0.75, E0 + len / 2);
      g.add(rail);
      for (let z = E0 + 0.2; z < BRIDGE_END; z += 2.4) {
        const p = new THREE.Mesh(postGeo, std("#fff7f2"));
        p.position.set(s * BW, 0, z);
        p.scale.y = 1.15;
        g.add(p);
      }
    }
    for (let z = ISLAND_R + 2; z < BRIDGE_END; z += 7) {
      const c = new THREE.Mesh(new THREE.IcosahedronGeometry(1.6, 1), cloudMat);
      c.position.set(0, -1.6, z);
      c.scale.set(1.6, 0.7, 1.2);
      g.add(c);
    }

    // the start line, with an arch and a board over it
    const checker = canvasTex(64, 16, (x, w, h) => {
      for (let i = 0; i < 16; i++) for (let j = 0; j < 4; j++) {
        x.fillStyle = (i + j) % 2 ? "#2b2633" : "#fff7f2";
        x.fillRect(i * 4, j * 4, 4, 4);
      }
    }, false);
    const line = new THREE.Mesh(new THREE.PlaneGeometry(W * 2, 1.2), new THREE.MeshStandardMaterial({ map: checker, roughness: 0.8 }));
    const lp = at(START);
    line.position.set(lp.x, lp.y + 0.04, lp.z);
    line.rotation.order = "YXZ";
    line.rotation.set(-Math.PI / 2, heading(START), 0);
    g.add(line);
    const arch = new THREE.Group();
    arch.position.copy(lp);
    arch.rotation.y = heading(START);
    g.add(arch);
    for (const s of [-1, 1]) {
      const pillar = new THREE.Mesh(new THREE.CylinderGeometry(0.22, 0.26, 4.6, 8), std(s < 0 ? "#ff8fb1" : "#8fd3f0"));
      pillar.position.set(s * (W + 0.5), 2.3, 0);
      arch.add(pillar);
      const ball = new THREE.Mesh(new THREE.IcosahedronGeometry(0.4, 1), glow.pink);
      ball.position.set(s * (W + 0.5), 4.8, 0);
      arch.add(ball);
    }
    const beam = new THREE.Mesh(new THREE.BoxGeometry(W * 2 + 1.4, 0.3, 0.3), std("#fff7f2"));
    beam.position.y = 4.5;
    arch.add(beam);
    // the board faces you as you come round
    this.board = makeScreen(5.2, 1.5, { border: "#ff8fb1", placeholder: "⋆ sky race ⋆" });
    this.board.mesh.position.set(0, 3.55, -0.2);
    this.board.mesh.rotation.y = Math.PI;
    arch.add(this.board.mesh);
    const back = new THREE.Mesh(this.board.mesh.geometry, this.board.mesh.material);
    back.position.set(0, 3.55, 0.2);
    arch.add(back);
    this.drawBoard();

    // boost pads
    const chev = canvasTex(64, 64, (x, w, h) => {
      x.fillStyle = "#ffd166";
      x.fillRect(0, 0, w, h);
      x.strokeStyle = "#ff6fa5";
      x.lineWidth = 9;
      for (const y of [16, 38]) {
        x.beginPath();
        x.moveTo(10, y + 16);
        x.lineTo(32, y);
        x.lineTo(54, y + 16);
        x.stroke();
      }
    }, false);
    const padMat = new THREE.MeshStandardMaterial({ map: chev, emissive: "#ffb000", emissiveIntensity: 0.35, roughness: 0.6 });
    this.pads = BOOSTS.map(([a, off]) => {
      const p = at(a, off);
      const pad = new THREE.Mesh(new THREE.PlaneGeometry(2.6, 3.2), padMat);
      pad.position.set(p.x, p.y + 0.05, p.z);
      pad.rotation.order = "YXZ";
      pad.rotation.set(-Math.PI / 2, heading(a) + Math.PI, 0);
      g.add(pad);
      return { a, off };
    });

    // rolling candy bumpers that sweep across the road
    const swirl = canvasTex(64, 32, (x, w, h) => {
      for (let i = 0; i < 8; i++) {
        x.fillStyle = i % 2 ? "#fff7f2" : "#ff6fa5";
        x.fillRect((i * w) / 8, 0, w / 8 + 1, h);
      }
    }, false);
    const bumperMat = new THREE.MeshStandardMaterial({ map: swirl, roughness: 0.4, emissive: "#ff6fa5", emissiveIntensity: 0.15 });
    this.bumpers = BUMPERS.map(([a, speed], i) => {
      const mesh = new THREE.Mesh(new THREE.SphereGeometry(1.05, 16, 12), bumperMat);
      g.add(mesh);
      return { a, speed, phase: i * 1.7, mesh, off: 0, pos: new THREE.Vector3() };
    });
    // rainbow arches over the road
    ARCHES.forEach((a) => {
      const arch = new THREE.Group();
      arch.position.copy(at(a));
      arch.rotation.y = heading(a);
      RAINBOW.forEach((col, k) => {
        const band = new THREE.Mesh(new THREE.TorusGeometry(W + 1.6 - k * 0.32, 0.17, 5, 28, Math.PI), new THREE.MeshStandardMaterial({ color: col, emissive: col, emissiveIntensity: 0.25, flatShading: true }));
        arch.add(band);
      });
      for (const s of [-1, 1]) {
        const c = new THREE.Mesh(new THREE.IcosahedronGeometry(1.1, 1), cloudMat);
        c.position.set(s * (W + 0.8), 0.2, 0);
        c.scale.set(1.3, 0.8, 1.1);
        arch.add(c);
      }
      g.add(arch);
    });
    // the ramps: striped, with a sign before each
    const rampTex = chev.clone();
    rampTex.wrapS = rampTex.wrapT = THREE.RepeatWrapping;
    rampTex.needsUpdate = true;
    const rampMat = new THREE.MeshStandardMaterial({ map: rampTex, emissive: "#ffb000", emissiveIntensity: 0.2, roughness: 0.6, side: THREE.DoubleSide });
    for (const j of JUMPS) {
      // chevrons painted on the ramp itself, following its curve
      const offRamp = (x) => { const u = ((x % TAU) + TAU) % TAU; return u < j.r0 || u > j.g0 - 0.002; };
      g.add(new THREE.Mesh(strip(-W + 0.7, W - 0.7, 0.04, 3.2, offRamp), rampMat));
      const sign = makeScreen(2.6, 1.0, { border: "#ffd166", placeholder: "jump!" });
      sign.draw({ title: "⚡ JUMP ⚡", foot: "go fast!" });
      const sp = at(j.r0 - 0.12, W + 0.9, Hc(j.r0 - 0.12) + 2.2);
      sign.mesh.position.copy(sp);
      sign.mesh.rotation.y = heading(j.r0 - 0.12) + Math.PI;
      g.add(sign.mesh);
    }

    // ways to start: at the gate, and at the start line
    const gateSpot = new THREE.Vector3(0, 0, ISLAND_R - 4.4);
    this.world.interactables.push({ id: "race-gate", label: "start a sky race 🏁", icon: "🏁", pos: gateSpot, radius: 2.2, action: { type: "race" } });
    const startSpot = at(START - 6 / Rc(START), -W + 1.2);
    this.world.interactables.push({ id: "race-start", label: "start a sky race 🏁", icon: "🏁", pos: startSpot, radius: 3.2, action: { type: "race" } });
  }

  drawBoard(extra) {
    const pairs = [["🏆 best", this.best ? fmt(this.best) : "–"]];
    if (extra) pairs.unshift(extra);
    this.board.draw({ title: "⋆ sky race ⋆", pairs, foot: `${LAPS} laps · ride round, hit the boosts ⋆` });
  }

  // ---- the ground and the rails ---------------------------------------------
  // how high the road (or the bridge) is under x, z; null when there's none
  groundAt(x, z) {
    if (z > ISLAND_R - 1 && z < BRIDGE_END + 0.5 && Math.abs(x) <= BW + 0.05) return 0;
    const r = Math.hypot(x, z);
    if (r < ISLAND_R + 5) return null;
    const a = Math.atan2(x, z);
    if (inGap(a)) return null;
    return Math.abs(r - Rc(a)) <= W + 0.1 ? Hc(a) : null;
  }
  // the gap in the island's fence where the bridge starts
  inGate(x, z) {
    return z > 0 && Math.abs(Math.atan2(x, z)) < GATE_GAP;
  }
  // on the bridge or the road
  isHere(p) {
    return (p.z > ISLAND_R - 0.6 && p.z < BRIDGE_END && Math.abs(p.x) < BW + 0.5 && p.y > -2) || this.onRoad(p);
  }
  onRoad(p) {
    const r = Math.hypot(p.x, p.z);
    if (r < ISLAND_R + 5) return false;
    const a = Math.atan2(p.x, p.z);
    return Math.abs(r - Rc(a)) <= W + 0.5 && Math.abs(p.y - Hc(a)) < 2;
  }
  // keeps you between the rails, on the bridge and on the road
  collide(p, y, rad) {
    if (y < -2 || y > 12) return;
    // the bridge's sides, until it opens onto the road
    if (p.z > ISLAND_R - 0.3 && p.z < BRIDGE_END - W * 0.2 && Math.abs(p.x) < BW + 1.2 && y < 2) {
      const max = BW - rad * 0.8;
      if (Math.abs(p.x) > max) p.x = Math.sign(p.x) * max;
      return;
    }
    const r = Math.hypot(p.x, p.z);
    if (r < ISLAND_R + 5) return;
    const a = Math.atan2(p.x, p.z);
    if (Math.abs(y - Hc(a)) > 1.6) return;
    // the candy bumpers
    for (const b of this.bumpers || []) {
      const dx = p.x - b.pos.x;
      const dz = p.z - b.pos.z;
      const d = Math.hypot(dx, dz);
      const min = 1.05 + rad;
      if (d < min && d > 1e-4 && Math.abs(y - (b.pos.y - 1.05)) < 1.5) {
        p.x = b.pos.x + (dx / d) * min;
        p.z = b.pos.z + (dz / d) * min;
        if (performance.now() - (this.bonkAt || 0) > 500) {
          this.bonkAt = performance.now();
          this.audio.sfx("bounce");
          this.bonked = 0.5;
        }
      }
    }
    if (inGap(a)) return;
    const c = Rc(a);
    const off = r - c;
    if (Math.abs(off) > W + 1.2) return;
    const max = W - rad * 0.8;
    let want = null;
    if (off > max) want = c + max;
    else if (off < -max && !(Math.abs(p.x) < BW && p.z > 0)) want = c - max;
    if (want !== null) {
      p.x *= want / r;
      p.z *= want / r;
    }
  }

  // where to put you back after falling off
  respawnPoint(player) {
    if (this.state === "idle" && !this.lastOnRoad) return null;
    let a = this.lastA ?? START;
    // fell short of a jump: back before its ramp
    const u = ((a % TAU) + TAU) % TAU;
    for (const j of JUMPS) if (u > j.r0 - 0.15 && u <= j.g1 + 0.02) a = j.r0 - 0.35;
    const p = at(a, 0);
    p.y += 0.05;
    return { pos: p, facing: heading(a) };
  }

  // ---- racing ----------------------------------------------------------------
  get frozen() {
    return this.state === "count";
  }
  get racing() {
    return this.state === "count" || this.state === "run";
  }

  begin() {
    if (this.racing) {
      this.ui.toast("you're already racing 🏁");
      return;
    }
    this.start(0);
    this.send?.({ go: 1 });
  }

  // lane 0 on the inside, 1 on the outside
  start(lane) {
    this.state = "count";
    this.count = 3.9; // the fade, then 3, 2, 1
    this.lastBeep = 4;
    this.lap = 0;
    this.time = 0;
    this.rival = null;
    this.rivalDone = null;
    const a = START - 9 / Rc(START);
    const p = at(a, lane ? 2 : -2);
    p.y += 0.02;
    this.lastA = a;
    this.prog = wrap(a - START);
    this.hooks.grid(p, heading(a));
    this.drawBoard(["🏁", "get ready…"]);
  }

  onRemote(p, who) {
    if (p.go) {
      if (this.racing || !this.hooks.canJoin()) {
        this.ui.toast(`${who} started a sky race 🏁 come to the gate to join the next one`);
        return;
      }
      this.ui.toast(`${who} started a sky race! 🏁`);
      this.start(1);
      this.rival = { name: who, lap: 0 };
    } else if (p.lap !== undefined) {
      this.rival = { name: who, lap: p.lap };
    } else if (p.done) {
      this.rivalDone = { name: who, time: p.done };
      this.rival = { name: who, lap: LAPS };
      this.ui.toast(this.state === "run" ? `${who} finished first! ${fmt(p.done)} 🏆 keep going!` : `${who} finished in ${fmt(p.done)} 🏁`);
    } else if (p.quit) {
      if (this.rival) this.ui.toast(`${who} left the race`);
      this.rival = null;
    }
  }

  quit(why) {
    if (!this.racing) return;
    this.state = "idle";
    this.send?.({ quit: 1 });
    this.ui.toast(why || "race cancelled");
    this.drawBoard();
  }

  // every frame: boosts, laps and the clock. Returns the line for the top chip.
  update(dt, player) {
    // the bumpers roll across the road (on a shared clock, so you both see them in the same place)
    const clock = Date.now() / 1000;
    for (const b of this.bumpers) {
      b.off = Math.sin(clock * b.speed + b.phase) * (W - 1.3);
      b.pos.copy(at(b.a, b.off, Hc(b.a) + 1.05));
      b.mesh.position.copy(b.pos);
      b.mesh.rotation.set(0, heading(b.a), -b.off * 0.95);
    }
    this.bonked = Math.max(0, (this.bonked || 0) - dt);
    const on = this.onRoad(player.pos);
    const a = Math.atan2(player.pos.x, player.pos.z);
    if (on) {
      this.lastOnRoad = true;
      // boost pads
      const off = Math.hypot(player.pos.x, player.pos.z) - Rc(a);
      for (const pad of this.pads) {
        if (Math.abs(wrap(a - pad.a)) * Rc(a) < 1.7 && Math.abs(off - pad.off) < 1.5 && this.boost < 0.6) {
          this.boost = 1.3;
          this.audio.sfx("bounce");
          this.ui.buzz?.();
        }
      }
    } else if (Math.hypot(player.pos.x, player.pos.z) < ISLAND_R - 1) this.lastOnRoad = false;
    this.boost = Math.max(0, this.boost - dt);

    if (this.state === "count") {
      this.count -= dt;
      const n = Math.ceil(this.count);
      if (n < this.lastBeep && n <= 3 && n > 0) {
        this.lastBeep = n;
        this.ui.toast(`${n}…`);
        this.audio.sfx("tick");
      }
      if (this.count <= 0) {
        this.state = "run";
        this.time = 0;
        this.ui.toast("GO! 🏁");
        this.audio.sfx("start");
        this.audio.sfx("horn");
      }
      return `🏁 ${Math.max(1, Math.ceil(Math.min(3, this.count)))}…`;
    }
    if (this.state === "run") {
      this.time += dt;
      // how far round you've come (going backwards counts back)
      if (on || Math.hypot(player.pos.x, player.pos.z) > ISLAND_R + 5) {
        this.prog += wrap(a - this.lastA);
        this.lastA = a;
      }
      // back on the island: that's the end of it
      if (Math.hypot(player.pos.x, player.pos.z) < ISLAND_R - 3 && player.pos.y < 3) {
        this.quit("you left the race 🏁");
        return "";
      }
      if (this.prog >= (this.lap + 1) * TAU) {
        this.lap++;
        if (this.lap >= LAPS) this.finish();
        else {
          this.ui.toast(`lap ${this.lap + 1}/${LAPS} · ${fmt(this.time)}`);
          this.audio.sfx("check");
          this.send?.({ lap: this.lap });
        }
      }
      if (this.state !== "run") return this.chip;
      const rival = this.rival ? ` · ${this.rival.name}: ${this.rival.lap >= LAPS ? "done 🏆" : `lap ${Math.min(LAPS, this.rival.lap + 1)}`}` : "";
      return `🏁 lap ${this.lap + 1}/${LAPS} · ${fmt(this.time)}${this.boost > 0 ? " ⚡" : ""}${rival}`;
    }
    if (on) this.lastA = a;
    if (this.state === "done") {
      this.doneT -= dt;
      if (this.doneT <= 0) this.state = "idle";
      return this.chip;
    }
    return this.boost > 0 ? "⚡ boost!" : "";
  }

  finish() {
    const t = this.time;
    this.state = "done";
    this.doneT = 6;
    const first = !this.rivalDone;
    const newBest = !this.best || t < this.best;
    if (newBest) {
      this.best = t;
      try {
        localStorage.setItem(BEST_KEY, String(+t.toFixed(2)));
      } catch {}
    }
    this.send?.({ done: +t.toFixed(2) });
    const place = this.rival || this.rivalDone ? (first ? "you won! 🥇" : "2nd place 🥈") : "finished!";
    this.ui.toast(`${place} ${fmt(t)}${newBest ? " ⋆ new best!" : ""}`);
    this.ui.confetti();
    this.audio.sfx("win");
    this.chip = `🏁 ${fmt(t)}${newBest ? " ⋆ new best" : ""}`;
    this.drawBoard(["🏁 last", fmt(t)]);
  }
}
