// The island's weather, picked in the 🎨 menu: clear, rain, snow and autumn (a blizzard
// instead of autumn in the christmas theme). Each one
// nudges the theme's colours (a grey drizzly sky, a snowy white ground and frosted trees,
// golden grass and orange leaves) and fills the air round the camera with what's falling:
// raindrops, snowflakes or tumbling leaves. The falling things live in a box that follows
// the camera, so they're everywhere you go without there being millions of them.
import * as THREE from "three";

const KEY = "tdd3d.weather";
export const WEATHERS = ["clear", "rain", "snow", "autumn", "blizzard"];
export const WEATHER_INFO = {
  clear: { icon: "☀️", label: "clear", toast: "☀️ clear skies" },
  rain: { icon: "🌧️", label: "rain", toast: "🌧️ a soft rainy day" },
  snow: { icon: "❄️", label: "snow", toast: "❄️ snow day! ☃" },
  autumn: { icon: "🍂", label: "autumn", toast: "🍂 autumn leaves" },
  blizzard: { icon: "🌨️", label: "blizzard", toast: "🌨️ a whirling blizzard! stay cosy ☃" },
};

export function loadWeather() {
  try {
    const v = localStorage.getItem(KEY);
    if (WEATHERS.includes(v)) return v;
  } catch {}
  return "clear";
}
export function saveWeather(v) {
  try {
    localStorage.setItem(KEY, v);
  } catch {}
}

const col = new THREE.Color();
const mix = (a, b, t) => `#${col.set(a).lerp(new THREE.Color(b), t).getHexString()}`;
const dim = (a, k) => `#${col.set(a).multiplyScalar(k).getHexString()}`;

// the theme's palette, dressed for the weather (night themes stay dark: the colours are
// mixed in, not swapped)
export function weatherVariant(p, w) {
  if (w === "clear" || !WEATHER_INFO[w]) return p;
  if (w === "blizzard") {
    // the snow's look, with the sky closed in white and the far side lost in the whirl
    const q = weatherVariant(p, "snow");
    const n = p.night || 0;
    q.sky = q.sky.map((c) => mix(c, n > 0.5 ? "#4a5470" : "#dfe6ef", 0.5));
    q.fog = mix(q.fog, n > 0.5 ? "#5a6480" : "#eef2f7", 0.6);
    q.fogNear = q.fogNear * 0.35;
    q.fogFar = q.fogFar * 0.5;
    q.sunI = q.sunI * 0.55;
    q.cloud = mix(q.cloud, "#e8edf4", 0.5);
    return q;
  }
  const n = p.night || 0;
  const q = { ...p, petals: false };
  if (w === "rain") {
    q.sky = p.sky.map((c, i) => mix(c, n > 0.5 ? "#1c2230" : ["#7d8a9c", "#a3adbb", "#c4cbd4"][i], 0.6));
    q.sunDisc = mix(p.sunDisc, "#c8d0dc", 0.6);
    q.sunI = p.sunI * 0.45;
    q.hemiI = p.hemiI * 0.92;
    q.hemiSky = mix(p.hemiSky, "#b8c4d4", 0.4);
    q.fog = mix(p.fog, n > 0.5 ? "#1e2634" : "#aab4c2", 0.6);
    q.fogNear = p.fogNear * 0.5;
    q.fogFar = p.fogFar * 0.65;
    q.grassTint = mix(p.grassTint, "#c4dcc0", 0.35);
    q.cloud = mix(p.cloud, n > 0.5 ? "#3a4252" : "#c8ced8", 0.7);
    q.canopy = dim(p.canopy, 0.88);
  } else if (w === "snow") {
    const k = 1 - n * 0.45; // (snow at night is a moonlit blue, not glowing white)
    q.ground = [dim("#f4f8ff", k), dim("#dfe7f2", k)];
    q.grassTint = "#ffffff";
    q.tuft = mix(p.tuft, "#eef4fb", 0.75);
    q.canopy = mix(p.canopy, "#f6faff", 0.6);
    q.pine = mix(p.pine, "#e6eef6", 0.35);
    q.sky = p.sky.map((c, i) => mix(c, n > 0.5 ? "#1a2238" : ["#a9c3e0", "#d3e2f2", "#f2f6fb"][i], 0.55));
    q.sunDisc = mix(p.sunDisc, "#f4f8ff", 0.5);
    q.sun = mix(p.sun, "#e8f0ff", 0.5);
    q.hemiSky = mix(p.hemiSky, "#e6efff", 0.5);
    q.hemiGround = mix(p.hemiGround, "#c8d4e4", 0.6);
    q.fog = mix(p.fog, n > 0.5 ? "#283048" : "#e4ecf6", 0.6);
    q.fogNear = p.fogNear * 0.6;
    q.fogFar = p.fogFar * 0.75;
    q.cloud = mix(p.cloud, "#ffffff", 0.6);
  } else if (w === "autumn") {
    const k = 1 - n * 0.4;
    q.ground = [dim("#ecd88c", k), dim("#d9b866", k)];
    q.grassTint = "#ffffff";
    q.tuft = mix(p.tuft, "#e0a040", 0.75);
    q.canopy = mix(p.canopy, "#f27428", 0.88);
    q.pine = mix(p.pine, "#6f7a4a", 0.35);
    q.sky = p.sky.map((c, i) => mix(c, n > 0.5 ? "#2a1a14" : ["#f2b880", "#ffd9a8", "#fff0d8"][i], 0.4));
    q.sun = mix(p.sun, "#ffcf98", 0.5);
    q.sunDisc = mix(p.sunDisc, "#ffd8a0", 0.5);
    q.hemiSky = mix(p.hemiSky, "#ffe2bc", 0.35);
    q.fog = mix(p.fog, n > 0.5 ? "#2a1c18" : "#f6dcc0", 0.45);
  }
  return q;
}

// a soft round flake
function flakeTex() {
  const c = document.createElement("canvas");
  c.width = c.height = 32;
  const x = c.getContext("2d");
  const g = x.createRadialGradient(16, 16, 0, 16, 16, 16);
  g.addColorStop(0, "rgba(255,255,255,1)");
  g.addColorStop(0.5, "rgba(255,255,255,0.8)");
  g.addColorStop(1, "rgba(255,255,255,0)");
  x.fillStyle = g;
  x.fillRect(0, 0, 32, 32);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

const BOX = { x: 44, y: 26, z: 44 }; // the box of air round the camera
const wrap = (v, c, size) => v - Math.floor((v - c) / size + 0.5) * size;

export class WeatherFx {
  constructor(scene, lowEnd = false) {
    this.scene = scene;
    this.kind = "clear";
    this.lowEnd = lowEnd;
    this.group = new THREE.Group();
    this.group.frustumCulled = false;
    scene.add(this.group);
    this.t = 0;
    this.flash = 0; // lightning, 0..1 (island.js brightens the sky light with it)
    this.onThunder = null;
  }

  set(kind) {
    if (kind === this.kind) return;
    this.kind = kind;
    for (const c of [...this.group.children]) {
      this.group.remove(c);
      c.geometry?.dispose();
    }
    this.rain = this.snow = this.leaves = this.splash = null;
    this.flash = 0;
    const R = Math.random;
    const scale = this.lowEnd ? 0.5 : 1;
    if (kind === "rain") {
      // short pale streaks, falling fast and a little slanted
      const n = Math.round(3400 * scale);
      const pos = new Float32Array(n * 6);
      const drops = new Float32Array(n * 3);
      for (let i = 0; i < n; i++) {
        drops[i * 3] = (R() - 0.5) * BOX.x;
        drops[i * 3 + 1] = R() * BOX.y;
        drops[i * 3 + 2] = (R() - 0.5) * BOX.z;
      }
      const g = new THREE.BufferGeometry();
      g.setAttribute("position", new THREE.BufferAttribute(pos, 3).setUsage(THREE.DynamicDrawUsage));
      const m = new THREE.LineSegments(g, new THREE.LineBasicMaterial({ color: "#d8e6f4", transparent: true, opacity: 0.75, depthWrite: false, fog: true }));
      m.frustumCulled = false;
      this.group.add(m);
      this.rain = { m, drops, n, speed: 24, slant: 3 };
      // little rings where the drops land round you
      const sn = Math.round(140 * scale);
      const sm = new THREE.InstancedMesh(new THREE.RingGeometry(0.05, 0.08, 14).rotateX(-Math.PI / 2), new THREE.MeshBasicMaterial({ color: "#e8f2fc", transparent: true, opacity: 0.45, depthWrite: false }), sn);
      sm.frustumCulled = false;
      this.group.add(sm);
      this.splash = { m: sm, S: Array.from({ length: sn }, () => ({ x: 0, z: 0, age: R() * 0.5, life: 0.35 + R() * 0.25 })), d: new THREE.Object3D() };
    } else if (kind === "snow" || kind === "flurry" || kind === "blizzard") {
      // (a flurry: christmas's own light snowfall on a clear day; a blizzard: thick, fast,
      // blown sideways by the wind)
      const n = Math.round((kind === "flurry" ? 1100 : kind === "blizzard" ? 5600 : 3200) * scale);
      const pos = new Float32Array(n * 3);
      const seed = new Float32Array(n);
      for (let i = 0; i < n; i++) {
        pos[i * 3] = (R() - 0.5) * BOX.x;
        pos[i * 3 + 1] = R() * BOX.y;
        pos[i * 3 + 2] = (R() - 0.5) * BOX.z;
        seed[i] = R() * 100;
      }
      const g = new THREE.BufferGeometry();
      g.setAttribute("position", new THREE.BufferAttribute(new Float32Array(n * 3), 3).setUsage(THREE.DynamicDrawUsage));
      const m = new THREE.Points(g, new THREE.PointsMaterial({ map: flakeTex(), size: 0.32, sizeAttenuation: true, transparent: true, opacity: 0.95, depthWrite: false, color: "#ffffff" }));
      m.frustumCulled = false;
      this.group.add(m);
      this.snow = { m, base: pos, seed, n, speed: kind === "blizzard" ? 3.4 : 1, wind: kind === "blizzard" ? 7 : 0 };
    } else if (kind === "autumn") {
      // little leaves in reds, oranges and gold, tumbling down
      const n = Math.round(520 * scale);
      const leaf = new THREE.Shape();
      leaf.moveTo(0, -0.1);
      leaf.quadraticCurveTo(0.08, 0, 0, 0.1);
      leaf.quadraticCurveTo(-0.08, 0, 0, -0.1);
      const geo = new THREE.ShapeGeometry(leaf, 3);
      const m = new THREE.InstancedMesh(geo, new THREE.MeshStandardMaterial({ side: THREE.DoubleSide, roughness: 0.8 }), n);
      m.frustumCulled = false;
      m.castShadow = false;
      const cols = ["#e8642c", "#f08a3c", "#d94a2a", "#f2b440", "#c8762e", "#b8402a"].map((c) => new THREE.Color(c));
      const L = [];
      for (let i = 0; i < n; i++) {
        m.setColorAt(i, cols[i % cols.length]);
        L.push({ x: (R() - 0.5) * BOX.x, y: R() * BOX.y, z: (R() - 0.5) * BOX.z, s: R() * 100, sp: 0.8 + R() * 0.8, sc: 1.8 + R() * 1.6 });
      }
      m.instanceColor.needsUpdate = true;
      this.group.add(m);
      this.leaves = { m, L, n, d: new THREE.Object3D() };
    }
  }

  // once a frame: what's falling, round the camera
  update(dt, cam) {
    if (this.kind === "clear") return;
    dt = Math.min(dt, 0.05);
    this.t += dt;
    const t = this.t;
    const cx = cam.x, cz = cam.z, y0 = cam.y - BOX.y * 0.55;
    if (this.rain) {
      const { drops, n, speed, slant } = this.rain;
      const pos = this.rain.m.geometry.attributes.position.array;
      for (let i = 0; i < n; i++) {
        let y = drops[i * 3 + 1] - speed * dt;
        if (y < 0) y += BOX.y;
        drops[i * 3 + 1] = y;
        drops[i * 3] += slant * dt * 0.15;
        const x = wrap(drops[i * 3], cx, BOX.x), z = wrap(drops[i * 3 + 2], cz, BOX.z);
        const o = i * 6;
        pos[o] = x;
        pos[o + 1] = y0 + y;
        pos[o + 2] = z;
        pos[o + 3] = x - slant * 0.03;
        pos[o + 4] = y0 + y + 0.85;
        pos[o + 5] = z;
      }
      this.rain.m.geometry.attributes.position.needsUpdate = true;
      // splashes: each ring grows and starts again somewhere new near you
      const { m: sm, S, d } = this.splash;
      for (let i = 0; i < S.length; i++) {
        const p = S[i];
        p.age += dt;
        if (p.age > p.life) {
          p.age = 0;
          const a = Math.random() * Math.PI * 2, r = 1.5 + Math.sqrt(Math.random()) * 13;
          p.x = cx + Math.sin(a) * r;
          p.z = cz + Math.cos(a) * r;
        }
        d.position.set(p.x, 0.03, p.z);
        d.scale.setScalar(0.4 + (p.age / p.life) * 2.2);
        d.updateMatrix();
        sm.setMatrixAt(i, d.matrix);
      }
      sm.instanceMatrix.needsUpdate = true;
      // now and then a flash of lightning, then the thunder
      this.flash = Math.max(0, this.flash - dt * 3.5);
      if (Math.random() < dt / 14) {
        this.flash = 1;
        this.flashAgain = 0.12 + Math.random() * 0.1;
        this.onThunder?.();
      }
      if (this.flashAgain > 0 && (this.flashAgain -= dt) <= 0) this.flash = Math.max(this.flash, 0.7);
    }
    if (this.snow) {
      const { base, seed, n, speed, wind } = this.snow;
      const pos = this.snow.m.geometry.attributes.position.array;
      for (let i = 0; i < n; i++) {
        let y = base[i * 3 + 1] - (0.9 + (seed[i] % 1) * 0.6) * speed * dt;
        if (y < 0) y += BOX.y;
        base[i * 3 + 1] = y;
        if (wind) base[i * 3] += wind * (0.7 + (seed[i] % 1) * 0.6) * dt;
        const s = seed[i];
        pos[i * 3] = wrap(base[i * 3] + Math.sin(t * 0.7 + s) * 0.6, cx, BOX.x);
        pos[i * 3 + 1] = y0 + y;
        pos[i * 3 + 2] = wrap(base[i * 3 + 2] + Math.cos(t * 0.5 + s * 1.3) * 0.6, cz, BOX.z);
        // (not right in front of the lens, where a flake would be a big blur)
        const dx = pos[i * 3] - cx, dy = pos[i * 3 + 1] - cam.y, dz = pos[i * 3 + 2] - cz;
        if (dx * dx + dy * dy + dz * dz < 12) pos[i * 3 + 1] = -999;
      }
      this.snow.m.geometry.attributes.position.needsUpdate = true;
    }
    if (this.leaves) {
      const { m, L, n, d } = this.leaves;
      for (let i = 0; i < n; i++) {
        const l = L[i];
        l.y -= l.sp * dt;
        if (l.y < 0) l.y += BOX.y;
        d.position.set(wrap(l.x + Math.sin(t * 0.8 + l.s) * 1.4, cx, BOX.x), y0 + l.y, wrap(l.z + Math.cos(t * 0.6 + l.s) * 1.4, cz, BOX.z));
        d.rotation.set(t * 1.7 + l.s, t * 1.1 + l.s * 2, Math.sin(t * 2 + l.s) * 0.8);
        // (shrinking away right by the lens, so one never fills the screen)
        const near = d.position.distanceTo(cam);
        d.scale.setScalar(l.sc * Math.min(1, Math.max(0, (near - 1.5) / 2)));
        d.updateMatrix();
        m.setMatrixAt(i, d.matrix);
      }
      m.instanceMatrix.needsUpdate = true;
    }
  }
}
