// The outsides of the buildings. Each room is dressed as the thing it keeps:
// the diary wears an open book for a roof, the gift room is a wrapped present,
// pin it is a camera, smol note is a pencil stub, and so on. Everything here
// sits outside the walls and over the old roof, so the insides stay as they are.
import * as THREE from "three";

let K; // the builder's kit from world.js: add, box, cyl, std, glow, heartGeo, shadeHex
const WHITE = "#fffaf6";
const PINK = "#f07aa0";
const T = 0.12; // how thick the outer skin is

const white = () => K.std(WHITE, { key: "ext" });
const gold = () => K.std("#ffd27a", { metalness: 0.45, roughness: 0.35, emissive: "#ffb648", emissiveIntensity: 0.3, key: "extgold" });
const roofMat = (color, extra = {}) => K.std(color, { side: THREE.DoubleSide, key: "extroof", ...extra });

function tex(w, h, paint, rx = 1, ry = 1) {
  const c = document.createElement("canvas");
  c.width = w;
  c.height = h;
  paint(c.getContext("2d"), w, h);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.repeat.set(rx, ry);
  t.anisotropy = 4;
  return t;
}
const stripes = (a, b, rx) =>
  tex(64, 8, (g) => {
    g.fillStyle = a;
    g.fillRect(0, 0, 32, 8);
    g.fillStyle = b;
    g.fillRect(32, 0, 32, 8);
  }, rx, 1);
const dots = (bg, dot, rx, ry) =>
  tex(128, 128, (g) => {
    g.fillStyle = bg;
    g.fillRect(0, 0, 128, 128);
    g.fillStyle = dot;
    for (const [x, y] of [[32, 32], [96, 96]]) {
      g.beginPath();
      g.arc(x, y, 13, 0, 7);
      g.fill();
    }
  }, rx, ry);

let starGeoCache;
function starGeo() {
  if (starGeoCache) return starGeoCache;
  const s = new THREE.Shape();
  for (let i = 0; i < 10; i++) {
    const r = i % 2 ? 0.42 : 1;
    const a = (i / 10) * Math.PI * 2 + Math.PI / 2;
    s[i ? "lineTo" : "moveTo"](Math.cos(a) * r, Math.sin(a) * r);
  }
  starGeoCache = new THREE.ExtrudeGeometry(s, { depth: 0.3, bevelEnabled: false });
  starGeoCache.center();
  return starGeoCache;
}

// ---- pieces every building shares ------------------------------------------
// a band of boxes round the outside of the walls (leaving the doorway open)
function belt(room, c, y, h, mat, out = 0, t = T) {
  room.walls.forEach((w, i) => {
    const L = c.lens[i] + 0.3;
    const z = c.thick / 2 + t / 2 + out;
    if (i === 0 && y - h / 2 < c.doorH) {
      const side = (L - c.doorW) / 2;
      for (const s of [-1, 1]) K.add(w.group, K.box(side, h, t), mat, (s * (c.doorW + side)) / 2, y, z);
    } else K.add(w.group, K.box(L, h, t), mat, 0, y, z);
  });
}
// a new coat over the walls, a darker skirt at the bottom and round pillars at the corners
function skin(room, c, color, skirt, map) {
  const Hs = c.H + 0.25;
  // a soft glow of their own colour, so pastel walls stay pastel in the shade
  const m = map ? K.std("#ffffff", { map, emissive: "#fff0f5", emissiveIntensity: 0.12, key: "extskin" }) : K.std(color, { emissive: color, emissiveIntensity: 0.16, key: "extskin" });
  belt(room, c, c.doorH / 2, c.doorH, m);
  belt(room, c, c.doorH + (Hs - c.doorH) / 2, Hs - c.doorH, m);
  if (skirt) belt(room, c, 0.35, 0.7, K.std(skirt, { key: "ext" }), 0.05);
  return Hs;
}
function pillars(c, mat, r = 0.3) {
  const Hs = c.H + 0.25;
  const pts = c.hall ? [[-1, -1], [1, -1], [-1, 1], [1, 1]].map(([x, z]) => new THREE.Vector3(x * (c.W / 2 + 0.1), 0, z * (c.D / 2 + 0.1))) : Array.from({ length: c.sides }, (_, i) => c.vert(i).multiplyScalar(1 + 0.12 / c.R));
  for (const v of pts) {
    K.add(c.group, K.cyl(r, r, Hs, 10), mat, v.x, Hs / 2, v.z);
    K.add(c.group, new THREE.SphereGeometry(r * 1.15, 8, 6), mat, v.x, Hs, v.z);
  }
}
// white posts round the door, with a glowing fanlight over it
function doorway(room, c, fan = true) {
  const wg = room.walls[0].group;
  const z = c.thick / 2 + T;
  const m = white();
  // posts reach into the opening and back to the wall, so no face sits on the skin's edges
  for (const s of [-1, 1]) K.add(wg, K.box(0.26, c.doorH, T + 0.09), m, s * (c.doorW / 2 + 0.09), c.doorH / 2, c.thick / 2 + 0.01 + (T + 0.09) / 2);
  K.add(wg, K.box(c.doorW + 0.46, 0.18, T + 0.11), m, 0, c.doorH + 0.05, c.thick / 2 + 0.01 + (T + 0.11) / 2);
  if (!fan) return;
  const r = c.doorW / 2 + 0.2;
  const pane = K.add(wg, new THREE.CircleGeometry(r - 0.1, 16, 0, Math.PI), K.glow.warm, 0, c.doorH + 0.14, z + 0.03, { cast: false });
  const arch = K.add(wg, new THREE.TorusGeometry(r - 0.05, 0.1, 6, 16, Math.PI), m, 0, c.doorH + 0.14, z + 0.03);
  pane.scale.y = arch.scale.y = 0.72;
  for (const a of [-0.5, 0, 0.5]) K.add(wg, K.box(0.05, (r - 0.1) * 0.72, 0.04), m, Math.sin(a) * r * 0.45, c.doorH + 0.14 + Math.cos(a) * r * 0.33, z + 0.05, { rz: -a, cast: false });
}
function flowerBox(wg, x, y, z, w) {
  K.add(wg, K.box(w, 0.22, 0.28), white(), x, y, z + 0.14);
  const leaf = K.std("#8fd3a0", { key: "ext" });
  const cols = ["#ff8fb1", "#ffd166", "#c7b0f5", "#fff3f8"];
  const n = Math.round(w / 0.24);
  for (let i = 0; i < n; i++) {
    const fx = x - w / 2 + 0.12 + i * ((w - 0.24) / Math.max(1, n - 1));
    K.add(wg, new THREE.IcosahedronGeometry(0.09, 0), leaf, fx, y + 0.15, z + 0.14, { cast: false });
    K.add(wg, new THREE.IcosahedronGeometry(0.075, 0), K.std(cols[i % 4], { key: "ext" }), fx + 0.03, y + 0.26, z + 0.19, { cast: false });
  }
}
// a round window with a cross in it, and flowers under it
function roundWindow(wg, c, x, y, r, flowers = true) {
  const z = c.thick / 2 + T;
  const m = white();
  K.add(wg, new THREE.CircleGeometry(r, 18), K.glow.warm, x, y, z + 0.02, { cast: false });
  K.add(wg, new THREE.TorusGeometry(r, 0.09, 6, 18), m, x, y, z + 0.02);
  K.add(wg, K.box(0.07, r * 2, 0.05), m, x, y, z + 0.03, { cast: false });
  K.add(wg, K.box(r * 2, 0.07, 0.05), m, x, y, z + 0.03, { cast: false });
  if (flowers) flowerBox(wg, x, y - r - 0.26, z, r * 2 + 0.3);
}
// the same windows the old walls had, on the new coat
function windows(room, c, y = c.H * 0.55, r = 0.55) {
  room.walls.forEach((w, i) => {
    if (i === 0) return;
    if (c.sides === 6 ? i % 2 === 1 : i === 2 || i === 8) roundWindow(w.group, c, 0, y, r);
  });
}
// closes the roof from underneath, outside the walls only
function soffit(c, Re, color) {
  K.add(c.roofG, new THREE.RingGeometry(c.R + 0.32, Re + 0.1, c.sides, 1), K.std(color, { key: "ext" }), 0, c.H + 0.03, 0, { rx: Math.PI / 2, cast: false });
}
const eave = (c) => 1.3 * c.R + 0.12;
function dome(c, color, h, extra) {
  const Re = eave(c);
  const d = K.add(c.roofG, new THREE.SphereGeometry(1, 20, 8, 0, Math.PI * 2, 0, Math.PI / 2), roofMat(color, extra), 0, c.H + 0.02, 0);
  d.scale.set(Re, h, Re);
  soffit(c, Re, K.shadeHex(color, 0.85));
  return Re;
}
function bow(parent, x, y, z, s, color) {
  const g = new THREE.Group();
  g.position.set(x, y, z);
  g.scale.setScalar(s);
  parent.add(g);
  const m = K.std(color, { key: "ext" });
  for (const d of [-1, 1]) {
    const loop = K.add(g, new THREE.SphereGeometry(0.6, 8, 6), m, d * 0.72, 0.1, 0, { rz: d * 0.35 });
    loop.scale.set(1.25, 0.8, 0.55);
    K.add(g, K.box(0.34, 1.0, 0.12), m, d * 0.38, -0.6, 0.02, { rz: d * 0.45 });
  }
  K.add(g, new THREE.SphereGeometry(0.3, 8, 6), K.std(K.shadeHex(color, 0.85), { key: "ext" }), 0, 0, 0.12);
  return g;
}
function bob(world, obj, amp = 0.12, speed = 1.6, spin = 0) {
  const y = obj.position.y;
  const ph = Math.random() * 6;
  world.animated.push((t) => {
    obj.position.y = y + Math.sin(t * speed + ph) * amp;
    if (spin) obj.rotation.y = t * spin + ph;
  });
}

// a box round the six walls (for the present and the camera): the body, a
// short porch from its front to the real door, and a lid that holds the old roof
function boxShell(world, room, c, bodyMat, lidMat) {
  const hxL = 1.28 * c.R + 0.14;
  const hzL = 1.28 * c.R * Math.cos(Math.PI / 6) + 0.14;
  const hx = hxL - 0.35;
  const hz = hzL - 0.35;
  const Hs = c.H + 0.25;
  const t = 0.14;
  const g = c.group;
  K.add(g, K.box(hx * 2, Hs, t), bodyMat, 0, Hs / 2, -hz + t / 2);
  for (const s of [-1, 1]) K.add(g, K.box(t, Hs, hz * 2), bodyMat, s * (hx - t / 2), Hs / 2, 0);
  const side = hx - c.doorW / 2;
  for (const s of [-1, 1]) K.add(g, K.box(side, Hs, t), bodyMat, s * (c.doorW / 2 + side / 2), Hs / 2, hz - t / 2);
  K.add(g, K.box(c.doorW, Hs - c.doorH, t), bodyMat, 0, c.doorH + (Hs - c.doorH) / 2, hz - t / 2);
  // the porch
  const z0 = c.apo + c.thick / 2;
  const depth = hz - z0;
  const m = white();
  // frames overlap the opening and each other with no shared faces (shared faces flicker)
  for (const s of [-1, 1]) K.add(g, K.box(0.14, c.doorH, depth - 0.01), m, s * (c.doorW / 2 + 0.04), c.doorH / 2, z0 + depth / 2);
  K.add(g, K.box(c.doorW + 0.26, 0.15, depth + 0.01), m, 0, c.doorH + 0.045, z0 + depth / 2);
  K.add(g, K.box(c.doorW, 0.05, depth + 0.3), m, 0, 0.02, z0 + depth / 2 + 0.15, { cast: false });
  for (const s of [-1, 1]) K.add(g, K.box(0.27, c.doorH + 0.21, 0.19), m, s * (c.doorW / 2 + 0.105), (c.doorH + 0.21) / 2, hz + 0.04);
  K.add(g, K.box(c.doorW + 0.5, 0.27, 0.21), m, 0, c.doorH + 0.095, hz + 0.04);
  // you bump into the box, not the walls hidden inside it
  const seg = (x1, z1, x2, z2) => {
    const a = new THREE.Vector3(x1, 0, z1).applyMatrix4(g.matrixWorld);
    const b = new THREE.Vector3(x2, 0, z2).applyMatrix4(g.matrixWorld);
    world.addWallSegment(a.x, a.z, b.x, b.z);
  };
  seg(-hx, -hz, hx, -hz);
  seg(hx, -hz, hx, hz);
  seg(-hx, -hz, -hx, hz);
  seg(-hx, hz, -c.doorW / 2, hz);
  seg(c.doorW / 2, hz, hx, hz);
  for (const s of [-1, 1]) seg((s * c.doorW) / 2, z0, (s * c.doorW) / 2, hz);
  // the lid
  const lidH = c.roofH + 0.3;
  const lidY = c.H + 0.2;
  // open underneath, so the old ceiling is still what you see from inside
  K.add(c.roofG, K.box(hxL * 2, 0.14, hzL * 2), lidMat, 0, lidY + lidH - 0.07, 0);
  for (const d of [-1, 1]) {
    K.add(c.roofG, K.box(hxL * 2, lidH, 0.14), lidMat, 0, lidY + lidH / 2, d * (hzL - 0.07));
    K.add(c.roofG, K.box(0.14, lidH, hzL * 2), lidMat, d * (hxL - 0.07), lidY + lidH / 2, 0);
    K.add(c.roofG, K.box(hxL * 2, 0.06, 0.5), lidMat, 0, lidY + 0.03, d * (hzL - 0.25), { cast: false });
    K.add(c.roofG, K.box(0.5, 0.06, hzL * 2), lidMat, d * (hxL - 0.25), lidY + 0.03, 0, { cast: false });
  }
  room.eave = Math.hypot(hxL, hzL) + 0.3;
  Object.assign(c, { box: true, front: hz, boxHx: hxL, boxHz: hzL, lidY });
  return { hx, hz, hxL, hzL, Hs, lidH, lidY, top: lidY + lidH };
}

// ---- one look per room ------------------------------------------------------
const STYLES = {
  // now playing: a lilac music box with piano keys round the roof and a gramophone horn
  song(world, room, c) {
    skin(room, c, "#e8defd", "#cdbdf4");
    pillars(c, white());
    doorway(room, c);
    windows(room, c);
    const h = c.roofH + 0.3;
    const Re = dome(c, "#b9a6f0", h);
    const keys = tex(256, 64, (g) => {
      g.fillStyle = "#fffdf8";
      g.fillRect(0, 0, 256, 64);
      g.fillStyle = "#cfc6de";
      for (let i = 0; i < 8; i++) g.fillRect(i * 32 - 1, 0, 2, 64);
      g.fillStyle = "#3a3350";
      for (let i = 1; i < 8; i++) if (i % 4) g.fillRect(i * 32 - 10, 0, 20, 38);
    }, 7, 1);
    K.add(c.roofG, new THREE.CylinderGeometry(Re + 0.06, Re + 0.06, 0.62, 40, 1, true), K.std("#ffffff", { map: keys, side: THREE.DoubleSide, key: "ext" }), 0, c.H + 0.32, 0);
    // the horn
    const top = c.H + h;
    K.add(c.roofG, K.cyl(0.5, 0.75, 0.5, 10), white(), 0, top + 0.05, 0);
    const horn = new THREE.Group();
    horn.position.set(0, top + 0.2, 0);
    horn.rotation.x = 0.75;
    c.roofG.add(horn);
    K.add(horn, new THREE.CylinderGeometry(1.7, 0.16, 2.6, 14, 1, true), K.std("#ffd27a", { side: THREE.DoubleSide, metalness: 0.4, roughness: 0.4, emissive: "#ffb648", emissiveIntensity: 0.25, key: "exthorn" }), 0, 1.3, 0);
    K.add(horn, new THREE.TorusGeometry(1.7, 0.09, 6, 20), gold(), 0, 2.6, 0, { rx: Math.PI / 2 });
    // notes drifting out of it
    const noteMat = K.std("#7b5cd6", { key: "ext" });
    [[1.2, 2.2, 3.2], [-1.6, 3.0, 2.2], [0.3, 3.9, 3.6]].forEach(([x, y, z], i) => {
      const n = new THREE.Group();
      n.position.set(x, top + y, z);
      n.scale.setScalar(1.15);
      c.roofG.add(n);
      const head = K.add(n, new THREE.SphereGeometry(0.24, 8, 6), i === 1 ? K.std(PINK, { key: "ext" }) : noteMat, 0, 0, 0, { rz: 0.4 });
      head.scale.set(1.2, 0.85, 0.8);
      K.add(n, K.box(0.07, 0.8, 0.07), i === 1 ? K.std(PINK, { key: "ext" }) : noteMat, 0.22, 0.4, 0);
      K.add(n, K.box(0.3, 0.14, 0.07), i === 1 ? K.std(PINK, { key: "ext" }) : noteMat, 0.36, 0.72, 0, { rz: -0.4 });
      bob(world, n, 0.22, 1.2 + i * 0.3);
    });
    room.labelY = top + 5.6;
  },

  // smol note: a stubby pencil, eraser end down
  note(world, room, c) {
    skin(room, c, "#ffe08f");
    belt(room, c, 0.42, 0.84, K.std("#ff9dbd", { key: "ext" }), 0.06); // the eraser
    belt(room, c, 1.0, 0.34, K.std("#cfc3ee", { metalness: 0.3, roughness: 0.45, key: "extmetal" }), 0.09); // the metal band
    pillars(c, K.std("#ffd166", { key: "ext" }), 0.24);
    doorway(room, c);
    windows(room, c, c.H * 0.62, 0.5);
    const Re = eave(c);
    const h = c.roofH + 2.0; // tall enough that the lead tip sits above the ceiling inside
    const turn = { ry: Math.PI / c.sides };
    K.add(c.roofG, new THREE.ConeGeometry(Re, h, c.sides, 1, true), roofMat("#f6d9b0"), 0, c.H + 0.02 + h / 2, 0, turn);
    K.add(c.roofG, new THREE.ConeGeometry(Re * 0.3 + 0.04, h * 0.3 + 0.04, c.sides), K.std("#5d5672", { key: "ext" }), 0, c.H + 0.02 + h - (h * 0.3) / 2, 0, turn);
    soffit(c, Re, "#ffe08f");
    // a little note pinned by the door
    const wg = room.walls[0].group;
    const z = c.thick / 2 + T + 0.03;
    const paper = new THREE.Group();
    paper.position.set(2.05, 1.85, z);
    paper.rotation.z = -0.1;
    wg.add(paper);
    K.add(paper, K.box(0.95, 1.15, 0.04), white(), 0, 0, 0);
    for (let i = 0; i < 3; i++) K.add(paper, K.box(0.62 - i * 0.12, 0.05, 0.02), K.std("#c9bcd6", { key: "ext" }), -0.06 - i * 0.06, 0.28 - i * 0.2, 0.03, { cast: false });
    K.add(paper, K.heartGeo(0.3), K.glow.pink, 0.2, -0.32, 0.05, { cast: false });
    K.add(paper, new THREE.SphereGeometry(0.07, 6, 5), K.std(PINK, { key: "ext" }), 0, 0.5, 0.05);
    room.labelY = c.H + h + 1.2;
  },

  // pin it: an instant camera
  photos(world, room, c) {
    const s = boxShell(world, room, c, K.std(WHITE, { key: "ext" }), K.std("#cfe3ff", { key: "ext" }));
    const g = c.group;
    // the rainbow stripe
    ["#ff8fb1", "#ffd166", "#9fe0a6", "#8fc8f5"].forEach((col, i) => K.add(g, K.box(0.26, s.Hs, 0.05), K.std(col, { key: "ext" }), -3.6 + i * 0.26, s.Hs / 2, s.hz + 0.03, { cast: false }));
    // the lens, over the door
    const ly = s.lidY + s.lidH / 2;
    const lz = s.hzL;
    K.add(c.roofG, K.cyl(1.32, 1.42, 0.7, 20), white(), 0, ly, lz + 0.3, { rx: Math.PI / 2 });
    K.add(c.roofG, K.cyl(1.05, 1.05, 0.2, 20), K.std("#8fa8d8", { key: "ext" }), 0, ly, lz + 0.62, { rx: Math.PI / 2 });
    K.add(c.roofG, new THREE.CircleGeometry(0.88, 20), K.std("#2a2550", { emissive: "#3b3a8a", emissiveIntensity: 0.5, roughness: 0.2, key: "extglass" }), 0, ly, lz + 0.73, { cast: false });
    K.add(c.roofG, new THREE.CircleGeometry(0.2, 10), new THREE.MeshBasicMaterial({ color: "#ffffff" }), -0.32, ly + 0.34, lz + 0.74, { cast: false });
    K.add(c.roofG, new THREE.CircleGeometry(0.09, 8), new THREE.MeshBasicMaterial({ color: "#ffffff" }), 0.28, ly - 0.3, lz + 0.74, { cast: false });
    // flash, viewfinder and the button
    K.add(c.roofG, K.box(1.9, 0.9, 0.3), white(), s.hxL - 1.9, ly + 0.5, lz + 0.14);
    K.add(c.roofG, K.box(1.5, 0.55, 0.06), K.glow.warm, s.hxL - 1.9, ly + 0.5, lz + 0.31, { cast: false });
    K.add(c.roofG, K.box(1.1, 0.75, 0.2), K.std("#2a2550", { key: "ext" }), -s.hxL + 1.8, ly + 0.55, lz + 0.1);
    K.add(c.roofG, K.cyl(0.62, 0.62, 0.4, 14), K.std(PINK, { key: "ext" }), -s.hxL + 2.2, s.top + 0.2, 0.6);
    K.add(c.roofG, K.cyl(0.8, 0.8, 0.12, 14), white(), -s.hxL + 2.2, s.top + 0.06, 0.6);
    // a photo sliding out of the side of the door
    const photo = new THREE.Group();
    photo.position.set(3.2, 1.75, s.hz + 0.06);
    photo.rotation.z = 0.12;
    g.add(photo);
    K.add(photo, K.box(1.25, 1.5, 0.05), white(), 0, 0, 0);
    K.add(photo, K.box(1.02, 1.0, 0.02), K.std("#ffc9dc", { key: "ext" }), 0, 0.15, 0.03, { cast: false });
    K.add(photo, K.heartGeo(0.5), K.glow.pink, 0, 0.15, 0.07, { cast: false });
    roundWindow(g, { thick: (s.hz - T) * 2 }, -5.3, 1.9, 0.55);
    roundWindow(g, { thick: (s.hz - T) * 2 }, 5.6, 1.9, 0.55);
    room.labelY = s.top + 1.6;
  },

  // important dates: a mint clock tower under a bell roof, with a gold spire on top
  calendar(world, room, c) {
    skin(room, c, "#d9f6e8", "#b4e6cf");
    pillars(c, white(), 0.26);
    doorway(room, c, false);
    room.walls.forEach((w, i) => {
      if (i === 2 || i === 8) roundWindow(w.group, c, 0, 2.0, 0.5);
      if (i === 3 || i === 7) roundWindow(w.group, c, 0, 4.0, 0.45, false);
    });
    // today's page, either side of the clock
    const d = new Date();
    const page = tex(256, 300, (g) => {
      g.fillStyle = "#fffdf8";
      g.fillRect(0, 0, 256, 300);
      g.fillStyle = PINK;
      g.fillRect(0, 0, 256, 84);
      g.fillStyle = "#ffffff";
      g.textAlign = "center";
      g.textBaseline = "middle";
      g.font = 'bold 52px "Fredoka", "Quicksand", sans-serif';
      g.fillText(d.toLocaleString("en", { month: "short" }).toLowerCase(), 128, 44);
      g.fillStyle = "#4a3f5c";
      g.font = 'bold 170px "Fredoka", "Quicksand", sans-serif';
      g.fillText(String(d.getDate()), 128, 200);
    });
    for (const i of [1, 9]) {
      const wg = room.walls[i].group;
      const z = c.thick / 2 + T;
      K.add(wg, K.box(1.75, 2.05, 0.08), white(), 0, 3.5, z + 0.03);
      K.add(wg, new THREE.PlaneGeometry(1.55, 1.82), new THREE.MeshStandardMaterial({ map: page, roughness: 0.9 }), 0, 3.5, z + 0.08, { cast: false });
      for (const s of [-1, 1]) K.add(wg, new THREE.TorusGeometry(0.12, 0.035, 5, 10), gold(), s * 0.45, 4.52, z + 0.08, { ry: Math.PI / 2 });
    }
    const Re = eave(c);
    const prof = [[1, 0], [0.97, 0.6], [0.82, 1.7], [0.55, 2.9], [0.24, 3.9], [0.07, 4.5], [0, 5.3]].map(([r, y]) => new THREE.Vector2(r * Re, y));
    K.add(c.roofG, new THREE.LatheGeometry(prof, 16), roofMat("#7fd1ba"), 0, c.H + 0.02, 0);
    K.add(c.roofG, new THREE.TorusGeometry(Re, 0.2, 6, 28), white(), 0, c.H + 0.08, 0, { rx: Math.PI / 2 });
    soffit(c, Re, "#b4e6cf");
    const top = c.H + 5.3;
    // a gold ball and spire on top
    K.add(c.roofG, new THREE.IcosahedronGeometry(0.42, 1), gold(), 0, top + 0.35, 0);
    const spire = K.add(c.roofG, new THREE.ConeGeometry(0.14, 1.1, 8), gold(), 0, top + 1.25, 0);
    world.animated.push((t) => (spire.rotation.y = t * 0.6));
    room.labelY = top + 2.3;
  },

  // toto's poems: an ink bottle with a feather quill, stars in the ink
  poems(world, room, c) {
    skin(room, c, "#fff1e2", "#f3d7c2");
    pillars(c, white());
    doorway(room, c);
    windows(room, c);
    const h = c.roofH + 0.2;
    const Re = dome(c, "#5d52a8", h, { emissive: "#2c2466", emissiveIntensity: 0.35, roughness: 0.4, key: "extink" });
    K.add(c.roofG, new THREE.TorusGeometry(Re, 0.2, 6, 28), gold(), 0, c.H + 0.1, 0, { rx: Math.PI / 2 });
    const starM = new THREE.MeshBasicMaterial({ color: "#fff2b8" });
    for (let i = 0; i < 16; i++) {
      const a = i * 2.4;
      const up = 0.25 + ((i * 37) % 60) / 100;
      const r = Math.sqrt(1 - up * up);
      const st = K.add(c.roofG, starGeo(), starM, Math.sin(a) * r * Re * 1.01, c.H + up * h * 1.01, Math.cos(a) * r * Re * 1.01, { cast: false });
      st.scale.setScalar(0.12 + (i % 3) * 0.05);
      st.lookAt(0, c.H - 4, 0);
    }
    const top = c.H + h;
    K.add(c.roofG, K.cyl(1.35, 1.65, 1.3, 12), K.std("#5d52a8", { key: "ext" }), 0, top + 0.3, 0);
    K.add(c.roofG, new THREE.TorusGeometry(1.4, 0.24, 6, 16), gold(), 0, top + 0.95, 0, { rx: Math.PI / 2 });
    const quill = new THREE.Group();
    quill.position.set(0, top + 0.8, 0);
    quill.rotation.set(0.2, 0, -0.45);
    c.roofG.add(quill);
    K.add(quill, K.cyl(0.035, 0.07, 4.6, 6), white(), 0, 2.2, 0);
    const vane = K.add(quill, new THREE.SphereGeometry(1, 10, 8), K.std("#ffd3e3", { key: "ext" }), 0, 3.0, 0);
    vane.scale.set(0.62, 1.75, 0.07);
    const vane2 = K.add(quill, new THREE.SphereGeometry(1, 10, 8), white(), 0.05, 3.0, 0.03);
    vane2.scale.set(0.36, 1.5, 0.07);
    world.animated.push((t) => (quill.rotation.z = -0.45 + Math.sin(t * 0.9) * 0.05));
    room.labelY = top + 6.2;
  },

  // toto's gift: a wrapped present with a big bow
  gift(world, room, c) {
    const body = K.std("#ffffff", { map: dots("#ffc3d8", "#fffafc", 5, 2), key: "ext" });
    const s = boxShell(world, room, c, body, K.std("#ffdbe7", { key: "ext" }));
    const g = c.group;
    const rib = K.std(PINK, { key: "ext" });
    // ribbon over the lid and down the sides
    K.add(c.roofG, K.box(1.5, 0.08, s.hzL * 2 + 0.1), rib, 0, s.top + 0.02, 0);
    K.add(c.roofG, K.box(s.hxL * 2 + 0.1, 0.08, 1.5), rib, 0, s.top + 0.02, 0);
    for (const d of [-1, 1]) {
      K.add(c.roofG, K.box(1.5, s.lidH + 0.08, 0.08), rib, 0, s.lidY + s.lidH / 2, d * (s.hzL + 0.02));
      K.add(c.roofG, K.box(0.08, s.lidH + 0.08, 1.5), rib, d * (s.hxL + 0.02), s.lidY + s.lidH / 2, 0);
    }
    K.add(g, K.box(1.5, s.Hs, 0.08), rib, 0, s.Hs / 2, -s.hz - 0.02);
    for (const d of [-1, 1]) K.add(g, K.box(0.08, s.Hs, 1.5), rib, d * (s.hx + 0.02), s.Hs / 2, 0);
    bow(c.roofG, 0, s.top + 1.0, 0, 2.3, PINK);
    // the tag
    const tag = new THREE.Group();
    tag.position.set(-s.hxL + 2.4, s.lidY + s.lidH * 0.5, s.hzL + 0.06);
    tag.rotation.z = 0.18;
    c.roofG.add(tag);
    K.add(tag, K.box(1.3, 1.8, 0.06), white(), 0, 0, 0);
    K.add(tag, K.heartGeo(0.62), K.glow.pink, 0, -0.15, 0.08, { cast: false });
    K.add(tag, new THREE.TorusGeometry(0.1, 0.03, 5, 10), gold(), 0, 0.68, 0.04);
    roundWindow(g, { thick: (s.hz - T) * 2 }, -4.0, 1.9, 0.55);
    roundWindow(g, { thick: (s.hz - T) * 2 }, 4.0, 1.9, 0.55);
    room.labelY = s.top + 3.6;
  },

  // our wardrobe: a striped boutique tent with a bow over the door
  wardrobe(world, room, c) {
    skin(room, c, "#f6efff", "#dccdf8");
    pillars(c, K.std("#ffffff", { map: stripes("#cdb8f5", WHITE, 1), key: "extpole" }), 0.26);
    doorway(room, c);
    windows(room, c);
    const Re = eave(c);
    const h = c.roofH + 0.9;
    K.add(c.roofG, new THREE.ConeGeometry(Re, h, 24, 1, true), K.std("#ffffff", { map: stripes("#c6aef2", WHITE, 12), side: THREE.DoubleSide, key: "ext" }), 0, c.H + 0.02 + h / 2, 0);
    soffit(c, Re, "#dccdf8");
    const half = new THREE.CircleGeometry(0.46, 8, Math.PI, Math.PI);
    const mats = [K.std("#c6aef2", { side: THREE.DoubleSide, key: "ext" }), K.std(WHITE, { side: THREE.DoubleSide, key: "ext" })];
    for (let i = 0; i < 48; i++) {
      const a = ((i + 0.5) / 48) * Math.PI * 2;
      K.add(c.roofG, half, mats[i % 2], Math.sin(a) * Re, c.H + 0.04, Math.cos(a) * Re, { ry: a, cast: false });
    }
    const top = c.H + h;
    K.add(c.roofG, K.cyl(0.05, 0.05, 1.6, 6), gold(), 0, top + 0.7, 0);
    K.add(c.roofG, new THREE.SphereGeometry(0.2, 8, 6), gold(), 0, top + 1.55, 0);
    const flag = new THREE.Shape();
    flag.moveTo(0, 0.35);
    flag.lineTo(1.1, 0);
    flag.lineTo(0, -0.35);
    const pennant = K.add(c.roofG, new THREE.ShapeGeometry(flag), K.std(PINK, { side: THREE.DoubleSide, key: "ext" }), 0, top + 1.05, 0, { cast: false });
    world.animated.push((t) => (pennant.rotation.y = Math.sin(t * 1.3) * 0.5));
    bow(room.walls[0].group, 0, c.H + 0.1, c.thick / 2 + T + 0.3, 0.95, PINK);
    room.labelY = top + 2.8;
  },

  // art studio: a paint pot brimming over, with a brush standing in it
  art(world, room, c) {
    const splat = tex(256, 256, (g) => {
      g.fillStyle = WHITE;
      g.fillRect(0, 0, 256, 256);
      const cols = ["#ff9fbf", "#ffd98a", "#a9e3b4", "#9fd0f7", "#cdb8f5"];
      for (let i = 0; i < 18; i++) {
        g.fillStyle = cols[i % 5];
        g.beginPath();
        g.arc((i * 71) % 256, 20 + ((i * 97) % 220), 7 + ((i * 13) % 10), 0, 7);
        g.fill();
      }
    }, 2, 1.4);
    skin(room, c, WHITE, null, splat);
    belt(room, c, 0.3, 0.6, K.std("#ffb49f", { key: "ext" }), 0.05);
    pillars(c, white());
    doorway(room, c);
    windows(room, c);
    const paint = "#ff9c8c";
    const h = c.roofH + 0.25;
    const Re = dome(c, paint, h);
    const pm = K.std(paint, { key: "ext" });
    K.add(c.roofG, new THREE.TorusGeometry(Re - 0.15, 0.34, 6, 30), pm, 0, c.H + 0.2, 0, { rx: Math.PI / 2 });
    for (let i = 0; i < 18; i++) {
      const a = (i / 18) * Math.PI * 2 + 0.17;
      const len = 0.35 + ((i * 53) % 100) / 80;
      const rad = 0.2 + ((i * 29) % 10) / 70;
      K.add(c.roofG, new THREE.CapsuleGeometry(rad, len, 3, 8), pm, Math.sin(a) * (Re - 0.12), c.H + 0.1 - len / 2, Math.cos(a) * (Re - 0.12));
    }
    // the brush
    const top = c.H + h;
    const brush = new THREE.Group();
    brush.position.set(0.4, top - 0.3, 0);
    brush.rotation.z = -0.3;
    c.roofG.add(brush);
    K.add(brush, K.cyl(0.17, 0.24, 2.4, 8), K.std("#8fc8f5", { key: "ext" }), 0, 1.2, 0);
    K.add(brush, K.cyl(0.32, 0.26, 0.55, 8), K.std("#e6e3f2", { metalness: 0.5, roughness: 0.35, key: "extmetal" }), 0, 2.65, 0);
    const hair = K.add(brush, new THREE.SphereGeometry(1, 8, 8), K.std("#f3dcb8", { key: "ext" }), 0, 3.35, 0);
    hair.scale.set(0.42, 0.85, 0.3);
    const tip = K.add(brush, new THREE.SphereGeometry(1, 8, 8), K.std("#b79be8", { key: "ext" }), 0, 3.85, 0);
    tip.scale.set(0.34, 0.5, 0.26);
    // a palette by the door
    const wg = room.walls[0].group;
    const z = c.thick / 2 + T;
    K.add(wg, K.cyl(0.72, 0.72, 0.08, 14), K.std("#f3dcb8", { key: "ext" }), 2.05, 1.9, z + 0.05, { rx: Math.PI / 2 });
    ["#ff8fb1", "#ffd166", "#9fe0a6", "#8fc8f5", "#b79be8"].forEach((col, i) => {
      const a = -0.6 + i * 0.75;
      K.add(wg, new THREE.SphereGeometry(0.13, 6, 5), K.std(col, { key: "ext" }), 2.05 + Math.cos(a) * 0.42, 1.9 + Math.sin(a) * 0.42, z + 0.1, { cast: false });
    });
    room.labelY = top + 5.2;
  },

  // our diary: a blush cottage with an open book laid over it for a roof
  diary(world, room, c) {
    const { W, D, H } = c;
    skin(room, c, "#ffe3ec", "#f6bfd2");
    pillars(c, white(), 0.36);
    doorway(room, c);
    // shutters and frames on the new coat, where the windows were
    const shut = K.std("#f6bfd2", { key: "ext" });
    const win = (wg, x, w) => {
      const z = c.thick / 2 + T;
      K.add(wg, K.box(w, 1.15, 0.05), K.glow.warm, x, 1.92, z + 0.01, { cast: false });
      K.add(wg, K.box(w + 0.2, 0.1, 0.1), white(), x, 2.54, z + 0.03);
      K.add(wg, K.box(w + 0.2, 0.1, 0.1), white(), x, 1.3, z + 0.03);
      K.add(wg, K.box(0.07, 1.15, 0.07), white(), x, 1.92, z + 0.03, { cast: false });
      K.add(wg, K.box(w, 0.07, 0.07), white(), x, 1.92, z + 0.03, { cast: false });
      for (const s of [-1, 1]) {
        K.add(wg, K.box(0.5, 1.3, 0.07), shut, x + s * (w / 2 + 0.3), 1.92, z + 0.03);
        K.add(wg, K.heartGeo(0.22), white(), x + s * (w / 2 + 0.3), 2.2, z + 0.08, { cast: false });
      }
    };
    for (const x of [-4.6, 4.6]) win(room.walls[0].group, x, 1.45);
    for (const i of [1, 3]) for (const x of [-2.5, 2.5]) {
      win(room.walls[i].group, x, 1.35);
      flowerBox(room.walls[i].group, x, 1.12, c.thick / 2 + T, 1.6);
    }
    win(room.walls[2].group, 5.6, 1.35);

    // the book: cream pages under a rose cover on each slope, a spine along the ridge
    const y0 = H + 0.1;
    const hw = D / 2 + 1.1;
    const rise = 3.6;
    const a = Math.atan2(rise, hw);
    const sl = Math.hypot(hw, rise);
    const len = W + 1.4;
    const cover = K.std("#e98aa9", { key: "ext" });
    const pages = K.std("#fff6e6", { key: "ext" });
    for (const s of [1, -1]) {
      const slab = (w, t, l, d, m) => {
        const cy = y0 + rise / 2 - Math.sin(a) * 0.25 + Math.cos(a) * d;
        const cz = s * (hw / 2 + Math.cos(a) * 0.25 + Math.sin(a) * d);
        return K.add(c.roofG, K.box(w, t, l), m, 0, cy, cz, { rx: s * a });
      };
      slab(len + 0.2, 0.3, sl + 0.25, 0.17, pages);
      slab(len + 0.7, 0.14, sl + 0.6, 0.4, cover);
    }
    K.add(c.roofG, K.cyl(0.5, 0.5, len + 0.8, 10), K.std("#d96d92", { key: "ext" }), 0, y0 + rise + 0.3, 0, { rz: Math.PI / 2 });
    for (const x of [-len / 2 + 1.2, len / 2 - 1.2]) K.add(c.roofG, K.cyl(0.55, 0.55, 0.3, 10), gold(), x, y0 + rise + 0.3, 0, { rz: Math.PI / 2 });
    // the ends of the book: pages, with a round window
    const tri = new THREE.Shape();
    tri.moveTo(-hw - 0.2, 0);
    tri.lineTo(0, rise + 0.12);
    tri.lineTo(hw + 0.2, 0);
    const end = new THREE.ExtrudeGeometry(tri, { depth: 0.12, bevelEnabled: false });
    end.rotateY(Math.PI / 2);
    for (const s of [-1, 1]) {
      K.add(c.roofG, end, pages, s * (len / 2 + 0.04) - 0.06, y0, 0);
      const x = s * (len / 2 + 0.12);
      K.add(c.roofG, new THREE.CircleGeometry(0.75, 18), K.glow.warm, x, y0 + 1.25, 0, { ry: (s * Math.PI) / 2, cast: false });
      K.add(c.roofG, new THREE.TorusGeometry(0.75, 0.1, 6, 18), white(), x, y0 + 1.25, 0, { ry: Math.PI / 2 });
    }
    // the title on the cover, facing the willow
    const title = tex(1024, 256, (g) => {
      g.textAlign = "center";
      g.textBaseline = "middle";
      g.font = 'bold 150px "Fredoka", "Quicksand", sans-serif';
      g.fillStyle = "#fff3c9";
      g.fillText("our diary ♡", 512, 132);
    });
    const d = 0.49;
    K.add(c.roofG, new THREE.PlaneGeometry(7.2, 1.8), new THREE.MeshBasicMaterial({ map: title, transparent: true }), -3.4, y0 + rise * 0.62 + Math.cos(a) * d, hw * 0.38 + Math.sin(a) * d, { rx: -(Math.PI / 2 - a), cast: false });
    // a ribbon bookmark hanging off the front
    const rib = K.std(PINK, { key: "ext" });
    K.add(c.roofG, K.box(0.8, 0.05, sl + 0.7), rib, 5.2, y0 + rise / 2 - Math.sin(a) * 0.25 + Math.cos(a) * 0.5, hw / 2 + Math.cos(a) * 0.25 + Math.sin(a) * 0.5, { rx: a });
    K.add(c.roofG, K.box(0.8, 1.5, 0.05), rib, 5.2, y0 - 0.95, hw + 0.62);
    room.labelY = y0 + rise + 2.6;
  },
};

// ---- the finishing touches outside, and insides that match -------------------
const THEMES = {
  song: { accent: "#9a86d6", deep: "#cdbdf4", door: "#b9a6f0", wall: "notes", ceil: "notesSky", hang: "note", pot: "#b9a6f0" },
  note: { accent: "#f2a65a", deep: "#ffd166", door: "#ff9dbd", wall: "lined", ceil: "wood", hang: "heart", pot: "#ff9dbd" },
  photos: { accent: "#7aa8d8", deep: "#8fc8f5", door: "#8fa8d8", wall: "polaroids", ceil: "clouds", hang: "photo", pot: "#8fc8f5" },
  calendar: { accent: "#4e9a6a", deep: "#7fd1ba", door: "#7fd1ba", wall: "mintStars", ceil: "night", hang: "star", pot: "#7fd1ba" },
  poems: { accent: "#5d52a8", deep: "#5d52a8", door: "#5d52a8", wall: "inkStars", ceil: "night", hang: "star", pot: "#5d52a8" },
  gift: { accent: "#e2557f", deep: "#f07aa0", door: "#f07aa0", wall: "dots", ceil: "stripesPink", hang: "heart", pot: "#f07aa0" },
  wardrobe: { accent: "#9a7bd0", deep: "#c6aef2", door: "#c6aef2", wall: "stripesLilac", ceil: "stripesLilac", hang: "heart", pot: "#c6aef2" },
  art: { accent: "#ef8a5a", deep: "#ffb49f", door: "#ff9c8c", wall: "splats", ceil: "splats", hang: "drop", pot: "#ff9c8c" },
  diary: { accent: "#e2557f", deep: "#f6bfd2", door: "#e98aa9", wall: "hearts", ceil: "heartsCream", hang: "heart", pot: "#e98aa9" },
};

const patterns = new Map();
function pattern(kind) {
  if (patterns.has(kind)) return patterns.get(kind);
  const S = 256;
  const t = tex(S, S, (g) => {
    const dot = (x, y, r, col) => {
      g.fillStyle = col;
      g.beginPath();
      g.arc(x, y, r, 0, 7);
      g.fill();
    };
    const heart = (x, y, s, col) => {
      g.fillStyle = col;
      g.beginPath();
      g.moveTo(x, y + s * 0.35);
      g.bezierCurveTo(x - s * 0.9, y - s * 0.25, x - s * 0.4, y - s * 0.9, x, y - s * 0.4);
      g.bezierCurveTo(x + s * 0.4, y - s * 0.9, x + s * 0.9, y - s * 0.25, x, y + s * 0.35);
      g.fill();
    };
    const star = (x, y, r, col) => {
      g.fillStyle = col;
      g.beginPath();
      for (let i = 0; i < 10; i++) {
        const rr = i % 2 ? r * 0.45 : r;
        const a = (i / 10) * Math.PI * 2 - Math.PI / 2;
        g[i ? "lineTo" : "moveTo"](x + Math.cos(a) * rr, y + Math.sin(a) * rr);
      }
      g.fill();
    };
    const note = (x, y, col) => {
      dot(x, y, 9, col);
      g.fillStyle = col;
      g.fillRect(x + 6, y - 34, 4, 34);
      g.fillRect(x + 6, y - 34, 16, 6);
    };
    const bg = (c) => {
      g.fillStyle = c;
      g.fillRect(0, 0, S, S);
    };
    const stripes = (a, b) => {
      for (let i = 0; i < 4; i++) {
        g.fillStyle = i % 2 ? b : a;
        g.fillRect((i * S) / 4, 0, S / 4, S);
      }
    };
    switch (kind) {
      case "notes":
        bg("#f1eaff");
        g.fillStyle = "rgba(154,134,214,0.25)";
        for (let i = 0; i < 5; i++) g.fillRect(0, 150 + i * 12, S, 2);
        note(60, 80, "#c2b2ee");
        note(190, 60, "#f2a9c4");
        note(120, 230, "#c2b2ee");
        break;
      case "notesSky":
        bg("#ddd2fb");
        note(70, 90, "#ffffff");
        note(190, 200, "#ffd27a");
        star(200, 60, 10, "#ffffff");
        break;
      case "lined":
        bg("#fffaf0");
        g.fillStyle = "#cfe0f7";
        for (let y = 20; y < S; y += 32) g.fillRect(0, y, S, 3);
        g.fillStyle = "#ffb3c7";
        g.fillRect(40, 0, 3, S);
        heart(180, 130, 18, "#ffc2d6");
        break;
      case "wood":
        bg("#f6dcb3");
        g.fillStyle = "#ead0a2";
        for (let y = 0; y < S; y += 32) g.fillRect(0, y, S, 14);
        break;
      case "polaroids":
        bg("#e9f3ff");
        [[60, 70, -0.15, "#ffc9dc"], [190, 150, 0.12, "#cfe3ff"], [90, 210, 0.08, "#d9f6e8"]].forEach(([x, y, a, inner]) => {
          g.save();
          g.translate(x, y);
          g.rotate(a);
          g.fillStyle = "#ffffff";
          g.fillRect(-26, -30, 52, 60);
          g.fillStyle = inner;
          g.fillRect(-21, -25, 42, 38);
          g.restore();
        });
        break;
      case "clouds":
        bg("#cfe6ff");
        for (const [x, y] of [[60, 70], [180, 180]]) for (const [dx, dy, r] of [[0, 0, 22], [24, 6, 18], [-22, 8, 16], [10, -12, 18]]) dot(x + dx, y + dy, r, "#ffffff");
        break;
      case "mintStars":
        bg("#e6faf1");
        for (const [x, y] of [[50, 60], [180, 90], [110, 190], [230, 220]]) star(x, y, 9, "#9bdcc4");
        dot(200, 30, 4, "#ffd27a");
        dot(30, 170, 4, "#ffd27a");
        break;
      case "night":
        bg("#3d3680");
        for (let i = 0; i < 18; i++) dot((i * 97) % S, (i * 57) % S, 1.5 + (i % 3), "#fff6c8");
        star(190, 70, 12, "#ffd27a");
        star(60, 190, 9, "#ffd27a");
        break;
      case "inkStars":
        bg("#f6f1ff");
        for (const [x, y] of [[50, 60], [180, 90], [110, 190], [230, 220]]) star(x, y, 8, "#d9c98a");
        for (let i = 0; i < 6; i++) dot((i * 83) % S, (i * 131) % S, 3, "#c9c2ee");
        break;
      case "dots":
        bg("#ffd3e2");
        for (const [x, y] of [[64, 64], [192, 192], [192, 64], [64, 192]]) dot(x, y, 16, "#fffafc");
        break;
      case "stripesPink":
        stripes("#ffc3d8", "#fffafc");
        break;
      case "stripesLilac":
        stripes("#ddd0fa", "#fffafc");
        break;
      case "splats":
        bg("#fffaf6");
        ["#ff9fbf", "#ffd98a", "#a9e3b4", "#9fd0f7", "#cdb8f5"].forEach((c, i) => {
          dot(30 + ((i * 97) % 200), 30 + ((i * 61) % 200), 14, c);
          dot(40 + ((i * 97) % 200), 48 + ((i * 61) % 200), 6, c);
        });
        break;
      case "hearts":
        bg("#ffeaf1");
        heart(64, 70, 22, "#ffc2d6");
        heart(192, 190, 22, "#ffc2d6");
        dot(190, 60, 4, "#ffffff");
        dot(60, 190, 4, "#ffffff");
        break;
      case "heartsCream":
        bg("#fff6ea");
        heart(70, 80, 20, "#f6bfd2");
        heart(190, 190, 20, "#f6bfd2");
        break;
      default:
        bg("#ffffff");
    }
  });
  patterns.set(kind, t);
  return t;
}

// a little thing hanging on a string, slowly turning
function hanging(world, parent, kind, at, top, len, col) {
  K.add(parent, K.cyl(0.012, 0.012, len, 4), K.std("#fff3f8", { key: "ext" }), at.x, top - len / 2, at.z, { cast: false });
  const g = new THREE.Group();
  g.position.set(at.x, top - len - 0.18, at.z);
  parent.add(g);
  const m = K.std(col, { key: "ext" });
  if (kind === "heart") K.add(g, K.heartGeo(0.36), m, 0, 0, 0, { cast: false });
  else if (kind === "star") {
    const s = K.add(g, starGeo(), K.glow.warm, 0, 0, 0, { cast: false });
    s.scale.setScalar(0.2);
  } else if (kind === "note") {
    const head = K.add(g, new THREE.SphereGeometry(0.11, 8, 6), m, 0, -0.12, 0, { cast: false });
    head.scale.set(1.25, 0.85, 0.7);
    K.add(g, K.box(0.04, 0.36, 0.04), m, 0.11, 0.06, 0, { cast: false });
  } else if (kind === "photo") {
    K.add(g, K.box(0.34, 0.4, 0.02), white(), 0, 0, 0, { cast: false });
    K.add(g, K.box(0.28, 0.26, 0.025), m, 0, 0.04, 0, { cast: false });
  } else if (kind === "drop") {
    const d = K.add(g, new THREE.SphereGeometry(0.13, 8, 6), m, 0, 0, 0, { cast: false });
    d.scale.set(1, 1.35, 1);
    K.add(g, new THREE.ConeGeometry(0.09, 0.16, 8), m, 0, 0.2, 0, { cast: false });
  }
  const ph = Math.random() * 6;
  world.animated.push((t) => {
    g.rotation.y = t * 0.6 + ph;
    g.rotation.z = Math.sin(t * 0.9 + ph) * 0.08;
  });
}

// the walls, windows, ceiling and a few hanging things inside
const BACK_SCREEN = new Set(["song", "gift", "wardrobe"]);
function dressInside(world, room, c, th) {
  const paper = pattern(th.wall).clone();
  paper.needsUpdate = true;
  paper.repeat.set(c.hall ? 5 : 3, c.hall ? 2.5 : c.H > 4 ? 3.2 : 2);
  for (const w of room.walls) {
    w.material.map = paper;
    w.material.color.set("#ffffff");
    w.material.needsUpdate = true;
  }
  // the old ceiling becomes a themed one
  const ceil = c.roofG.children[0];
  if (ceil?.material) {
    const p = pattern(th.ceil).clone();
    p.needsUpdate = true;
    p.repeat.set(c.hall ? 0.35 : 6, c.hall ? 0.35 : 2);
    // lit from within a little, so it keeps its colours up in the shadow
    ceil.material = new THREE.MeshStandardMaterial({ map: p, emissiveMap: p, emissive: "#ffffff", emissiveIntensity: 0.55, side: THREE.DoubleSide, flatShading: true, roughness: 0.9 });
  }
  const deep = K.std(th.deep, { key: "ext" });
  const rail = white();
  const zIn = -(c.thick / 2);
  room.walls.forEach((w, i) => {
    const L = c.hall ? c.lens[i] - 0.6 : c.lens[i] - 0.45;
    const side = (L - c.doorW) / 2 - 0.1;
    const pieces = i === 0 ? [[-(c.doorW / 2 + 0.05 + side / 2), side], [c.doorW / 2 + 0.05 + side / 2, side]] : [[0, L]];
    for (const [x, len] of pieces) {
      K.add(w.group, K.box(len, 0.95, 0.03), deep, x, 0.5, zIn - 0.015, { cast: false });
      K.add(w.group, K.box(len, 0.07, 0.07), rail, x, 0.99, zIn - 0.035, { cast: false });
    }
    K.add(w.group, K.box(L, 0.12, 0.06), rail, 0, c.H - 0.14, zIn - 0.03, { cast: false });
    if (c.hall) return;
    // the windows inside turn round, like the ones outside, with little curtains
    const winY = c.H * 0.55;
    const hasWin = c.sides === 6 ? i % 2 === 1 : i === 2 || i === 8;
    if (!hasWin || i === 0) return;
    for (const o of [...w.group.children]) {
      if (o.material === w.material) continue;
      if (Math.abs(o.position.x) < 0.7 && Math.abs(o.position.y - winY) < 0.62 && Math.abs(o.position.z) < 0.01) o.visible = false;
    }
    // the back wall holds the room's screen in these rooms: no window behind it
    if (BACK_SCREEN.has(room.def.id) && i === c.sides / 2) return;
    const r = 0.5;
    const z = zIn - 0.03;
    K.add(w.group, new THREE.CircleGeometry(r, 18), K.glow.warm, 0, winY, z, { ry: Math.PI, cast: false });
    K.add(w.group, new THREE.TorusGeometry(r, 0.07, 6, 18), rail, 0, winY, z, { cast: false });
    K.add(w.group, K.box(0.06, r * 2, 0.04), rail, 0, winY, z - 0.01, { cast: false });
    K.add(w.group, K.box(r * 2, 0.06, 0.04), rail, 0, winY, z - 0.01, { cast: false });
    for (const s of [-1, 1]) K.add(w.group, K.box(0.32, 1.25, 0.04), deep, s * (r + 0.12), winY - 0.1, z - 0.05, { rz: s * -0.08, cast: false });
    K.add(w.group, K.cyl(0.025, 0.025, r * 2 + 0.8, 6), rail, 0, winY + r + 0.12, z - 0.06, { rz: Math.PI / 2, cast: false });
  });
  // a few hanging things, high over your head
  if (c.hall) {
    // strings come down from the sloping ceiling to just over the walls' height
    for (let i = 0; i < 6; i++) {
      const z = i % 2 ? 1.6 : -0.6;
      const top = c.H + 0.1 + 3.6 * (1 - Math.abs(z) / (c.D / 2 + 1.1));
      hanging(world, c.group, th.hang, new THREE.Vector3(-5 + i * 2, 0, z), top, top - (c.H + 0.25 - (i % 3) * 0.15), th.door);
    }
  } else {
    const rr = c.R * 0.45;
    for (let i = 0; i < 5; i++) {
      const a = (i / 5) * Math.PI * 2 + 0.3;
      // from the cone of the ceiling above, down to a little under the walls' top
      const top = c.H + 0.05 + c.roofH * (1 - rr / (1.28 * c.R)) - 0.05;
      hanging(world, c.group, th.hang, new THREE.Vector3(Math.sin(a) * rr, 0, Math.cos(a) * rr), top, top - (c.H - 0.15 + (i % 2) * 0.2), i % 2 ? th.door : th.accent);
    }
  }
}

function emojiTex(emoji) {
  const t = tex(256, 256, () => {});
  t.wrapS = t.wrapT = THREE.ClampToEdgeWrapping;
  const g = t.image.getContext("2d");
  const draw = () => {
    g.fillStyle = "#fffaf6";
    g.fillRect(0, 0, 256, 256);
    g.textAlign = "center";
    g.textBaseline = "middle";
    g.font = '160px "Apple Color Emoji", "Noto Color Emoji", "Segoe UI Emoji", sans-serif';
    g.fillText(emoji, 128, 142);
    t.needsUpdate = true;
  };
  draw();
  document.fonts?.load('160px "Noto Color Emoji"', emoji).then(draw, () => {});
  return t;
}

// open double doors, a hanging shop sign, a step, potted flowers and fairy lights
function dressOutside(world, room, c, th) {
  const g = c.group;
  const front = c.front;
  const leafW = c.doorW / 2;
  const doorMat = K.std(th.door, { key: "ext" });
  const panel = K.std(K.shadeHex(th.door, 0.88), { key: "ext" });
  const rail = white();
  for (const s of [-1, 1]) {
    const hinge = new THREE.Group();
    hinge.position.set(s * leafW, 0, front + 0.02);
    hinge.rotation.y = s * 2.2;
    g.add(hinge);
    const leaf = new THREE.Group();
    leaf.position.x = (-s * leafW) / 2;
    hinge.add(leaf);
    K.add(leaf, K.box(leafW - 0.04, c.doorH - 0.06, 0.08), doorMat, 0, (c.doorH - 0.06) / 2, 0);
    for (const d of [-1, 1]) K.add(leaf, K.heartGeo(0.42), K.glow.warm, 0, c.doorH * 0.66, d * 0.05, { cast: false });
    K.add(leaf, K.box(leafW * 0.6, 0.5, 0.1), panel, 0, 0.55, 0);
    K.add(leaf, new THREE.SphereGeometry(0.05, 6, 5), gold(), s * (leafW / 2 - 0.12), c.doorH * 0.45, 0.07);
  }
  // a sill through the doorway, from the floor inside out to the step (no gap of grass)
  const inner = (c.hall ? c.D / 2 : c.apo) - 0.3;
  if (Number.isFinite(inner) && front > inner) K.add(g, K.box(c.doorW + 0.04, 0.06, front - inner + 0.02), rail, 0, 0.0, (inner + front) / 2 + 0.01, { cast: false });
  // the step up to the door
  K.add(g, K.box(c.doorW + 0.9, 0.1, 0.55), rail, 0, 0.05, front + 0.28, { cast: false });
  // and a welcome mat just past it (every building, however far its front sticks out)
  const trimCol = room.def.trim || "#e2557f";
  // (lifted clear of the walkway that runs under it, or the cobbles show through)
  K.add(g, K.box(1.6, 0.03, 0.9), K.std("#ffffff", { map: K.texture("fabric", [trimCol, "#fff3e8"]) }), 0, 0.06, front + 0.55 + 0.5, { cast: false });
  // a shop sign on a bracket by the door, with the room's emoji
  const sx = c.doorW / 2 + (c.box ? 1.3 : 0.8);
  const sy = c.doorH + 0.05;
  const iron = K.std("#5d4a5a", { key: "ext" });
  K.add(g, K.box(0.08, 0.08, 0.85), iron, sx, sy + 0.32, front + 0.42);
  const sign = new THREE.Group();
  sign.position.set(sx, sy - 0.12, front + 0.66);
  sign.rotation.y = Math.PI / 2;
  g.add(sign);
  K.add(sign, K.cyl(0.42, 0.42, 0.08, 20), K.std(th.accent, { key: "ext" }), 0, 0, 0, { rx: Math.PI / 2 });
  const face = new THREE.MeshStandardMaterial({ map: emojiTex(room.def.emoji), roughness: 0.8 });
  for (const d of [-1, 1]) K.add(sign, new THREE.CircleGeometry(0.34, 20), face, 0, 0, d * 0.045, { ry: d < 0 ? Math.PI : 0, cast: false });
  for (const d of [-1, 1]) K.add(sign, K.cyl(0.01, 0.01, 0.2, 4), iron, 0, 0.5, d * 0.12, { cast: false });
  world.animated.push((t) => (sign.rotation.x = Math.sin(t * 1.3 + sx) * 0.06));
  // flowers in pots either side of the step
  const potMat = K.std(th.pot, { key: "ext" });
  const cols = ["#ff8fb1", "#ffd166", "#c7b0f5", "#fffafc"].map((col) => K.std(col, { key: "ext" }));
  const bushMat = K.std("#8fd3a0", { key: "ext" });
  for (const s of [-1, 1]) {
    const px = s * (c.doorW / 2 + 0.6 + (c.box ? 0.2 : 0));
    const pz = front + 0.5;
    K.add(g, K.cyl(0.26, 0.19, 0.42, 10), potMat, px, 0.21, pz);
    K.add(g, K.cyl(0.29, 0.29, 0.07, 10), rail, px, 0.43, pz);
    const bush = K.add(g, new THREE.IcosahedronGeometry(0.32, 1), bushMat, px, 0.66, pz);
    bush.scale.y = 0.85;
    for (let i = 0; i < 6; i++) {
      const a = i * 1.05 + s;
      K.add(g, new THREE.IcosahedronGeometry(0.065, 0), cols[i % 4], px + Math.sin(a) * 0.26, 0.72 + (i % 2) * 0.1, pz + Math.cos(a) * 0.24, { cast: false });
    }
  }
  // fairy lights under the edge of the roof
  const ring = [];
  if (c.box || c.hall) {
    const hx = c.box ? c.boxHx : c.W / 2 + 0.75;
    const hz = c.box ? c.boxHz : c.D / 2 + 0.75;
    const y = c.box ? c.lidY - 0.02 : c.H + 0.05;
    const corners = [[-hx, hz], [hx, hz], [hx, -hz], [-hx, -hz]];
    for (let i = 0; i < 4; i++) {
      const [a, b] = [corners[i], corners[(i + 1) % 4]];
      ring.push([new THREE.Vector3(a[0], y, a[1]), new THREE.Vector3(b[0], y, b[1])]);
    }
  } else {
    const n = 12;
    const r = eave(c) - 0.1;
    for (let i = 0; i < n; i++) {
      const a0 = (i / n) * Math.PI * 2;
      const a1 = ((i + 1) / n) * Math.PI * 2;
      ring.push([new THREE.Vector3(Math.sin(a0) * r, c.H - 0.02, Math.cos(a0) * r), new THREE.Vector3(Math.sin(a1) * r, c.H - 0.02, Math.cos(a1) * r)]);
    }
  }
  const pts = [];
  const wire = K.std("#7a6070", { key: "ext" });
  for (const [a, b] of ring) {
    const n = Math.max(4, Math.round(a.distanceTo(b) / 0.5));
    const seg = [];
    for (let i = 0; i <= n; i++) {
      const t = i / n;
      const p = a.clone().lerp(b, t);
      p.y -= Math.sin(Math.PI * t) * 0.22;
      seg.push(p);
      if (i > 0 && i < n) pts.push(p.clone().setY(p.y - 0.06));
    }
    K.add(g, new THREE.TubeGeometry(new THREE.CatmullRomCurve3(seg), n * 2, 0.012, 4), wire, 0, 0, 0, { cast: false });
  }
  const bulbs = new THREE.InstancedMesh(new THREE.IcosahedronGeometry(0.065, 0), new THREE.MeshBasicMaterial({ color: "#ffffff" }), pts.length);
  const m4 = new THREE.Matrix4();
  const col = new THREE.Color();
  const pal = ["#ff8fb1", "#ffe07a", "#c7b0f5", "#8fd3f0", "#fff3f8"];
  pts.forEach((p, i) => {
    bulbs.setMatrixAt(i, m4.makeTranslation(p.x, p.y, p.z));
    bulbs.setColorAt(i, col.set(pal[i % pal.length]));
  });
  g.add(bulbs);
}

export function dressBuilding(world, room, c, kit) {
  K = kit;
  c.front = c.hall ? c.D / 2 + c.thick / 2 + T : c.apo + c.thick / 2 + T;
  // how far the welcome mat reaches out from the middle: the walkway runs up to it
  room.doorReach = c.front + 1.5;
  (STYLES[room.def.id] || STYLES.song)(world, room, c);
  const th = THEMES[room.def.id] || THEMES.song;
  dressOutside(world, room, c, th);
  dressInside(world, room, c, th);
}
