  // ---- treats: hand one to your person, and watch whoever's eating take bites --------------
  // only known kinds and short plain values come in from the network
  function cleanTreat(t) {
    if (!t || typeof t !== "object" || !RECIPES[t.kind]) return null;
    const out = { kind: t.kind };
    for (const k of ["shape", "filling", "cup", "mix", "top", "frost", "fstyle", "bake", "by"]) if (typeof t[k] === "string") out[k] = t[k].slice(0, 24);
    if (typeof t.deco === "string") out.deco = t.deco.slice(0, 48);
    if (typeof t.msg === "string") out.msg = t.msg.slice(0, 12);
    out.stars = Math.max(1, Math.min(3, Number(t.stars) || 1));
    return out;
  }
  function giveTreat(treat, key) {
    const t = cleanTreat(treat);
    const r = net.remotes.get(key);
    if (!t || !r) return toast("they've wandered off… try again in a moment ♡");
    net.send("treat", { treat: t, from: myName() }, key);
    // hold it out to them for a moment
    startEating(avatar, t, true, null, true);
    audio.sfx("pop");
    toast(`you gave ${r.name || "your person"} your ${treatName(t)} 💝`);
  }
  function gotTreat(p, r) {
    const t = cleanTreat(p.treat);
    if (!t) return;
    const pic = h("canvas", { width: 240, height: 240, style: "width:120px;height:120px" });
    drawTreat(pic.getContext("2d"), t, 240);
    const save = () => {
      bakery.keep(t);
      toast("saved in the bakery's display case for later 🍰");
    };
    choiceCard(h, root, {
      pic,
      title: `${String(p.from || r?.name || "your person").slice(0, 24)} made you a ${treatName(t)}! ♡`,
      choices: [
        { icon: "😋", label: "eat it now", hint: "everyone sees you take the bites", go: () => eatMine(t) },
        !isGuest && { icon: "🍰", label: "save it for later", hint: "it goes in the bakery's display case", go: save },
      ],
      cancel: isGuest ? "maybe later" : null,
      onCancel: isGuest ? null : save, // tapped away: it's kept, never lost
    });
    audio.sfx("kiss");
    spawnHearts(player.pos, 6);
  }
  // you eat it: everyone sees you take the bites
  function eatMine(t) {
    t = cleanTreat(t);
    if (!t) return;
    net.send("eat", { treat: t });
    startEating(avatar, t, true, null);
  }
  // a treat held up by someone: three bites, crumbs, then a happy little heart burst
  const eaters = [];
  function startEating(av, t, mine, r, handOnly = false) {
    const old = eaters.findIndex((e) => e.av === av);
    if (old >= 0) {
      eaters[old].model.parent?.remove(eaters[old].model);
      eaters.splice(old, 1);
    }
    const model = makeTreat(t);
    model.scale.setScalar(1.5);
    av.root.add(model);
    eaters.push({ av, model, t, mine, r, time: 0, bites: 0, handOnly });
    if (!mine && r && !handOnly) toast(`${r.name || "your person"} is eating the ${treatName(t)} 😋`);
  }
  function updateEaters(dt) {
    for (let i = eaters.length - 1; i >= 0; i--) {
      const e = eaters[i];
      e.time += dt;
      const H = e.av.dims?.height || 1.6;
      // held out in front, then up to the mouth for each bite
      const end = e.handOnly ? 1.4 : 4.4;
      const phase = e.handOnly ? 0 : Math.max(0, Math.sin(Math.min(1, (e.time % 1.2) / 1.2) * Math.PI)) * (e.time > 0.6 ? 1 : 0);
      e.model.position.set(0.12, H * 0.58 + phase * H * 0.2, e.handOnly ? 0.55 : 0.36 - phase * 0.12);
      e.model.rotation.x = -0.4 + phase * 0.5;
      // your own treat is turned towards your camera (behind you), so any writing on it reads the right way
      if (e.mine && !e.handOnly) e.model.rotation.y = Math.PI;
      if (!e.handOnly) {
        const due = Math.min(3, Math.floor((e.time - 0.6) / 1.2) + 1);
        if (e.time > 1.1 && e.bites < due) {
          e.bites++;
          e.model.scale.multiplyScalar(0.72);
          const at = new THREE.Vector3();
          e.model.getWorldPosition(at);
          fx.puff(at, "#e9b46f", "#fff3e8");
          audio.sfx("chomp");
        }
      }
      if (e.time > end) {
        e.model.parent?.remove(e.model);
        eaters.splice(i, 1);
        if (!e.handOnly) {
          const at = new THREE.Vector3();
          e.av.root.getWorldPosition(at);
          spawnHearts(at, e.mine ? 8 : 5);
          if (e.mine) {
            toast(`mmm… ${treatName(e.t)} ${e.t.stars >= 3 ? "tastes like heaven 😋" : "yummy 😋"}`);
            audio.sfx("kiss");
          }
        }
      }
    }
  }

  // messages of every other kind
  function onNetX(p, r) {
    if (r?.guest && p.t !== "chat" && p.t !== "voice" && p.t !== "petpet" && p.t !== "ball" && p.t !== "race" && p.t !== "mole" && p.t !== "coaster" && p.t !== "eat") return;
    if (p.t === "bakery") {
      bakery.remote(p.s);
      return;
    }
    if (p.t === "garden") {
      garden.remote(p.s);
      return;
    }
    if (p.t === "pantry") {
      pantry.remote(p.s);
      return;
    }
    if (p.t === "bouquet") {
      bouquets.received(p, r);
      return;
    }
    if (p.t === "treat") {
      gotTreat(p, r);
      return;
    }
    // our paintings and the gallery wall, for a visitor
    if (p.t === "art") {
      if (!isGuest || r?.guest) return;
      if (p.hang) addToGallery(p.hang);
      else drawImageSrc(p.c === 1 ? 1 : 0, p.src);
      return;
    }
    // what the screens show, for visitors
    if (p.t === "view") {
      if (!isGuest || r?.guest) return;
      if (p.screens && typeof p.screens === "object") relayed = p.screens;
      if (Array.isArray(p.watch)) watchlist.setRelayed(p.watch);
      if (typeof p.bakery === "string" && p.bakery.length < 60000) bakery.showAs(p.bakery);
      if (typeof p.garden === "string") garden.remote(p.garden);
      return;
    }
    if (p.t === "eat") {
      const t = cleanTreat(p.treat);
      if (t && r) startEating(r.avatar, t, false, r);
      return;
    }
    if (p.t === "coaster") {
      coaster.onRemote(p);
      return;
    }
    if (p.t === "race") {
      race.onRemote(p, r?.name || "your person");
      return;
    }
    if (p.t === "ball") {
      games.onRemoteBall(p, p.key, net.myKey);
      return;
    }
    if (p.t === "mole") {
      games.onRemoteMole(p, r?.name || "your person");
      return;
    }
    if (p.t === "petpet") {
      // they pet your pet
      const c = creatures.pets?.[p.i];
      if (!c || !r) return;
      creatures.greet(c, r);
      spawnHearts(c.pos, 4);
      const sp = c.species || c.kind;
      if (c.pos.distanceTo(player.pos) < 20) audio.sfx(sp === "cat" ? "purr" : sp === "bunny" ? "squeak" : "pop");
      toast(`${r.name || "your person"} pet ${c.petName || `your ${sp === "cat" ? "kitty" : sp}`} ♡`);
    } else if (p.t === "chat" || p.t === "voice") social.onRemote(p, r);
    else if (p.t === "photo" || p.t === "unphoto" || p.t === "pose" || p.t === "timer" || p.t === "tripod" || p.t === "tsnap") album.onRemote(p, r?.name);
    else if (p.t === "tree") {
      if (p.add && willow.merge([p.add])) toast(`${r?.name || "your person"} decorated our willow ✿`);
      if (p.del) willow.remove(p.del);
      if (p.all) willow.merge(p.all);
      if (!decorate.hidden) buildDecorate();
    } else if (p.t === "shot" && r) {
      fx.remoteShot(new THREE.Vector3(...p.a), new THREE.Vector3(...p.b));
      if (r.pos.distanceTo(player.pos) < 60) audio.sfx("shot");
    } else if (p.t === "tokens" && !isGuest) mergeTokens(p.list || [], p.revoked || []);
    else if (p.t === "kick" && !isGuest) {
      if (p.revoked?.length) mergeTokens([], p.revoked);
    }
  }
  // when your person arrives: share what they might have missed
