// One clear card for "you've got something: what now?" (flowers you picked, a full vase,
// a treat someone made you). Big buttons, each saying exactly what will happen, and a
// way out. Only one is open at a time; Esc or a tap outside closes it.
let open = null;

export function choiceCard(h, root, { pic, title, note, choices, cancel = "not now", onCancel }) {
  closeChoice();
  const done = () => {
    card.remove();
    if (open === card) open = null;
  };
  const card = h("div", { class: "g3d-overlay g3d-gift g3d-choice" },
    h("div", { class: "g3d-sheet g3d-gift-card" },
      pic || null,
      h("p", { class: "g3d-gift-from" }, title),
      note ? h("p", { class: "g3d-gd-note" }, note) : null,
      ...choices.filter(Boolean).map((c, i) =>
        h("button", { type: "button", class: `g3d-big-btn g3d-choice-btn${i ? " g3d-big-btn-soft" : ""}`, onclick: () => {
          done();
          c.go();
        } },
          h("span", { class: "g3d-choice-icon", "aria-hidden": "true" }, c.icon || "♡"),
          h("span", { class: "g3d-choice-text" }, h("b", {}, c.label), c.hint ? h("small", {}, c.hint) : null),
        ),
      ),
      cancel ? h("button", { type: "button", class: "g3d-gd-dig", onclick: () => {
        done();
        onCancel?.();
      } }, cancel) : null,
    ),
  );
  card.cancel = () => {
    done();
    onCancel?.();
  };
  card.addEventListener("pointerdown", (e) => e.target === card && card.cancel());
  root.append(card);
  open = card;
  return card;
}
export const choiceOpen = () => Boolean(open?.isConnected);
export function closeChoice() {
  open?.cancel();
}
