// Flowers picked in the garden make a bouquet: give it to your person (it pops up on
// their screen and they carry it), or carry it yourself to one of the vases dotted round
// the island and leave it there. What's in the vases is shared (shared.js), so we both
// see the flowers the other one left.
import * as THREE from "three";
import { std, ISLAND_R } from "./world.js";
import { getShared, setShared, onShared } from "./shared.js";
import { choiceCard } from "./choice.js";
import { flowerInfo } from "./garden.js";

export const VASES_KEY = "tdd3d.vases";
// the flower shelf (loose flowers, by kind and colour) and dodo's stall, shared by us both
export const FLOWERS_KEY = "tdd3d.flowers";
const MAX_STEMS = 12; // flowers in one bouquet
const STALL_MAX = 6; // bouquets on the stall at once
const WRAPS = ["#fff3f6", "#ffd1e1", "#e8dcff", "#d9f2e6", "#fff0c9"];
// the paper round a bouquet: a cone, open at the top
const WRAP_GEO = new THREE.ConeGeometry(0.14, 0.3, 10, 1, true).rotateX(Math.PI);
// what a bouquet sells for: more flowers, more coins; golden ones are worth a lot
const price = (cols) => 4 + cols.length * 2 + cols.filter((c) => c.toLowerCase() === "#ffd23f").length * 5;
function readFlowers(raw) {
  let d = null;
  try {
    d = JSON.parse(raw || "null");
  } catch {}
  const out = { stems: {}, stall: [], sold: 0, coins: 0 };
  if (!d || typeof d !== "object") return out;
  if (d.stems && typeof d.stems === "object") {
    for (const [k, n] of Object.entries(d.stems)) {
      if (/^[a-z]{0,20}\|#[0-9a-f]{6}$/i.test(k) && n > 0) out.stems[k] = Math.min(999, Math.floor(n));
    }
  }
  if (Array.isArray(d.stall)) out.stall = d.stall.map((b) => b && { cols: clean(b.cols), w: Math.max(0, Math.min(WRAPS.length - 1, Number(b.w) || 0)), by: String(b.by || "").slice(0, 24) }).filter((b) => b?.cols.length).slice(0, STALL_MAX);
  out.sold = Math.max(0, Number(d.sold) || 0);
  out.coins = Math.max(0, Number(d.coins) || 0);
  return out;
}
// near these places, just off the path
const NEAR = ["plaza", "gate", "cinema", "chill", "discord", "heart", "lake", "wishlist", "farm"];
// and one inside every room, on a little table by the door (placed once the room's inside is built)
const INSIDE = ["diary", "song", "note", "photos", "calendar", "poems", "gift", "wardrobe", "art", "bakery"];
// and the one on our café table in the garden (garden.js says where)
const GARDEN = NEAR.length + INSIDE.length;
const ALL = GARDEN + 1;
const VASE_COLS = ["#ffd6e4", "#d6ecff", "#fff1c2", "#e4dcff", "#d8f5e4", "#ffe0cc"];
const clean = (cols) => (Array.isArray(cols) ? cols.filter((c) => typeof c === "string" && /^#[0-9a-f]{6}$/i.test(c)).slice(0, 12) : []);

// the bouquet as a picture (cols are already checked #rrggbb colours)
const shade = (hex, k) => {
  const n = parseInt(hex.slice(1), 16);
  const f = (v) => Math.round(Math.max(0, Math.min(255, k < 0 ? v * (1 + k) : v + (255 - v) * k))).toString(16).padStart(2, "0");
  return `#${f(n >> 16)}${f((n >> 8) & 255)}${f(n & 255)}`;
};
const svgSpan = (h, cls, svg) => {
  const el = h("span", { class: cls });
  el.innerHTML = svg;
  return el;
};
function bouquetSvg(cols, wrap = "#fff4f8") {
  const fold = shade(wrap, -0.06), edge = shade(wrap, -0.2);
  if (!cols.length) cols = ["#ffb3cf"];
  const n = cols.length;
  const base = [80, 132]; // where the stems gather, inside the wrap
  // two rows on a fan: the back row higher and wider, the front row lower
  const spots = cols.map((c, i) => {
    const back = n > 4 && i % 2 === 0;
    const row = back ? Math.ceil(n / 2) : n > 4 ? Math.floor(n / 2) : n;
    const j = n > 4 ? Math.floor(i / 2) : i;

    const t = row > 1 ? j / (row - 1) - 0.5 : 0;
    const a = t * (back ? 1.5 : 1.15);
    const r = back ? 74 : n > 4 ? 56 : 64;
    return { c, x: base[0] + Math.sin(a) * r, y: base[1] - Math.cos(a) * r, a, s: back ? 11 : 12.5, back };
  });
  const order = [...spots.filter((s) => s.back), ...spots.filter((s) => !s.back)];
  let stems = "", leaves = "", heads = "";
  order.forEach((s, k) => {
    stems += `<path d="M${base[0]} ${base[1]} Q${(base[0] + s.x) / 2 + s.a * 6} ${(base[1] + s.y) / 2 + 8} ${s.x.toFixed(1)} ${s.y.toFixed(1)}" stroke="#5fae5a" stroke-width="2.6" fill="none" stroke-linecap="round"/>`;
    if (k % 2 === 0) {
      const lx = (base[0] + s.x) / 2, ly = (base[1] + s.y) / 2 + 6, side = s.a < 0 ? -1 : 1;
      leaves += `<ellipse cx="${(lx + side * 6).toFixed(1)}" cy="${ly.toFixed(1)}" rx="9" ry="4" fill="${k % 4 ? "#7fc07a" : "#6fb46a"}" transform="rotate(${(side * 35 + s.a * 40).toFixed(0)} ${(lx + side * 6).toFixed(1)} ${ly.toFixed(1)})"/>`;
    }
    const petals = [0, 1, 2, 3, 4].map((p) => `<ellipse cx="0" cy="${(-s.s * 0.62).toFixed(1)}" rx="${(s.s * 0.5).toFixed(1)}" ry="${(s.s * 0.68).toFixed(1)}" transform="rotate(${p * 72})"/>`).join("");
    heads += `<g transform="translate(${s.x.toFixed(1)} ${s.y.toFixed(1)}) rotate(${(s.a * 50 + k * 13).toFixed(0)})"><g fill="${s.c}" stroke="${shade(s.c, -0.18)}" stroke-width="1">${petals}</g><circle r="${(s.s * 0.36).toFixed(1)}" fill="${shade(s.c, 0.55)}"/><circle r="${(s.s * 0.17).toFixed(1)}" fill="#ffd166"/></g>`;
  });
  return `<svg viewBox="0 0 160 170" width="150" height="160" aria-hidden="true">
<ellipse cx="80" cy="162" rx="40" ry="5" fill="rgba(0,0,0,0.12)"/>
${stems}${leaves}
<path d="M48 112 L80 162 L112 112 Q80 122 48 112Z" fill="${wrap}" stroke="${edge}" stroke-width="1.5"/>
<path d="M58 113 L80 158 L68 114Z" fill="${fold}"/>
${heads}
<path d="M46 110 Q80 124 114 110 L108 120 Q80 132 52 120Z" fill="${wrap}" stroke="${edge}" stroke-width="1.5"/>
<g fill="#ff8fb1" stroke="#e2557f" stroke-width="1.2"><path d="M80 134 Q62 122 64 138 Q70 144 80 136Z"/><path d="M80 134 Q98 122 96 138 Q90 144 80 136Z"/><path d="M79 136 L70 154 L76 152 L80 158 Z"/><path d="M81 136 L90 154 L84 152 L80 158 Z"/></g>
<circle cx="80" cy="135" r="3.6" fill="#e2557f"/>
</svg>`;
}


// a bunch of flowers: stems fanned out, a round head on each, a ribbon round the middle
const STEM = new THREE.CylinderGeometry(0.008, 0.01, 1, 4).translate(0, 0.5, 0);
const HEAD = new THREE.IcosahedronGeometry(1, 0);
const LEAF = new THREE.SphereGeometry(1, 5, 3);
export function makeBunch(cols, size = 1, ribbon = true) {
  const g = new THREE.Group();
  const stem = std("#5fae5a");
  const n = cols.length;
  cols.forEach((c, i) => {
    const a = (i / n) * Math.PI * 2 + i * 0.7;
    const lean = n === 1 ? 0 : 0.18 + (i % 3) * 0.08;
    const len = (0.32 + ((i * 37) % 10) / 80) * size;
    const s = new THREE.Mesh(STEM, stem);
    s.scale.set(size, len, size);
    s.rotation.set(Math.cos(a) * lean, 0, Math.sin(a) * lean);
    g.add(s);
    const top = new THREE.Vector3(0, len, 0).applyEuler(s.rotation);
    const head = new THREE.Mesh(HEAD, std(c));
    head.position.copy(top);
    head.scale.set(0.05 * size, 0.035 * size, 0.05 * size);
    head.rotation.set(s.rotation.x, a, s.rotation.z);
    g.add(head);
    const eye = new THREE.Mesh(HEAD, std("#ffe28a"));
    eye.position.copy(top).add(new THREE.Vector3(0, 0.02 * size, 0));
    eye.scale.setScalar(0.017 * size);
    g.add(eye);
    if (i % 2 === 0) {
      const leaf = new THREE.Mesh(LEAF, stem);
      leaf.position.copy(top).multiplyScalar(0.45);
      leaf.scale.set(0.035 * size, 0.012 * size, 0.07 * size);
      leaf.rotation.y = a;
      g.add(leaf);
    }
  });
  if (ribbon) {
    const r = new THREE.Mesh(new THREE.TorusGeometry(0.035 * size, 0.012 * size, 4, 10), std("#ff8fb1"));
    r.rotation.x = Math.PI / 2;
    r.position.y = 0.1 * size;
    g.add(r);
  }
  return g;
}

export class Bouquets {
  constructor({ world, h, toast, audio, isGuest, net, myName, people, avatar, hearts, confetti, root, onOpen, onClose }) {
    Object.assign(this, { world, h, toast, audio, isGuest, net, myName, people, avatar, hearts, confetti, root, onOpen, onClose });
    this.carry = null; // the colours of the bouquet you're holding
    this.held = null;
    this.vases = [];
    this.kept = [];
    this.state = this.read();
    this.flowers = readFlowers(getShared(FLOWERS_KEY));
    // the bunches kept on the shelf before it held loose flowers: onto the shelf they go
    if (this.kept.length && !this.isGuest) {
      for (const k of this.kept) this.addStems(k.cols.map((c) => ["", c]), false);
      this.kept = [];
      this.save();
      this.saveFlowers();
    }
    this.placeVases();
    this.draw();
    this.drawStall();
    onShared((key, value) => {
      if (key === VASES_KEY) {
        this.state = this.read(value);
        this.draw();
      } else if (key === FLOWERS_KEY) this.applyFlowers(value);
    });
    this.chip = h("button", { class: "g3d-chip g3d-carry", type: "button", hidden: true, title: "put the flowers on the shelf", onclick: () => this.drop() }, "💐 holding flowers · walk to a vase and press E · ✕");
    root.append(this.chip);
    // the flower shelf and the stall share one sheet
    this.body = h("div", { class: "g3d-help-body g3d-fl-body" });
    this.title = h("h2", { class: "g3d-sheet-title" }, "our flower shelf");
    this.el = h("div", { class: "g3d-overlay g3d-fl", hidden: true, role: "dialog", "aria-label": "flowers" },
      h("div", { class: "g3d-sheet" },
        h("header", { class: "g3d-panel-head" }, this.title, h("button", { class: "g3d-close", type: "button", "aria-label": "close", onclick: () => this.close() }, "✕")),
        this.body,
      ),
    );
    this.el.addEventListener("pointerdown", (e) => e.target === this.el && this.close());
    document.body.append(this.el);
    this.customers = [];
    this.nextCustomer = 6 + Math.random() * 4;
  }
  read(raw = getShared(VASES_KEY)) {
    let d = null;
    try {
      d = JSON.parse(raw || "null");
    } catch {}
    const out = [];
    for (let i = 0; i < ALL; i++) {
      const v = Array.isArray(d) ? d[i] : null;
      out.push(v && typeof v === "object" ? { cols: clean(v.cols), by: String(v.by || "").slice(0, 24), at: Number(v.at) || 0 } : null);
    }
    // bunches kept on the shelf by an older version (they become loose flowers on it)
    const shelf = Array.isArray(d) && Array.isArray(d[ALL]?.shelf) ? d[ALL].shelf : [];
    this.kept = shelf.map((v) => v && { cols: clean(v.cols) }).filter((v) => v?.cols.length);
    return out;
  }
  save() {
    const s = JSON.stringify(this.state);
    if (!this.isGuest) setShared(VASES_KEY, s);
    this.net.send("bouquet", { vases: s });
  }
  // ---- the flower shelf: every flower we kept, by kind and colour, and dodo's stall --------
  saveFlowers() {
    const s = JSON.stringify(this.flowers);
    if (!this.isGuest) setShared(FLOWERS_KEY, s);
    this.net.send("bouquet", { flowers: s });
  }
  applyFlowers(json) {
    this.flowers = readFlowers(json);
    this.drawStall();
    if (!this.el.hidden) this.render();
  }
  stemTotal() {
    return Object.values(this.flowers.stems).reduce((a, b) => a + b, 0);
  }
  addStems(list, save = true) {
    for (const [k, c] of list) {
      if (!/^#[0-9a-f]{6}$/i.test(c)) continue;
      const key = `${k || ""}|${c.toLowerCase()}`;
      this.flowers.stems[key] = Math.min(999, (this.flowers.stems[key] || 0) + 1);
    }
    if (save) this.saveFlowers();
  }

  // a vase on a little stand by each place, somewhere free just off the path
  placeVases() {
    const w = this.world;
    NEAR.forEach((id, i) => {
      const room = w.rooms.get(id);
      if (!room) return;
      const c = room.def.pos;
      const len = Math.hypot(c.x, c.z) || 1;
      const base = Math.atan2(-c.x / len, -c.z / len); // towards the middle
      const r0 = (room.def.clear || 4) + 1.4;
      let at = null;
      for (let k = 0; k < 40 && !at; k++) {
        const a = base + (k % 2 ? 1 : -1) * (0.5 + Math.floor(k / 2) * 0.22);
        const r = r0 + (k % 3) * 0.6;
        const x = c.x + Math.sin(a) * r, z = c.z + Math.cos(a) * r;
        if (Math.hypot(x, z) > ISLAND_R - 5) continue;
        if (w.isFree(x, z, 0.9)) at = [x, z];
      }
      if (!at) return;
      this.makeVase(i, at[0], at[1], Math.atan2(-at[0], -at[1]), "outdoor");
    });
    const gv = w.gardenVase;
    if (gv) this.makeVase(GARDEN, gv.x, gv.z, gv.ry, "table", gv.y);
    INSIDE.forEach((id, k) => {
      const room = w.rooms.get(id);
      if (!room) return;
      const i = NEAR.length + k;
      if (room.interiorBuilt || !room.buildInterior) return this.vaseInside(room, i);
      const build = room.buildInterior;
      room.buildInterior = (...args) => {
        const out = build(...args);
        this.vaseInside(room, i);
        return out;
      };
    });
  }
  // a spot just inside, beside the doorway, clear of the walls and the furniture
  vaseInside(room, i) {
    const w = this.world;
    if (this.vases[i]) return;
    room.group.updateMatrixWorld(true);
    // a room can say where its vase goes (the bakery: on a café table)
    if (room.vaseSpot) {
      const p = room.group.localToWorld(new THREE.Vector3(room.vaseSpot.x, 0, room.vaseSpot.z));
      return this.makeVase(i, p.x, p.z, room.group.rotation.y + Math.PI, "table", room.vaseSpot.y);
    }
    const inv = room.group.matrixWorld.clone().invert();
    // the front wall: the room's walls furthest towards its door (local +z)
    let front = -Infinity;
    for (const sg of w.segments) {
      if (sg.room !== room.def.id) continue;
      const m = new THREE.Vector3((sg.ax + sg.bx) / 2, 0, (sg.az + sg.bz) / 2).applyMatrix4(inv);
      front = Math.max(front, m.z);
    }
    if (!Number.isFinite(front)) return;
    const clear = (x, z) => {
      for (const sg of w.segments) {
        const dx = sg.bx - sg.ax, dz = sg.bz - sg.az;
        const L = dx * dx + dz * dz || 1;
        const t = Math.max(0, Math.min(1, ((x - sg.ax) * dx + (z - sg.az) * dz) / L));
        if (Math.hypot(x - sg.ax - dx * t, z - sg.az - dz * t) < 0.6) return false;
      }
      for (const c of w.circles) if (Math.hypot(x - c.x, z - c.z) < c.r + 0.5) return false;
      return true;
    };
    for (const [lx, back] of [[1.9, 0.8], [-1.9, 0.8], [2.5, 1.1], [-2.5, 1.1], [1.6, 1.4], [-1.6, 1.4], [3.0, 1.6], [-3.0, 1.6], [2.2, 2.4], [-2.2, 2.4], [3.2, 2.6], [-3.2, 2.6], [3.4, 3.4], [-3.4, 3.4], [2.6, 3.8], [-2.6, 3.8]]) {
      const p = room.group.localToWorld(new THREE.Vector3(lx, 0, front - back));
      if (!clear(p.x, p.z)) continue;
      return this.makeVase(i, p.x, p.z, room.group.rotation.y + Math.PI, "indoor");
    }
  }
  // stand: "outdoor" (a stone pedestal), "indoor" (a little side table) or "table" (just
  // the vase, on a table that's already there, its top at height y)
  makeVase(i, x, z, ry, stand = "outdoor", y = 0) {
    const indoor = stand !== "outdoor";
    const w = this.world;
    const g = new THREE.Group();
    g.position.set(x, 0, z);
    g.rotation.y = ry;
    const parts = [];
    if (stand === "indoor") {
      // a little round side table
      const wood = std("#c9a27e");
      const leg = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.07, 0.66, 8), std("#8a6a4f"));
      leg.position.y = 0.33;
      const top = new THREE.Mesh(new THREE.CylinderGeometry(0.34, 0.34, 0.05, 16), wood);
      top.position.y = 0.68;
      const foot = new THREE.Mesh(new THREE.CylinderGeometry(0.22, 0.24, 0.04, 14), std("#8a6a4f"));
      foot.position.y = 0.02;
      const cloth = new THREE.Mesh(new THREE.CylinderGeometry(0.36, 0.4, 0.12, 16, 1, true), std("#fff3f6", { side: THREE.DoubleSide }));
      cloth.position.y = 0.64;
      parts.push(leg, top, foot, cloth);
    } else if (stand === "outdoor") {
      const stone = std("#f4ece6");
      const ped = new THREE.Mesh(new THREE.CylinderGeometry(0.28, 0.34, 0.7, 8), stone);
      ped.position.y = 0.35;
      const top = new THREE.Mesh(new THREE.CylinderGeometry(0.36, 0.36, 0.08, 8), stone);
      top.position.y = 0.74;
      parts.push(ped, top);
    }
    const base = stand === "table" ? y : indoor ? 0.71 : 0.78;
    const pts = [[0.001, 0], [0.14, 0.02], [0.2, 0.12], [0.17, 0.26], [0.09, 0.36], [0.11, 0.42], [0.14, 0.44]].map(([px, py]) => new THREE.Vector2(px, py));
    const vase = new THREE.Mesh(new THREE.LatheGeometry(pts, 12), std(VASE_COLS[i % VASE_COLS.length], { flatShading: false, roughness: 0.4, side: THREE.DoubleSide }));
    vase.position.y = base;
    if (indoor) vase.scale.setScalar(0.85);
    parts.push(vase);
    for (const m of parts) {
      m.castShadow = true;
      m.receiveShadow = true;
      g.add(m);
    }
    const flowers = new THREE.Group();
    flowers.position.y = base + (indoor ? 0.26 : 0.3);
    if (indoor) flowers.scale.setScalar(0.85);
    g.add(flowers);
    w.root.add(g);
    if (stand !== "table") w.addCircle(x, z, 0.45);
    const it = { id: `vase-${i}`, icon: "", pos: new THREE.Vector3(x, 0, z), radius: stand === "table" ? 1.9 : 1.4, action: { type: "vase", i }, room: "", hits: [g] };
    Object.defineProperty(it, "label", { enumerable: true, get: () => {
      const full = this.state[i]?.cols.length;
      if (this.carry) return full ? "swap the flowers in the vase 💐" : "put your flowers in the vase 💐";
      return full ? `flowers from ${this.state[i].by || "us"} ♡` : "an empty vase 🏺";
    } });
    g.traverse((o) => (o.userData.item = it));
    w.interactables.push(it);
    this.vases[i] = { g, flowers };
    this.draw();
  }
  draw() {
    this.vases.forEach((v, i) => {
      if (!v) return;
      v.flowers.clear();
      const s = this.state[i];
      if (s?.cols.length) v.flowers.add(makeBunch(s.cols, 1.3, false));
    });
  }

  // a little picture of the bunch, for the cards
  // a little drawing of the bunch for the cards: a flower in each colour fanned out over
  // stems and leaves, wrapped in a paper cone with a ribbon bow
  pic(cols) {
    const el = svgSpan(this.h, "g3d-bq-pic", bouquetSvg(clean(cols)));
    el.setAttribute("role", "img");
    el.setAttribute("aria-label", "the bouquet");
    return el;
  }

  ago(at) {
    if (!at) return "";
    const d = Math.round((Date.now() - at) / 86400000);
    return d < 1 ? "today" : d === 1 ? "yesterday" : `${d} days ago`;
  }

  // fresh from the garden: what shall we do with them?
  offer(cols, names, stems = []) {
    cols = clean(cols);
    if (!cols.length) return;
    const people = this.people().filter((p) => !p.guest);
    const what = names.length === 1 ? names[0] : "flowers";
    const garden = this.vases[GARDEN] ? GARDEN : -1;
    const loose = stems.length ? stems : cols.map((c) => ["", c]);
    choiceCard(this.h, this.root, {
      pic: this.pic(cols),
      title: `you picked ${what} 💐`,
      note: "what would you like to do with them?",
      choices: [
        { icon: "🫙", label: "put them on our flower shelf", hint: "make bouquets from them any time, or sell them at dodo's stall", go: () => this.keep(loose) },
        ...people.map((p) => ({ icon: "💝", label: `give them to ${p.name || "my person"}`, hint: "they'll pop straight into their hands", go: () => this.give(cols, p.key, p.name) })),
        garden >= 0 && { icon: "🌷", label: "put them in our table vase", hint: this.state[garden]?.cols.length ? "the flowers in it now make way" : "right here in the garden", go: () => this.fill(garden, cols) },
        { icon: "🏺", label: "carry them to a vase", hint: "any vase round the island · walk up to it and press E", go: () => {
          this.hold(cols);
          this.toast("💐 you're holding the flowers · walk up to any vase and press E");
        } },
      ],
      cancel: "later · put them on the shelf",
      onCancel: () => this.keep(loose),
    });
    this.audio.sfx("open");
  }
  give(cols, key, name) {
    if (!this.net.remotes.get(key)) return this.toast("they've wandered off… you're holding the flowers now ♡"), this.hold(cols);
    this.net.send("bouquet", { cols, from: this.myName() }, key);
    this.audio.sfx("kiss");
    this.hearts?.(4);
    this.toast(`you gave ${name || "your person"} the flowers 💐💝`);
    if (this.carry === cols) this.drop(true);
  }
  // from your person: a bouquet just for you (or the vases or the shelf changed)
  received(p, r) {
    if (typeof p.vases === "string" && p.vases.length < 4000) {
      this.state = this.read(p.vases);
      this.draw();
      return;
    }
    if (typeof p.flowers === "string" && p.flowers.length < 20000) return this.applyFlowers(p.flowers);
    if (p.sold) {
      this.toast(`🌸 someone bought a bouquet at dodo's stall · +${Number(p.sold) || 0} 🪙`);
      return;
    }
    const cols = clean(p.cols);
    if (!cols.length) return;
    const from = String(p.from || r?.name || "your person").slice(0, 24);
    this.audio.sfx("kiss");
    this.hearts?.(8);
    const garden = this.vases[GARDEN] ? GARDEN : -1;
    choiceCard(this.h, this.root, {
      pic: this.pic(cols),
      title: `${from} gave you flowers 💐`,
      choices: [
        { icon: "💐", label: "hold them", hint: "carry them round · put them in any vase with E", go: () => this.hold(cols) },
        garden >= 0 && { icon: "🌷", label: "put them in our table vase", hint: "in the garden, for both of us", go: () => this.fill(garden, cols) },
        { icon: "🫙", label: "put them on our flower shelf", hint: "for a bouquet later", go: () => this.keep(cols.map((c) => ["", c])) },
      ],
      cancel: "thank you ♡",
      onCancel: () => this.hold(cols), // they're yours: in your hands until you decide
    });
  }
  hold(cols) {
    this.drop(true);
    this.carry = cols;
    const av = this.avatar();
    if (av?.root) {
      this.held = makeBunch(cols, 1.1);
      const H = av.dims?.height || 1.6;
      this.held.position.set(0.28, H * 0.42, 0.22);
      this.held.rotation.set(0.35, 0, -0.25);
      av.root.add(this.held);
    }
    this.chip.hidden = false;
  }
  // loose flowers onto the shelf in the garden ([kind, colour] each)
  keep(stems) {
    if (!stems.length) return;
    this.addStems(stems);
    this.toast(`🫙 on our flower shelf · ${this.stemTotal()} flowers there now`);
  }
  // ---- the sheet: the shelf (make a bouquet) and the stall (sell them) -----------------------
  isOpen() {
    return !this.el.hidden;
  }
  close() {
    if (this.el.hidden) return;
    this.el.hidden = true;
    this.onClose?.();
  }
  open(mode, book) {
    this.onOpen?.();
    this.mode = mode;
    this.book = book;
    this.pick = [];
    this.wrap = this.wrap || 0;
    this.render();
    this.el.hidden = false;
    this.audio.sfx("open");
  }
  shelf(book) {
    this.open("shelf", book);
  }
  stall() {
    if (this.isGuest) return this.toast("🌸 dodo's flower stall · bouquets made from our garden");
    this.open("stall");
  }
  render() {
    const h = this.h;
    const stall = this.mode === "stall";
    const F = this.flowers;
    this.title.textContent = stall ? "🌸 dodo's flower stall" : "🫙 our flower shelf";
    const left = (key) => (F.stems[key] || 0) - this.pick.filter((p) => p === key).length;
    // what each one is (a flower kept without its kind is known by its colour), and its picture
    const infoOf = (key) => flowerInfo(...key.split("|"));
    const keys = Object.keys(F.stems).filter((k) => F.stems[k] > 0).sort((a, b) => (infoOf(a)?.name || "~").localeCompare(infoOf(b)?.name || "~") || a.localeCompare(b));
    const colOf = (key) => key.split("|")[1];
    const redraw = () => this.render();
    // the bouquet being put together
    const tray = h("div", { class: "g3d-fl-tray" },
      this.pick.length
        ? this.pick.map((key, i) => {
          const info = infoOf(key);
          return h("button", { type: "button", class: "g3d-fl-stem", style: `--c:${colOf(key)}`, title: `${info?.name || "flower"} · tap to put it back`, onclick: () => {
            this.pick.splice(i, 1);
            redraw();
          } }, info?.pic ? h("img", { src: info.pic, alt: info.name }) : null);
        })
        : h("span", { class: "g3d-fl-hint" }, keys.length ? "tap flowers below to make a bouquet ♡" : "the shelf is empty · pick flowers in the garden and keep them here"),
    );
    const tools = h("div", { class: "g3d-fl-tools" },
      h("span", {}, `${this.pick.length}/${MAX_STEMS}`),
      keys.length ? h("button", { type: "button", class: "g3d-fl-mini", onclick: () => {
        // a pretty mix: a few of the colours there are most of, then some different ones
        this.pick = [];
        const pool = keys.flatMap((k) => Array(Math.min(3, F.stems[k])).fill(k)).sort(() => Math.random() - 0.5);
        for (const k of pool) if (this.pick.length < 7 && left(k) > 0) this.pick.push(k);
        redraw();
      } }, "✨ pick for me") : null,
      this.pick.length ? h("button", { type: "button", class: "g3d-fl-mini", onclick: () => {
        this.pick = [];
        redraw();
      } }, "clear") : null,
    );
    // every kind and colour on the shelf, with how many
    const grid = h("div", { class: "g3d-fl-grid" }, keys.map((key) => {
      const [k, c] = key.split("|");
      const info = infoOf(key);
      const n = left(key);
      return h("button", { type: "button", class: "g3d-fl-tile", disabled: n <= 0 || this.pick.length >= MAX_STEMS ? true : null, title: info?.name || "flowers", onclick: () => {
        this.pick.push(key);
        this.audio.sfx("pop");
        redraw();
      } },
        info?.pic ? h("img", { src: info.pic, alt: "" }) : h("span", { class: "g3d-fl-blob", style: `--c:${c}` }),
        h("span", { class: "g3d-fl-name" }, info?.name || "flowers"),
        h("b", {}, `×${n}`),
      );
    }));
    const cols = this.pick.map(colOf);
    const take = () => {
      for (const key of this.pick) F.stems[key] = Math.max(0, (F.stems[key] || 0) - 1);
      for (const key of Object.keys(F.stems)) if (!F.stems[key]) delete F.stems[key];
      this.pick = [];
      return cols;
    };
    const people = this.people().filter((p) => !p.guest);
    const garden = this.vases[GARDEN] ? GARDEN : -1;
    const act = (icon, label, go, soft) => h("button", { type: "button", class: `g3d-big-btn${soft ? " g3d-big-btn-soft" : ""}`, onclick: go }, `${icon} ${label}`);
    const done = (fn) => () => {
      const c = take();
      this.saveFlowers();
      this.close();
      fn(c);
    };
    const room = F.stall.length < STALL_MAX;
    const actions = !cols.length ? [] : stall
      ? [
        h("div", { class: "g3d-fl-wraps" }, h("span", {}, "wrap it in"), WRAPS.map((w, i) => h("button", { type: "button", class: `g3d-fl-wrap${this.wrap === i ? " on" : ""}`, style: `--c:${w}`, "aria-label": `wrap ${i + 1}`, onclick: () => {
          this.wrap = i;
          redraw();
        } }))),
        room
          ? act("🌸", `put it on the stall · sells for ${price(cols)} 🪙`, () => {
            const c = take();
            F.stall.push({ cols: c, w: this.wrap, by: this.myName() });
            this.saveFlowers();
            this.drawStall();
            this.audio.sfx("win");
            redraw();
          })
          : h("p", { class: "g3d-gd-note" }, `the stall is full (${STALL_MAX}) · wait for a customer ♡`),
      ]
      : [
        act("🤲", "carry it", done((c) => {
          this.hold(c);
          this.toast("💐 you're holding a bouquet · walk up to any vase and press E");
        })),
        ...people.map((p) => act("💝", `give it to ${p.name || "my person"}`, done((c) => this.give(c, p.key, p.name)), true)),
        garden >= 0 ? act("🌷", "put it in our table vase", done((c) => this.fill(garden, c)), true) : null,
      ];
    const top = stall
      ? h("div", { class: "g3d-fl-stall" },
        h("div", { class: "g3d-gd-stats" },
          h("span", {}, h("b", {}, String(F.stall.length)), "on the stall"),
          h("span", {}, h("b", {}, String(F.sold)), "sold"),
          h("span", {}, h("b", {}, String(F.coins)), "coins 🪙"),
          h("span", {}, h("b", {}, String(this.stemTotal())), "flowers"),
        ),
        F.stall.length
          ? h("div", { class: "g3d-fl-onstall" },
            h("p", { class: "g3d-fl-cap" }, "on the stall now · tap one to take it back"),
            h("div", { class: "g3d-fl-display" }, F.stall.map((b, i) => h("button", { type: "button", class: "g3d-fl-bq", title: "take it back off the stall", "aria-label": "bouquet on the stall: take it back", onclick: () => {
              F.stall.splice(i, 1);
              this.addStems(b.cols.map((c) => ["", c]));
              this.drawStall();
              redraw();
            } },
              svgSpan(h, "g3d-fl-bq-art", bouquetSvg(clean(b.cols), WRAPS[b.w] || WRAPS[0])),
              h("span", { class: "g3d-fl-bq-price" }, `${price(b.cols)} 🪙`),
            ))),
            h("p", { class: "g3d-gd-note" }, this.customers.length ? "🐰 a bunny is hopping over to buy one ♡" : "🐰 bunny customers hop by while you're near the stall ♡"))
          : h("p", { class: "g3d-gd-note" }, "the stall is bare · make a bouquet from our flower shelf below, and bunny customers will come by ♡"),
      )
      : h("div", { class: "g3d-gd-stats" },
        h("span", {}, h("b", {}, String(this.stemTotal())), "flowers"),
        h("span", {}, h("b", {}, String(keys.length)), "kinds & colours"),
        h("span", {}, h("b", {}, String(F.stall.length)), "on dodo's stall"),
      );
    this.body.replaceChildren(...[
      top,
      this.carry ? act("🫙", "put the ones you're holding on the shelf", () => {
        this.drop();
        redraw();
      }, true) : null,
      h("h3", { class: "g3d-gd-head" }, stall ? "make a bouquet to sell" : "make a bouquet"),
      // what it looks like so far, in the wrap you picked
      cols.length ? svgSpan(h, "g3d-bq-pic g3d-bq-preview", bouquetSvg(clean(cols), stall ? WRAPS[this.wrap] || WRAPS[0] : undefined)) : null,
      tray,
      tools,
      ...actions,
      grid,
      !stall && this.book ? act("📖", "the garden book", () => {
        this.close();
        this.book();
      }, true) : null,
    ].filter(Boolean));
  }
  // ---- the stall in the world: bouquets on the stand, and customers who come and buy -------
  drawStall() {
    const st = this.world.stall;
    if (!st) return;
    st.slots.forEach((slot, i) => {
      slot.clear();
      const b = this.flowers.stall[i];
      if (!b) return;
      const g = makeBunch(b.cols, 1.05);
      const paper = new THREE.Mesh(WRAP_GEO, std(WRAPS[b.w] || WRAPS[0], { side: THREE.DoubleSide, key: `wrap${b.w}` }));
      paper.position.y = 0.12;
      g.add(paper);
      slot.add(g);
    });
  }
  // only one of us runs the shop (whoever's key comes first), so nothing is sold twice
  seller() {
    if (this.isGuest) return false;
    const me = this.net.myKey || "";
    for (const r of this.net.remotes.values()) if (!r.guest && r.key < me) return false;
    return true;
  }
  update(dt, playerPos) {
    const st = this.world.stall;
    if (!st) return;
    for (const c of this.customers) c.tick(dt);
    this.customers = this.customers.filter((c) => !c.gone);
    if (!this.flowers.stall.length || this.customers.length || !this.seller()) {
      if (!this.flowers.stall.length) this.nextCustomer = Math.min(this.nextCustomer, 6 + Math.random() * 4); // the first comes soon after one goes out
      return;
    }
    if (Math.hypot(playerPos.x - st.front.x, playerPos.z - st.front.z) > 60) return;
    this.nextCustomer -= dt;
    if (this.nextCustomer > 0) return;
    this.nextCustomer = 12 + Math.random() * 14;
    this.customers.push(this.customer());
  }
  // a little bunny hops up, picks the bouquet nearest the front, pays, and hops away with it
  customer() {
    const st = this.world.stall;
    const g = new THREE.Group();
    const fur = std(["#fffaf6", "#e9d6c8", "#cfc3d8"][Math.floor(Math.random() * 3)]);
    const add = (geo, mat, x, y, z, sx = 1, sy = 1, sz = 1) => {
      const m = new THREE.Mesh(geo, mat);
      m.position.set(x, y, z);
      m.scale.set(sx, sy, sz);
      m.castShadow = true;
      g.add(m);
      return m;
    };
    const ball = new THREE.IcosahedronGeometry(1, 1);
    add(ball, fur, 0, 0.22, 0, 0.2, 0.18, 0.24);
    add(ball, fur, 0, 0.42, 0.12, 0.14, 0.13, 0.13);
    for (const s of [-1, 1]) add(ball, fur, s * 0.06, 0.62, 0.08, 0.035, 0.12, 0.025).rotation.z = s * 0.2;
    for (const s of [-1, 1]) add(ball, std("#2b2030"), s * 0.06, 0.45, 0.24, 0.018, 0.018, 0.018);
    add(ball, std("#ffb3c7"), 0, 0.41, 0.255, 0.02, 0.016, 0.016);
    add(ball, std("#ffffff"), 0, 0.22, -0.24, 0.07, 0.07, 0.07);
    const hand = new THREE.Group();
    hand.position.set(0.12, 0.3, 0.18);
    g.add(hand);
    g.scale.setScalar(1.6);
    this.world.root.add(g);
    const from = st.door.clone();
    const to = st.front.clone();
    const walk = Math.max(2.5, from.distanceTo(to) / 2.4); // hopping along at an even pace
    const stay = 2.2;
    let t = 0;
    let paid = false;
    const c = {
      gone: false,
      tick: (dt) => {
        t += dt;
        const go = t < walk ? t / walk : t < walk + stay ? 1 : 1 - (t - walk - stay) / walk;
        const p = from.clone().lerp(to, Math.max(0, Math.min(1, go)));
        const hopping = t < walk || t > walk + stay;
        g.position.set(p.x, Math.abs(Math.sin(t * 8)) * 0.16 * (hopping ? 1 : 0), p.z);
        const dir = t < walk + stay * 0.5 ? to.clone().sub(from) : from.clone().sub(to);
        g.rotation.y = Math.atan2(dir.x, dir.z);
        // popping in and out of sight far off, not right at the stall
        g.scale.setScalar(1.6 * Math.min(1, t / 0.4, Math.max(0, walk * 2 + stay - t) / 0.4));
        if (!paid && t >= walk + 0.6) {
          paid = true;
          const b = this.flowers.stall.shift();
          if (b) {
            const coins = price(b.cols);
            this.flowers.sold++;
            this.flowers.coins += coins;
            this.saveFlowers();
            this.drawStall();
            hand.add(makeBunch(b.cols, 0.8));
            this.audio.sfx("ding");
            this.toast(`🐰 a bunny bought a bouquet at dodo's stall · +${coins} 🪙`);
            this.net.send("bouquet", { sold: coins });
            if (!this.el.hidden) this.render();
          }
        }
        if (t > walk * 2 + stay) {
          c.gone = true;
          g.parent?.remove(g);
        }
      },
    };
    return c;
  }
  drop(quiet) {
    // tucked away, they go on the shelf rather than being lost
    if (!quiet && this.carry) {
      const cols = this.carry;
      this.drop(true);
      return this.keep(cols.map((c) => ["", c]));
    }
    this.held?.parent?.remove(this.held);
    this.held = null;
    this.carry = null;
    this.chip.hidden = true;
  }
  // put flowers in vase i (whatever was in it goes)
  fill(i, cols) {
    this.state[i] = { cols, by: this.myName(), at: Date.now() };
    if (this.carry === cols) this.drop(true);
    this.draw();
    this.save();
    this.audio.sfx("win");
    if (this.vases[i]) this.confetti?.(this.vases[i].g.position.clone().setY(1.3));
    this.toast("💐 so pretty ♡ they'll be here for both of us");
  }
  // walking up to a vase: put yours in, swap, or take what's there
  useVase(a) {
    const i = a.i;
    const s = this.state[i];
    const full = s?.cols.length ? s : null;
    const mine = this.carry;
    if (!full && !mine) return this.toast("an empty vase 🏺 pick flowers in the garden and bring them here");
    if (!full) return this.fill(i, mine);
    const left = `${full.by || "someone"} left these here${full.at ? ` ${this.ago(full.at)}` : ""} ♡`;
    choiceCard(this.h, this.root, {
      pic: this.pic(full.cols),
      title: left,
      choices: mine
        ? [
          { icon: "🔁", label: "swap them", hint: "yours go in, you take these with you", go: () => {
            const old = full.cols;
            this.fill(i, mine);
            this.hold(old);
          } },
          { icon: "💐", label: "put yours in", hint: "these ones make way", go: () => this.fill(i, mine) },
        ]
        : [
          { icon: "🤲", label: "take them with you", hint: "the vase is left empty · put them in another with E", go: () => {
            this.state[i] = null;
            this.draw();
            this.save();
            this.hold(full.cols);
            this.audio.sfx("pop");
          } },
        ],
      cancel: mine ? "keep holding mine" : "leave them be",
    });
  }
}
