// Our watchlist: a marquee sign by the cinema showing what we've posted in the
// Discord "what to watch" channel (poster, title, overview). The posts arrive in
// the watchlist table (supabase/functions/watchlist-sync) and show up here live,
// no refresh. Walking up to the sign also asks for a fresh read of the channel.
import * as THREE from "three";
import { std } from "./world.js";
import { FONT } from "./textures.js";

const CW = 1024;
const CH = 720;
const SHOWN = 3; // posters on the sign itself
// the Supabase function that reads the channel (supabase/functions/watchlist-sync, deployed under this name)
const SYNC_FUNCTION = "swift-service";

const bridge = () => window.__tddBridge;

export class Watchlist {
  constructor({ world, scene, h, isGuest, onOpen, onClose }) {
    Object.assign(this, { world, scene, h, isGuest, onOpen, onClose });
    this.items = [];
    this.images = new Map(); // poster url -> loaded image
    this.state = isGuest ? "guest" : "loading";
    this.lastPull = 0;
    this.buildSign();
    this.buildUI();
    if (!isGuest) {
      this.load();
      this.listen();
    } else this.draw();
  }

  // ---- the sign, beside the cinema's screen on the right -----------------------------------
  buildSign() {
    const room = this.world.rooms.get("cinema");
    if (!room) return;
    room.group.updateMatrixWorld(true);
    const g = (this.group = new THREE.Group());
    const at = this.world.toWorld(room, 6.6, 0, 1.4);
    g.position.copy(at);
    g.rotation.y = room.group.rotation.y - 0.45; // turned a little toward the seats
    this.scene.add(g);
    const dark = std("#2b1830");
    const gold = std("#ffd166", { metalness: 0.5, roughness: 0.3 });
    const W = 2.6;
    const H = 1.83;
    const mesh = (geo, mat, x, y, z) => {
      const m = new THREE.Mesh(geo, mat);
      m.position.set(x, y, z);
      m.castShadow = true;
      m.receiveShadow = true;
      g.add(m);
      return m;
    };
    for (const s of [-1, 1]) mesh(new THREE.BoxGeometry(0.12, 2.4, 0.12), dark, (s * W) / 2 - s * 0.1, 1.2, -0.08);
    mesh(new THREE.BoxGeometry(W + 0.2, H + 0.2, 0.1), dark, 0, 2.15, -0.06);
    mesh(new THREE.BoxGeometry(W + 0.3, 0.08, 0.16), gold, 0, 2.15 + H / 2 + 0.12, -0.04);
    const c = (this.canvas = document.createElement("canvas"));
    c.width = CW;
    c.height = CH;
    this.tex = new THREE.CanvasTexture(c);
    this.tex.colorSpace = THREE.SRGBColorSpace;
    this.tex.anisotropy = 4;
    const face = mesh(new THREE.PlaneGeometry(W, H), new THREE.MeshBasicMaterial({ map: this.tex, toneMapped: false }), 0, 2.15, 0);
    face.castShadow = false;
    // little bulbs along the top, like the cinema's marquee
    const bulb = new THREE.SphereGeometry(0.045, 8, 6);
    this.bulbs = [std("#fff3c4", { emissive: "#ffcf6a", emissiveIntensity: 2, unique: true }), std("#fff3c4", { emissive: "#ffcf6a", emissiveIntensity: 0.5, unique: true })];
    for (let i = 0; i <= 14; i++) mesh(bulb, this.bulbs[i % 2], -W / 2 + (i / 14) * W, 2.15 + H / 2 + 0.2, 0.02).castShadow = false;
    this.world.animated.push((t) => {
      const on = Math.floor(t * 3) % 2;
      this.bulbs[0].emissiveIntensity = on ? 2.2 : 0.5;
      this.bulbs[1].emissiveIntensity = on ? 0.5 : 2.2;
    });
    for (const s of [-1, 1]) {
      const p = this.world.toWorld(room, 6.6 + s * 1.15 * Math.cos(-0.45), 0, 1.4 - s * 1.15 * Math.sin(-0.45));
      this.world.addCircle(p.x, p.z, 0.2);
    }
    // walk up and tap it to see everything
    // (the sign's spot in the world has to be worked out first, or "in front of it" is the
    // middle of the island and tapping it from afar walks you to the diary)
    g.updateMatrixWorld(true);
    const front = new THREE.Vector3(0, 0, 1.6).applyMatrix4(g.matrixWorld);
    // the whole sign is tappable, frame and posts too
    const item = { id: "watchlist", label: "see our watchlist 🍿", icon: "🍿", pos: front, radius: 2.4, action: { type: "watchlist" }, hits: [] };
    g.traverse((o) => {
      if (!o.isMesh) return;
      o.userData.item = item;
      item.hits.push(o);
    });
    this.world.interactables.push(item);
    this.signPos = g.position.clone();
    this.draw();
  }

  // ---- data -----------------------------------------------------------------------------------
  async load() {
    const sb = bridge()?.supabase;
    if (!sb) return;
    const { data, error } = await sb.from("watchlist").select("id, title, overview, poster_url, author, watched, posted_at").order("posted_at", { ascending: false }).limit(80);
    if (error) {
      // the table isn't there yet (not set up), or no connection
      this.state = "unset";
      this.draw();
      return;
    }
    this.items = data || [];
    this.state = "ready";
    this.draw();
    if (!this.el.hidden) this.renderList();
  }
  // a visitor can't read the table, so one of us sends the list over
  setRelayed(items) {
    if (!this.isGuest) return;
    this.items = items.filter((i) => i && typeof i.id === "string").slice(0, 40).map((i) => ({
      id: i.id,
      title: String(i.title || "").slice(0, 120),
      overview: String(i.overview || "").slice(0, 1200),
      poster_url: typeof i.poster_url === "string" && /^https:\/\//.test(i.poster_url) ? i.poster_url : null,
      author: String(i.author || "").slice(0, 40),
      watched: Boolean(i.watched),
      posted_at: String(i.posted_at || ""),
    }));
    this.state = "ready";
    this.draw();
    if (!this.el.hidden) this.renderList();
  }
  listen() {
    const sb = bridge()?.supabase;
    if (!sb) return;
    this.channel = sb
      .channel("watchlist-live")
      .on("postgres_changes", { event: "*", schema: "public", table: "watchlist" }, () => this.load())
      .subscribe();
  }
  // ask for a fresh read of the Discord channel (every few seconds while the island is open)
  pull() {
    if (this.isGuest || document.hidden || Date.now() - this.lastPull < 3000) return;
    this.lastPull = Date.now();
    bridge()?.supabase?.functions?.invoke(SYNC_FUNCTION, { body: {} }).catch(() => {});
  }
  // call each frame: while the island is open, keep asking for news (new posts then arrive live)
  update() {
    this.pull();
  }

  // newest first, but the ones we haven't watched yet come before the watched ones
  // one entry per show, tidied: IMDb-style link previews ("Clayface (2026) ⭐ 7.5 | Horror,
  // Sci-Fi" + "1h 48m | R") become a name plus details (year, rating, genres, runtime, age
  // rating); a link to something we also posted ourselves merges into our post. Newest
  // first, watched ones last.
  ordered() {
    const byShow = new Map();
    for (const it of [...this.items].sort((a, b) => Date.parse(a.posted_at) - Date.parse(b.posted_at))) {
      const p = parseShow(it.title, it.overview);
      const key = p.name.toLowerCase().replace(/[^\p{L}\p{N}]+/gu, " ").trim() || it.id;
      const had = byShow.get(key);
      if (!had) {
        byShow.set(key, { ...it, title: p.name, overview: p.overview, details: p.details });
        continue;
      }
      if (!had.poster_url && it.poster_url) had.poster_url = it.poster_url;
      if (!had.overview && p.overview) had.overview = p.overview;
      for (const [k, v] of Object.entries(p.details)) if (v && !had.details[k]) had.details[k] = v;
      had.watched = had.watched || it.watched;
      if (Date.parse(it.posted_at) > Date.parse(had.posted_at)) had.posted_at = it.posted_at;
    }
    return [...byShow.values()].sort((a, b) => Number(a.watched) - Number(b.watched) || Date.parse(b.posted_at) - Date.parse(a.posted_at));
  }
  image(url) {
    if (!url) return null;
    let img = this.images.get(url);
    if (!img) {
      img = new Image();
      img.crossOrigin = "anonymous";
      img.onload = () => this.draw();
      img.src = url;
      this.images.set(url, img);
    }
    return img.complete && img.naturalWidth ? img : null;
  }

  // ---- painting the sign ------------------------------------------------------------------------
  draw() {
    const x = this.canvas?.getContext("2d");
    if (!x) return;
    const bg = x.createLinearGradient(0, 0, 0, CH);
    bg.addColorStop(0, "#3a1f45");
    bg.addColorStop(1, "#22132b");
    x.fillStyle = bg;
    x.fillRect(0, 0, CW, CH);
    x.strokeStyle = "#ffd166";
    x.lineWidth = 8;
    x.strokeRect(14, 14, CW - 28, CH - 28);
    x.textAlign = "center";
    x.textBaseline = "middle";
    x.fillStyle = "#ffe6f0";
    x.shadowColor = "#ff6fa5";
    x.shadowBlur = 16;
    x.font = `700 58px ${FONT}`;
    x.fillText("˚₊‧ up next to watch ‧₊˚", CW / 2, 74);
    x.shadowBlur = 0;
    const note = (text) => {
      x.fillStyle = "#f3c7dd";
      x.font = `600 34px ${FONT}`;
      x.fillText(text, CW / 2, CH / 2 + 20);
    };
    if (this.state === "guest") return this.finish(note("this fills in when toto or dodo is on the island ♡"));
    if (this.state === "loading") return this.finish(note("getting our watchlist… ✿"));
    if (this.state === "unset") return this.finish(note("post in now-showing on discord ✿"));
    const list = this.ordered().filter((i) => !i.watched);
    if (!list.length) return this.finish(note(this.items.length ? "we've watched everything!! 🍿 post something new ✿" : "post in now-showing on discord ✿"));
    const shown = list.slice(0, SHOWN);
    const pw = 250;
    const ph = 370;
    const gap = 44;
    const x0 = (CW - (shown.length * pw + (shown.length - 1) * gap)) / 2;
    shown.forEach((item, i) => {
      const px = x0 + i * (pw + gap);
      const py = 136;
      x.fillStyle = "#fffaf6";
      x.fillRect(px - 8, py - 8, pw + 16, ph + 16);
      const img = this.image(item.poster_url);
      if (img) {
        // cover the frame, cropping the poster to fit
        const s = Math.max(pw / img.naturalWidth, ph / img.naturalHeight);
        const sw = pw / s;
        const sh = ph / s;
        x.drawImage(img, (img.naturalWidth - sw) / 2, (img.naturalHeight - sh) / 2, sw, sh, px, py, pw, ph);
      } else {
        const gr = x.createLinearGradient(px, py, px, py + ph);
        gr.addColorStop(0, "#ff8fb1");
        gr.addColorStop(1, "#b79be8");
        x.fillStyle = gr;
        x.fillRect(px, py, pw, ph);
        x.fillStyle = "#fffaf6";
        x.font = `700 110px ${FONT}`;
        x.fillText("♡", px + pw / 2, py + ph / 2);
      }
      x.fillStyle = "#fffaf6";
      x.font = `700 30px ${FONT}`;
      x.fillText(fit(x, item.title, pw + 30), px + pw / 2, py + ph + 44);
    });
    const more = list.length - shown.length;
    x.fillStyle = "#f3c7dd";
    x.font = `600 28px ${FONT}`;
    x.fillText(more > 0 ? `+${more} more · tap to see everything ✦` : "tap to see everything ✦", CW / 2, CH - 58);
    this.finish();
  }
  finish() {
    if (this.tex) this.tex.needsUpdate = true;
  }

  // ---- the full list ------------------------------------------------------------------------------
  buildUI() {
    const h = this.h;
    this.body = h("div", { class: "g3d-help-body g3d-wl-body" });
    this.el = h("div", { class: "g3d-overlay g3d-watchlist", hidden: true, role: "dialog", "aria-label": "our watchlist" },
      h("div", { class: "g3d-sheet" },
        h("header", { class: "g3d-panel-head" }, h("h2", { class: "g3d-sheet-title" }, "˚₊‧ our watchlist ‧₊˚"), h("button", { class: "g3d-close", type: "button", "aria-label": "close", onclick: () => this.close() }, "✕")),
        this.body,
      ),
    );
    for (const type of ["touchstart", "touchmove", "touchend"]) this.el.addEventListener(type, (e) => e.stopPropagation(), { passive: true });
    document.body.append(this.el);
  }
  isOpen() {
    return !this.el.hidden;
  }
  open() {
    this.onOpen?.();
    this.el.hidden = false;
    this.renderList();
    this.lastPull = 0;
    this.pull();
  }
  close() {
    if (this.el.hidden) return;
    this.el.hidden = true;
    this.onClose?.();
  }
  renderList() {
    const h = this.h;
    if (this.state === "guest") return this.body.replaceChildren(h("p", { class: "g3d-wl-empty" }, "this fills in when toto or dodo is on the island ♡"));
    if (this.state !== "ready" || !this.items.length) return this.body.replaceChildren(h("p", { class: "g3d-wl-empty" }, "nothing here yet ✿ post a poster and an overview in °｡⋆༘🎬°˖now-showing˖°🍿｡⋆༘° on discord and it shows up here"));
    const date = (s) => new Date(s).toLocaleDateString(undefined, { day: "numeric", month: "short" });
    this.body.replaceChildren(
      ...this.ordered().map((item) => {
        // a link post (IMDb etc.) has no story of its own: look one up
        if (!item.overview) {
          const found = findPlot(item.title, item.details, () => !this.el.hidden && this.renderList());
          if (found) item.overview = found;
        }
        return h("article", { class: `g3d-wl-item ${item.watched ? "watched" : ""}` },
          item.poster_url ? h("img", { src: item.poster_url, alt: "", loading: "lazy" }) : h("div", { class: "g3d-wl-noposter" }, "🍿"),
          h("div", { class: "g3d-wl-text" },
            h("h3", {}, item.title, item.watched ? h("span", { class: "g3d-wl-badge" }, "watched ✓") : null),
            detailLine(item.details) ? h("p", { class: "g3d-wl-details" }, detailLine(item.details)) : null,
            item.overview ? h("p", {}, item.overview) : null,
            h("small", {}, `${item.author ? `${item.author} · ` : ""}${date(item.posted_at)}`),
          ),
        );
      }),
    );
  }

  destroy() {
    this.channel && bridge()?.supabase?.removeChannel(this.channel);
    this.el.remove();
  }
}

// The short story of a show, from Wikipedia (IMDb link previews only carry runtime and
// age rating). Returns what's known now; when a lookup finishes, `done` runs once.
const plots = new Map();
const PLOT_KEY = "g3d-wl-plot:";
function findPlot(name, details = {}, done) {
  const key = `${name}|${details.year || ""}`.toLowerCase();
  if (plots.has(key)) return plots.get(key);
  try {
    const kept = localStorage.getItem(PLOT_KEY + key);
    if (kept !== null) return plots.set(key, kept).get(key);
  } catch {}
  plots.set(key, "");
  lookUpPlot(name, details)
    .then((text) => {
      plots.set(key, text);
      try {
        localStorage.setItem(PLOT_KEY + key, text);
      } catch {}
      if (text) done?.();
    })
    .catch(() => plots.delete(key)); // offline: try again next time
  return "";
}

const WIKI = "https://en.wikipedia.org/w/";
const bare = (s) => String(s).toLowerCase().replace(/\s*\([^)]*\)\s*$/, "").replace(/[^\p{L}\p{N}]+/gu, " ").trim();
async function lookUpPlot(name, d) {
  const series = /series|show/i.test(d.kind || "");
  const year = (d.year || "").slice(0, 4);
  const q = `${name} ${year} ${series ? "TV series" : "film"}`.replace(/\s+/g, " ");
  const found = await fetch(`${WIKI}rest.php/v1/search/page?q=${encodeURIComponent(q)}&limit=6`).then((r) => r.json());
  const want = bare(name);
  const page = (found.pages || []).find((p) => {
    const about = `${p.description || ""} ${p.title}`;
    return bare(p.title) === want && /film|movie|series|miniseries|show|anime/i.test(about) && (!year || !/\b(19|20)\d\d\b/.test(p.description || "") || (p.description || "").includes(year) || series);
  });
  if (!page) return "";
  const res = await fetch(`${WIKI}api.php?action=query&format=json&formatversion=2&origin=*&prop=extracts&explaintext=1&redirects=1&titles=${encodeURIComponent(page.title)}`).then((r) => r.json());
  return storyFrom(res?.query?.pages?.[0]?.extract || "");
}

// premise if there is one; else the lead's "In the film, …" line; else the plot's opening
function storyFrom(text) {
  const section = (name) => text.match(new RegExp(`\\n==\\s*(?:${name})\\s*==\\n+([\\s\\S]*?)(?:\\n==|$)`, "i"))?.[1].trim().split("\n")[0].replace(/\s+/g, " ");
  const sentences = (s, n) => (s.match(/[^.!?]+[.!?]+(?:["”’)]+)?/g) || [s]).slice(0, n).join(" ").trim();
  const clip = (s) => (s.length > 420 ? s.slice(0, 417).replace(/\s+\S*$/, "") + "…" : s);
  const premise = section("Premise|Synopsis|Overview");
  if (premise) return clip(sentences(premise, 3));
  const lead = text.split(/\n==/)[0];
  const line = lead.match(/(?:^|[.!?]\s+)((?:In the (?:film|series|show|story)|The (?:film|series|show|story) (?:follows|centers|centres|tells|is about|depicts)|It (?:follows|centers|centres|tells|depicts))[^.!?]*[.!?])/);
  if (line) return clip(line[1].replace(/^In the (?:film|series|show|story),\s*(\w)/, (_, c) => c.toUpperCase()));
  const plot = section("Plot|Story|Plot summary");
  if (plot) return clip(sentences(plot, 2));
  return "";
}

// IMDb (and friends) link previews pack everything into the title:
//   "Other Mommy (2026) ⭐ 5.3 | Horror, Thriller"   +   "1h 33m | R"
//   "Dark (TV Series 2017–2020) ⭐ 8.7 | Crime, Drama, Mystery"   +   "1h | TV-MA"
// Pull out the name, and keep the rest as tidy details; a real overview stays the overview.
export function parseShow(title, overview) {
  const details = { year: "", kind: "", rating: "", genres: "", runtime: "", cert: "" };
  let name = String(title || "").trim();
  const site = name.match(/\s+[-–—|]\s+(IMDb|Letterboxd|Netflix|Rotten Tomatoes|TMDB|The Movie Database).*$/i);
  if (site) name = name.slice(0, site.index);
  const paren = name.match(/\s*[(（]([^)）]*)[)）]/);
  if (paren) {
    const inside = paren[1].trim();
    const years = inside.match(/\d{4}(?:\s*[–-]\s*(?:\d{4})?)?/);
    if (years) details.year = years[0].replace(/\s+/g, "");
    const kind = inside.replace(years ? years[0] : "", "").trim();
    if (kind) details.kind = kind.replace(/\bSeries\b/, "series");
  }
  // the rating, then the genres (after a "|", or straight after the rating when the "|" was lost)
  const star = name.match(/[⭐★]\s*([\d.]+)\s*\|?\s*(.*)$/);
  if (star) {
    details.rating = star[1];
    if (star[2].trim()) details.genres = star[2].trim();
  }
  const bar = !details.genres && name.match(/\|\s*(.+)$/);
  if (bar) details.genres = bar[1].trim();
  if (paren) name = name.slice(0, paren.index);
  name = name.replace(/\s*[⭐★|·•].*$/, "").trim() || String(title || "").trim();
  // "1h 33m | R" (or "2h 1m | PG-13", "1h | TV-MA") is runtime and age rating, not an overview
  let text = String(overview || "").trim();
  const meta = text.match(/^((?:\d+h(?:\s*\d+m)?)|\d+m)?\s*\|?\s*([A-Z0-9][A-Z0-9-]{0,7})?\s*(?:\n|$)/);
  if (meta && (meta[1] || meta[2]) && meta[0].trim()) {
    details.runtime = meta[1] || "";
    details.cert = meta[2] || "";
    text = text.slice(meta[0].length).trim();
  }
  return { name, overview: text, details };
}

// the details as one tidy line: "2026 · ⭐ 7.5 · Horror, Sci-Fi · 1h 48m · R"
export function detailLine(d) {
  if (!d) return "";
  const when = d.kind ? `${d.kind} ${d.year}`.trim() : d.year;
  return [when, d.rating && `⭐ ${d.rating}`, d.genres, d.runtime, d.cert].filter(Boolean).join(" · ");
}

// shorten text to fit a width, with an ellipsis
function fit(x, text, max) {
  let s = String(text || "");
  if (x.measureText(s).width <= max) return s;
  while (s.length > 1 && x.measureText(s + "…").width > max) s = s.slice(0, -1);
  return s + "…";
}
