// ---- a tiny builder: lots of coloured pieces merged into one mesh -----------------------
const _e = new THREE.Euler(0, 0, 0, "YXZ");
const _q = new THREE.Quaternion();
const _c = new THREE.Color();
const mat4 = (x, y, z, rx, ry, rz, sx, sy, sz) => new THREE.Matrix4().compose(new THREE.Vector3(x, y, z), _q.setFromEuler(_e.set(rx, ry, rz)), new THREE.Vector3(sx, sy, sz));
const G = {
  stem: new THREE.CylinderGeometry(1, 1, 1, 5).translate(0, 0.5, 0),
  ball: new THREE.IcosahedronGeometry(1, 0),
  puff: new THREE.IcosahedronGeometry(1, 1),
  cone: new THREE.ConeGeometry(1, 1, 5).translate(0, 0.5, 0),
  blade: new THREE.ConeGeometry(1, 1, 3).translate(0, 0.5, 0),
  leaf: new THREE.OctahedronGeometry(1, 0).scale(0.19, 0.035, 0.5).translate(0, 0, 0.5),
  disc: new THREE.CylinderGeometry(1, 1, 1, 9),
  box: new THREE.BoxGeometry(1, 1, 1),
};

class Builder {
  constructor() {
    this.geos = [];
    this.stack = [new THREE.Matrix4()];
  }
  get m() {
    return this.stack[this.stack.length - 1];
  }
  // everything added inside fn sits at x, y, z, leaning rx toward its own +z after turning ry
  frame(x, y, z, rx, ry, fn, s = 1) {
    this.stack.push(this.m.clone().multiply(mat4(x, y, z, rx, ry, 0, s, s, s)));
    fn();
    this.stack.pop();
  }
  add(geo, color, x = 0, y = 0, z = 0, { rx = 0, ry = 0, rz = 0, s = 1, sx = 1, sy = 1, sz = 1 } = {}) {
    const g = geo.index ? geo.toNonIndexed() : geo.clone();
    g.applyMatrix4(this.m.clone().multiply(mat4(x, y, z, rx, ry, rz, s * sx, s * sy, s * sz)));
    g.deleteAttribute("uv");
    _c.set(color);
    const n = g.attributes.position.count;
    const col = new Float32Array(n * 3);
    for (let i = 0; i < n; i++) col.set([_c.r, _c.g, _c.b], i * 3);
    g.setAttribute("color", new THREE.BufferAttribute(col, 3));
    this.geos.push(g);
  }
  build() {
    const g = mergeGeometries(this.geos);
    for (const x of this.geos) x.dispose();
    g.computeBoundingSphere();
    return g;
  }
}

function rng(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const GREEN = "#6fb46a";
const DARK = "#4c9460";
const LIGHT = "#a3d68c";
const SAGE = "#9dbd9a";

// a stalk from the ground: fn then draws its head, standing on the stalk's tip
function stalk(b, x, z, h, lean, dir, r, color, fn) {
  b.frame(x, 0, z, lean, dir, () => {
    b.add(G.stem, color, 0, 0, 0, { sx: r, sy: h, sz: r });
    if (fn) b.frame(0, h, 0, 0, 0, fn);
  });
}
// a stalk that arches over: two pieces, the second leaning further
function arch(b, x, z, h, lean, dir, r, color, fn) {
  b.frame(x, 0, z, lean, dir, () => {
    b.add(G.stem, color, 0, 0, 0, { sx: r, sy: h * 0.6, sz: r });
    b.frame(0, h * 0.6, 0, lean * 1.6 + 0.35, 0, () => {
      b.add(G.stem, color, 0, 0, 0, { sx: r * 0.8, sy: h * 0.4, sz: r * 0.8 });
      if (fn) b.frame(0, h * 0.4, 0, 0, 0, fn);
    });
  });
}
function petals(b, n, len, w, color, tilt = 0.25, off = 0, thick = 0.14) {
  for (let i = 0; i < n; i++) b.frame(0, 0, 0, -tilt, off + (i / n) * TAU, () => b.add(G.ball, color, 0, 0, len * 0.55, { sx: w, sy: len * thick, sz: len * 0.5 }));
}
function leaves(b, n, len, color, tilt = 0.5, off = 0, y = 0) {
  for (let i = 0; i < n; i++) b.add(G.leaf, color, 0, y, 0, { ry: off + (i / n) * TAU, rx: -tilt, s: len });
}
function blades(b, R, n, h0, h1, lean0, lean1, colors, spread = 0.12, w = 0.022) {
  for (let i = 0; i < n; i++) {
    const a = R() * TAU;
    const d = Math.sqrt(R()) * spread;
    b.frame(Math.sin(a) * d, 0, Math.cos(a) * d, lean0 + R() * (lean1 - lean0), a + (R() - 0.5), () => b.add(G.blade, colors[i % colors.length], 0, 0, 0, { sx: w, sy: h0 + R() * (h1 - h0), sz: w * 0.5 }));
  }
}
// where the stalks of a clump stand: n of them, spread round the middle
function clump(R, n, spread, fn) {
  for (let i = 0; i < n; i++) {
    const a = (i / n) * TAU + R() * 0.8;
    const d = n === 1 ? 0 : spread * (0.45 + R() * 0.55);
    fn(Math.sin(a) * d, Math.cos(a) * d, a, i);
  }
}

