const BARK = "#8a5a3c";
// a cloud of puffs round c: the leafy (or flowery) top of a tree. Returns the puffs (in the
// builder's own space) so blossoms and fruit can be set right on their surface
function canopy(b, R, cx, cy, cz, rad, n, cols, s0, s1, squash = 0.85) {
  const out = [];
  for (let i = 0; i < n; i++) {
    const a = R() * TAU;
    const up = R() * 0.9 - 0.25;
    const d = rad * (0.35 + R() * 0.6);
    const s = s0 + R() * (s1 - s0);
    const x = cx + Math.sin(a) * d * Math.cos(up), y = cy + Math.sin(up) * rad * 0.6, z = cz + Math.cos(a) * d * Math.cos(up);
    b.add(G.puff, cols[i % cols.length], x, y, z, { sx: s, sy: s * squash, sz: s, ry: R() * 3 });
    out.push({ c: new THREE.Vector3(x, y, z).applyMatrix4(b.m), r: s, sq: squash });
  }
  return out;
}
const _d = new THREE.Vector3();
const _p = new THREE.Vector3();
// a point on the outside of the canopy: on one puff's skin, facing out (lo..hi is how far up
// it may face) and not buried inside a neighbouring puff
function onCanopy(R, puffs, lo, hi, sink = 0.94) {
  for (let t = 0; t < 14; t++) {
    const p = puffs[Math.floor(R() * puffs.length)];
    _d.set(R() - 0.5, 0, R() - 0.5).normalize();
    const y = lo + R() * (hi - lo);
    _d.multiplyScalar(Math.sqrt(1 - y * y)).setY(y);
    _p.set(_d.x * p.r * sink, _d.y * p.r * p.sq * sink, _d.z * p.r * sink).add(p.c);
    const hidden = puffs.some((o) => o !== p && ((_p.x - o.c.x) / o.r) ** 2 + ((_p.y - o.c.y) / (o.r * o.sq)) ** 2 + ((_p.z - o.c.z) / o.r) ** 2 < 0.8);
    if (!hidden) return _p;
  }
  return _p;
}
// little blossoms dotted over the outside of a canopy, sitting on it
function dots(b, R, puffs, n, cols, s, lo = -0.1) {
  for (let i = 0; i < n; i++) {
    const v = onCanopy(R, puffs, lo, 1);
    b.add(G.puff, cols[i % cols.length], v.x, v.y, v.z, { s });
  }
}
// fruit hanging round the sides and underneath, each on a little stalk tucked into the leaves
function fruitDots(b, R, puffs, n, col) {
  for (let i = 0; i < n; i++) {
    const v = onCanopy(R, puffs, -0.75, 0.35, 0.98);
    const { x, y, z } = v;
    b.add(G.puff, col, x, y - 0.06, z, { sx: 0.11, sy: 0.1, sz: 0.11 });
    b.add(G.stem, "#6a4430", x, y + 0.02, z, { sx: 0.012, sy: 0.07, sz: 0.012 });
    b.add(G.leaf, GREEN, x, y + 0.07, z, { ry: R() * 6, rx: -0.4, s: 0.09 });
  }
}
// a trunk that splits into n branches; fn(branch) is called at each branch tip
function trunk(b, R, h, r, col, n, spread, len, fn) {
  b.add(G.disc, col, 0, 0.05, 0, { sx: r * 1.9, sy: 0.1, sz: r * 1.9 });
  b.add(G.stem, col, 0, 0, 0, { sx: r, sy: h, sz: r });
  for (let k = 0; k < n; k++) {
    b.frame(0, h * (0.82 + R() * 0.15), 0, spread * (0.75 + R() * 0.5), (k / n) * TAU + R() * 0.6, () => {
      b.add(G.stem, col, 0, 0, 0, { sx: r * 0.55, sy: len, sz: r * 0.55 });
      b.frame(0, len, 0, 0, 0, () => fn?.(k));
    });
  }
}

