    b.add(G.puff, "#7a5238", 0, 0, 0, { sx: 0.2, sy: 0.07, sz: 0.2 });
    b.add(G.box, "#e8d2b0", 0.18, 0.16, 0.12, { sx: 0.022, sy: 0.32, sz: 0.012 });
    b.add(G.box, "#fffaf2", 0.18, 0.3, 0.127, { sx: 0.12, sy: 0.1, sz: 0.012 });
