      ...youngTrees.slice(0, 3).map((v) => row("🌳", v.kind.name, `fully grown in ${fmtTime(v.left)}`)),
      ...fruitSoon.slice(0, 3).map((v) => row(v.kind.fruitEmoji, `${v.kind.fruitName} on the ${v.kind.name}`, `ripe in ${fmtTime(v.fruitIn)}`)),
