  // ---- shared bits of building -----------------------------------------------------------
  // a watering can that tips over whatever you're watering, with drops
  makeKit(parent, canGeo) {
    const can = new THREE.Group();
    can.add(new THREE.Mesh(canGeo, plantMat));
    can.visible = false;
    parent.add(can);
    const drops = [];
    const dropGeo = new THREE.IcosahedronGeometry(0.03, 0);
    const dropMat = std("#8fd3f0", { emissive: "#8fd3f0", emissiveIntensity: 0.5 });
    for (let k = 0; k < 8; k++) {
      const d = new THREE.Mesh(dropGeo, dropMat);
      d.visible = false;
      parent.add(d);
      drops.push(d);
    }
    return { can, drops, job: null };
  }
  pour(kit, x, y, z) {
    kit.job = { x, y: y + 0.45, z, t: 0 };
  }
  stepKit(kit, dt) {
    const p = kit.job;
    if (!p) return;
    p.t += dt;
    const k = Math.min(1, p.t / 0.25) * (p.t > 1.15 ? Math.max(0, 1 - (p.t - 1.15) / 0.2) : 1);
    kit.can.visible = true;
    kit.can.position.set(p.x - 0.42, p.y, p.z);
    kit.can.rotation.z = -0.75 * k;
    kit.can.scale.setScalar(1.25 * Math.max(0.01, k));
    kit.drops.forEach((d, n) => {
      const u = (p.t * 1.9 + n / kit.drops.length) % 1;
      d.visible = p.t > 0.2 && p.t < 1.2;
      d.position.set(p.x + 0.02 + Math.sin(n * 2.4) * 0.12 + u * 0.1, p.y - 0.05 - u * (p.y - 0.25), p.z + Math.cos(n * 1.9) * 0.14);
    });
    if (p.t > 1.35) {
      kit.job = null;
      kit.can.visible = false;
      for (const d of kit.drops) d.visible = false;
    }
  }
